def _graph_noise(v, t):
    if not v:
        return True
    vl = v.strip().lower()
    if vl in GRAPH_STOP:
        return True
    # ORGANIZATION toda em maiúsculas = cabeçalho/termo jurídico, não empresa real
    if t == "ORGANIZATION" and any(c.isalpha() for c in v) and v == v.upper():
        return True
    return False

