# ---- estado persistente: instruções globais + skills (department copilots) ----
APPSTATE_PATH = os.getenv("APPSTATE_PATH", "/data/appstate.json")
_appstate_lock = threading.Lock()


def _appstate_load():
    try:
        with open(APPSTATE_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def _appstate_save(d):
    with _appstate_lock:
        os.makedirs(os.path.dirname(APPSTATE_PATH), exist_ok=True)
        tmp = APPSTATE_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
        os.replace(tmp, APPSTATE_PATH)


APPSTATE = _appstate_load()


def _skills():
    return APPSTATE.get("skills", [])


def _skill_ids(body):
    """Extrai a lista de skills do request (multi 'skill_ids' tem prioridade; cai p/ 'skill_id' único)."""
    ids = list(getattr(body, "skill_ids", None) or [])
    if not ids and getattr(body, "skill_id", None):
        ids = [body.skill_id]
    return [i for i in ids if i]


def _skills_combinar(ids):
    """Combina 1+ skills num único system prompt (aplica TODAS). Retorna (system, nomes, colecoes)."""
    sel = []
    for i in (ids or []):
        s = next((x for x in _skills() if x.get("id") == i), None)
        if s and s not in sel:
            sel.append(s)
    if not sel:
        return None, "", []
    cols = [s["colecao"] for s in sel if s.get("colecao")]
    if len(sel) == 1:
        return (sel[0].get("prompt") or None), sel[0].get("nome", ""), cols
    partes = [f"[SKILL {n} — {s.get('nome', '')}]\n{s.get('prompt', '')}" for n, s in enumerate(sel, 1)]
    system = ("Você opera com MÚLTIPLAS skills ao mesmo tempo. Aplique TODAS as personas abaixo em conjunto: "
              "cumpra o método e o formato de cada uma; havendo conflito, priorize a instrução mais específica "
              "e combine os formatos de saída de forma coerente.\n\n" + "\n\n".join(partes))
    return system, " + ".join(s.get("nome", "") for s in sel), cols


