    _seed_agentes_exemplo()                                     # agentes prontos (Excel/Word/PPT/SharePoint), idempotente
    _auth_seed()                                                # garante que o admin tem senha (gera e loga se preciso)
    threading.Thread(target=lambda: (time.sleep(8), _llms_pagas_reaplicar()), daemon=True).start()  # re-registra LLMs pagas no gateway
    threading.Thread(target=_anexo_loop, daemon=True).start()   # rotina de expiração dos anexos de chat
