# ---------------- PII masking ----------------
def mask_pii(text: str) -> dict:
    r = httpx.post(f"{PII_URL}/mask", json={"text": text}, timeout=120)
    r.raise_for_status()
    return r.json()


# Siglas/termos de domínio que o NER pt marca erroneamente como PERSON — NÃO devem ser mascarados
# (mascará-los degradava respostas externas, ex.: "LGPD é um identificador opaco que representa uma pessoa").
_MASK_ALLOW = {"LGPD", "ABA", "TEA", "TCC", "SOAP", "PTI", "TDAH", "TOC", "CID", "DSM", "PCD",
               "CFP", "CFM", "OAB", "SUS", "CNJ", "STF", "STJ", "TCU", "CLT", "CID-11",
               "RBAC", "API", "APIs", "MVP", "SaaS", "SLA", "UX", "UI", "TI", "IA", "SQL", "JWT",
               "HTML", "CSS", "PDF", "OKR", "SWOT", "KPI", "ROI", "CRM", "ERP", "CPF", "CNPJ", "RG",
               "Cerne", "Orqion"}


def _mask_ok(e, text):
    """True se a entidade DEVE ser mascarada. Descarta falso-positivo de NER: siglas de domínio e
    tokens curtos em CAIXA-ALTA marcados como PERSON (ex.: LGPD/ABA/TEA), preservando CPF/e-mail/telefone."""
    if e.get("type") not in _HIGHRISK_PII:
        return False
    if e.get("type") == "PERSON":
        val = text[e["start"]:e["end"]].strip()
        if val in _MASK_ALLOW:
            return False
        if re.fullmatch(r"[A-ZÇÃÉÁÍÓÚÊÔ0-9][A-ZÇÃÉÁÍÓÚÊÔ0-9./\-]{1,6}", val):   # sigla curta em caixa alta
            return False
    return True


def mask_reversible(text: str):
    """Mascara com tokens ÚNICOS e reversíveis. Retorna (texto_mascarado, mapa_local).
    O mapa token->valor NUNCA sai da máquina — é usado só para de-mascarar a resposta."""
    ents = [e for e in mask_pii(text)["entities_found"] if _mask_ok(e, text)]
    # só mascara identificadores de ALTO RISCO (CPF/CNPJ/e-mail/telefone...) antes de sair p/ o externo;
    # evita destruir a pergunta mascarando termos técnicos (ex.: "RAG"→ORG). O contexto do acervo já
    # vem mascarado da ingestão. Ver _HIGHRISK_PII.
    ents = sorted(ents, key=lambda e: (e["start"], -(e["end"] - e["start"])))
    chosen, last_end = [], -1
    for e in ents:
        if e["start"] >= last_end:
            chosen.append(e)
            last_end = e["end"]
    counters, spans, mapping = {}, [], {}
    for e in sorted(chosen, key=lambda e: e["start"]):
        t = e["type"]
        counters[t] = counters.get(t, 0) + 1
        token = f"[{t}_{counters[t]}]"
        mapping[token] = text[e["start"]:e["end"]]
        spans.append((e["start"], e["end"], token))
    masked = text
    for start, end, token in sorted(spans, key=lambda s: s[0], reverse=True):
        masked = masked[:start] + token + masked[end:]
    return masked, mapping


def demask(text: str, mapping: dict) -> str:
    # substitui do token mais longo p/ o mais curto: evita [PERSON_1] corromper [PERSON_11]
    for token, original in sorted(mapping.items(), key=lambda kv: len(kv[0]), reverse=True):
        text = text.replace(token, original)
    return text


def _mask_conv(msgs, mapping=None):
    """Mascara uma lista de mensagens (histórico) p/ envio externo, com tokens CONSISTENTES
    (mesmo valor -> mesmo token) acumulando num único 'mapping'. Retorna (msgs_mascaradas, mapping).
    Assim o provedor externo recebe a conversa sem PII, e a de-mascaração usa o mapa combinado."""
    mapping = dict(mapping or {})
    val2tok = {v: k for k, v in mapping.items()}
    counters = {}
    for tok in mapping:                                        # continua a numeração dos tokens já existentes
        t = tok.strip("[]").rsplit("_", 1)[0]
        try:
            counters[t] = max(counters.get(t, 0), int(tok.strip("[]").rsplit("_", 1)[1]))
        except Exception:
            pass
    out = []
    for m in (msgs or []):
        text = m.get("content", "") or ""
        if not isinstance(text, str):
            out.append(m); continue
        try:
            ents = [e for e in mask_pii(text)["entities_found"] if _mask_ok(e, text)]
        except Exception:
            ents = []
        ents = sorted(ents, key=lambda e: (e["start"], -(e["end"] - e["start"])))
        chosen, last = [], -1
        for e in ents:
            if e["start"] >= last:
                chosen.append(e); last = e["end"]
        spans = []
        for e in sorted(chosen, key=lambda e: e["start"]):
            val = text[e["start"]:e["end"]]
            tok = val2tok.get(val)
            if not tok:
                t = e["type"]; counters[t] = counters.get(t, 0) + 1
                tok = f"[{t}_{counters[t]}]"; mapping[tok] = val; val2tok[val] = tok
            spans.append((e["start"], e["end"], tok))
        masked = text
        for s, en, tok in sorted(spans, key=lambda x: x[0], reverse=True):
            masked = masked[:s] + tok + masked[en:]
        out.append({"role": m.get("role", "user"), "content": masked})
    return out, mapping


# ---------------- grafo de entidades (Neo4j, RAG híbrido) ----------------
# As entidades REAIS ficam só no Neo4j local (dentro do servidor soberano, nunca
# saem). O Qdrant continua guardando apenas o texto MASCARADO.
_neo4j = None


def _graph_driver():
    global _neo4j
    if _neo4j is None and NEO4J_URL:
        try:
            from neo4j import GraphDatabase
            _neo4j = GraphDatabase.driver(NEO4J_URL, auth=(NEO4J_USER, NEO4J_PASS),
                                          connection_timeout=5, connection_acquisition_timeout=5,
                                          max_transaction_retry_time=5)   # falha rápido se o grafo cair (não trava /stats)
        except Exception as ex:
            print("[cerne] neo4j indisponível:", ex)
            return None
    return _neo4j


def _real_entities(text: str, entities_found: list):
    """Valores reais das entidades (dos offsets sobre o texto original)."""
    out = []
    for e in entities_found:
        if e["type"] in GRAPH_TYPES:
            val = text[e["start"]:e["end"]].strip()
            if len(val) > 1 and not _graph_noise(val, e["type"]):
                out.append((val, e["type"]))
    return out


def _graph_add(source: str, entities: list):
    global _neo4j
    drv = _graph_driver()
    if not drv:
        return
    try:
        with drv.session() as s:
            s.run("MERGE (d:Document {source:$s})", s=source)
            for val, typ in entities:
                s.run("MERGE (e:Entity {value:$v, type:$t}) "
                      "MERGE (d:Document {source:$s}) "
                      "MERGE (d)-[:MENTIONS]->(e)", v=val, t=typ, s=source)
    except Exception as ex:
        print("[cerne] grafo (add):", ex)
        _neo4j = None                             # descarta driver quebrado p/ reconectar na próxima escrita


def _graph_sources(question: str):
    """Documentos conectados às entidades citadas na pergunta."""
    drv = _graph_driver()
    if not drv:
        return set()
    try:
        vals = [v for v, _ in _real_entities(question, mask_pii(question)["entities_found"])]
        if not vals:
            return set()
        with drv.session() as s:
            rows = s.run("MATCH (d:Document)-[:MENTIONS]->(e:Entity) "
                         "WHERE e.value IN $vals RETURN DISTINCT d.source AS src", vals=vals).data()
        return {r["src"] for r in rows}
    except Exception:
        return set()


def _graph_counts():
    drv = _graph_driver()
    if not drv:
        return None
    try:
        with drv.session() as s:
            docs = s.run("MATCH (d:Document) RETURN count(d) AS c").single()["c"]
            ents = s.run("MATCH (e:Entity) RETURN count(e) AS c").single()["c"]
            rels = s.run("MATCH ()-[r:MENTIONS]->() RETURN count(r) AS c").single()["c"]
        return {"documentos": docs, "entidades": ents, "relacoes": rels}
    except Exception:
        return None


# ---------------- modelos (via gateway) ----------------
def embed(text: str) -> list:
    r = httpx.post(f"{GATEWAY_URL}/v1/embeddings", headers=HEADERS,
                   json={"model": EMBED_ALIAS, "input": text}, timeout=600)
    r.raise_for_status()
    return r.json()["data"][0]["embedding"]


def embed_many(texts: list) -> list:
    """Embeddings em LOTE (uma chamada p/ vários textos) — muito mais rápido em CPU que 1 a 1."""
    if not texts:
        return []
    r = httpx.post(f"{GATEWAY_URL}/v1/embeddings", headers=HEADERS,
                   json={"model": EMBED_ALIAS, "input": texts}, timeout=900)
    r.raise_for_status()
    data = sorted(r.json()["data"], key=lambda d: d.get("index", 0))   # preserva a ordem dos trechos
    return [d["embedding"] for d in data]


# ─────────────────────────────────────────────────────────────────────────────
# PLANO DE GATEWAY · Cache semântico
# Perguntas semanticamente parecidas → reaproveita a mesma resposta (corta custo/latência).
# Chave por (org · coleções · skill · modelo · hash-da-memória) para não misturar contextos.
# ─────────────────────────────────────────────────────────────────────────────
import math as _math
_SEMCACHE: dict = {}          # chave -> [ {emb, q, ans, fontes, ancoragem, ts} ]
_SEMCACHE_TTL = 1800          # 30 min
_SEMCACHE_SIM = 0.93          # limiar de similaridade de cosseno
_SEMCACHE_MAX = 200           # itens por chave
_SEMCACHE_HITS = {"hit": 0, "miss": 0}

def _cos_sim(a: list, b: list) -> float:
    if not a or not b or len(a) != len(b):
        return 0.0
    dot = sum(x * y for x, y in zip(a, b))
    na = _math.sqrt(sum(x * x for x in a)); nb = _math.sqrt(sum(y * y for y in b))
    return dot / (na * nb) if na and nb else 0.0

def _cache_ativo() -> bool:
    try:
        return _org().get("cache_semantico", True) is not False and not _org().get("busca_web")
    except Exception:
        return True

def _cache_chave(colls, skill_id, model) -> str:
    try:
        org = _tenant()
    except Exception:
        org = "default"
    try:
        memh = str(abs(hash(_memoria_bloco())) % (10 ** 8)) if _memoria_ativa() else "0"
    except Exception:
        memh = "0"
    try:
        modo = _org().get("soberania", "soberano")
    except Exception:
        modo = "soberano"
    cols = ",".join(sorted(colls or []))
    return f"{org}|{modo}|{cols}|{skill_id or ''}|{model or 'chat'}|{memh}"

def _cache_get(q: str, chave: str):
    if not _cache_ativo() or not q:
        return None
    lst = _SEMCACHE.get(chave)
    if not lst:
        return None
    now = time.time()
    lst[:] = [e for e in lst if now - e["ts"] < _SEMCACHE_TTL]
    if not lst:
        return None
    try:
        qe = embed(q)
    except Exception:
        return None
    best, bs = None, 0.0
    for e in lst:
        c = _cos_sim(qe, e["emb"])
        if c > bs:
            bs, best = c, e
    if best and bs >= _SEMCACHE_SIM:
        _SEMCACHE_HITS["hit"] += 1
        best["_sim"] = round(bs, 3)
        return best
    _SEMCACHE_HITS["miss"] += 1
    return None

def _cache_put(q: str, chave: str, ans: str, fontes=None, ancoragem="na"):
    if not _cache_ativo() or not q or not ans:
        return
    # não cacheia recusas/erros
    if len(ans.strip()) < 12:
        return
    try:
        qe = embed(q)
    except Exception:
        return
    lst = _SEMCACHE.setdefault(chave, [])
    lst.append({"emb": qe, "q": q, "ans": ans, "fontes": fontes or [], "ancoragem": ancoragem, "ts": time.time()})
    if len(lst) > _SEMCACHE_MAX:
        del lst[0:len(lst) - _SEMCACHE_MAX]

def _cache_limpar_org():
    """Invalida o cache da org (ao ingerir/reindexar ou mexer na memória)."""
    try:
        org = _tenant()
    except Exception:
        return
    for k in [k for k in _SEMCACHE if k.startswith(org + "|")]:
        _SEMCACHE.pop(k, None)


def chat_model(model: str, messages: list, max_tokens: int = 1024) -> str:
    r = httpx.post(f"{GATEWAY_URL}/v1/chat/completions", headers=HEADERS,
                   json={"model": model, "messages": messages,
                         "temperature": 0.2, "max_tokens": max_tokens}, timeout=600)
    r.raise_for_status()
    return r.json()["choices"][0]["message"]["content"]


def _chat_completo(model, messages, max_tokens=1024, conts=2):
    """Gera a resposta COMPLETA: se o modelo parar por LIMITE de tokens (finish_reason=length), pede
    'continue' e concatena — entrega planos/sites/código inteiros sem truncar, gastando tokens extras só
    quando realmente precisa. Corrige o GAP P0 de forma robusta (independe do tamanho do entregável)."""
    full = ""
    msgs = list(messages)
    for _ in range(max(1, conts + 1)):
        r = httpx.post(f"{GATEWAY_URL}/v1/chat/completions", headers=HEADERS,
                       json={"model": model, "messages": msgs, "temperature": 0.2, "max_tokens": max_tokens},
                       timeout=900)
        r.raise_for_status()
        ch = r.json()["choices"][0]
        part = ch.get("message", {}).get("content") or ""
        full += part
        if ch.get("finish_reason") != "length":            # terminou naturalmente → pronto
            break
        msgs = msgs + [{"role": "assistant", "content": part},
                       {"role": "user", "content": "Continue EXATAMENTE de onde parou, sem repetir nada já escrito e sem reintroduzir."}]
    return full


_GEN_RE = re.compile(r"\b(planej|arquitet|document|pol[íi]tica|contrato|requisit|manual|relat[óo]ri|"
                     r"implement|escrev|c[óo]digo|script|gere|gerar|monte|montar|elabor|desenvolv|"
                     r"proposta|plano|especifica|roteiro|redij|crie|criar|detalh|passo a passo|checklist)", re.I)


def _max_tokens_for(text, base=2048, gen=8192):
    """Teto adaptativo de saída: pedidos de 'gerar/planejar/código/documento' precisam de MUITO mais que
    1024 tokens (senão truncam no meio). 8192 dá folga p/ sites/planos/código completos. GAP P0 do relatório."""
    return gen if _GEN_RE.search(text or "") else base


def _chat_resiliente(model, messages, max_tokens=1024, fallback="chat"):
    """chat_model tolerante a 429/erros do provedor: tenta o modelo pedido e, se falhar (rate limit,
    indisponibilidade), cai para o modelo LOCAL soberano — que não tem rate limit. NUNCA levanta exceção.
    Impede que uma subtarefa/planejador/síntese com 429 derrube a orquestração inteira."""
    tentativas = [model] if model == fallback else [model, fallback]
    for i, m in enumerate(tentativas):
        try:
            return chat_model(m, messages, max_tokens=max_tokens)
        except Exception as ex:
            if i < len(tentativas) - 1:
                time.sleep(0.5)                              # provável 429 transitório → respira e cai p/ local
            else:
                print(f"[cerne] orquestrador: '{m}' falhou ({str(ex)[:70]})")
    return ""


def chat(messages: list) -> str:
    return chat_model(CHAT_ALIAS, messages)


def _gen_call(messages, max_tokens=2000):
    """Chamada de geração (documento/site) com mais tokens; retorna (texto, total_tokens reais)."""
    r = httpx.post(f"{GATEWAY_URL}/v1/chat/completions", headers=HEADERS,
                   json={"model": "chat", "messages": messages, "temperature": 0.3, "max_tokens": max_tokens}, timeout=900)
    r.raise_for_status()
    j = r.json()
    return j["choices"][0]["message"]["content"], (j.get("usage") or {}).get("total_tokens")


def _stream_tokens(messages, model=None):
    with httpx.stream("POST", f"{GATEWAY_URL}/v1/chat/completions", headers=HEADERS,
                      json={"model": model or CHAT_ALIAS, "messages": messages, "temperature": 0.2,
                            "max_tokens": 1024, "stream": True}, timeout=600) as r:
        r.raise_for_status()
        for line in r.iter_lines():
            if not line or not line.startswith("data: "):
                continue
            data = line[6:]
            if data.strip() == "[DONE]":
                break
            try:
                delta = json.loads(data)["choices"][0]["delta"].get("content")
            except Exception:
                delta = None
            if delta:
                yield delta


def _web_search(query, n=5):
    """Busca na web via SearXNG self-hosted. A CONSULTA sai da máquina — é opt-in (org.busca_web)."""
    if not SEARXNG_URL:
        return "", []
    try:
        r = httpx.get(f"{SEARXNG_URL}/search",
                      params={"q": query, "format": "json", "language": "pt-BR", "safesearch": 0},
                      timeout=20)
        res = (r.json().get("results") or [])[:n]
    except Exception:
        return "", []
    linhas, fontes = [], []
    for x in res:
        t = (x.get("title") or "").strip()
        u = (x.get("url") or "").strip()
        c = (x.get("content") or "").strip()
        if not t:
            continue
        linhas.append(f"- {t}\n  {u}\n  {c}")
        fontes.append({"source": "🌐 " + t[:60], "trecho": (c or u)[:200], "score": ""})
    if not linhas:
        return "", []
    return ("[RESULTADOS DA WEB — resultados atuais de uma busca; use se forem relevantes e "
            "cite a fonte (URL)]\n" + "\n".join(linhas)), fontes


# ---------------- ingestão ----------------
def chunk_text(text: str, size: int = 600, overlap: int = 80):
    words = text.split()
    out, i = [], 0
    while i < len(words):
        piece = " ".join(words[i:i + size]).strip()
        if piece:
            out.append(piece)
        i += size - overlap
    return out


IMG_EXT = (".png", ".jpg", ".jpeg", ".webp", ".bmp", ".tif", ".tiff", ".gif")

_VISION_OK = {"v": None, "ts": 0.0}   # cache leve da disponibilidade (evita bater no ollama a cada imagem)


def _vision_available() -> bool:
    """True se o modelo de visão local estiver baixado no Ollama (checagem cacheada por 60s)."""
    if not VISION_ENABLED:
        return False
    if _VISION_OK["v"] is not None and (time.time() - _VISION_OK["ts"]) < 60:
        return _VISION_OK["v"]
    try:
        names = [m.get("name", "") for m in httpx.get(f"{OLLAMA_URL}/api/tags", timeout=8).json().get("models", [])]
        base = VISION_MODEL.split(":")[0]
        ok = any(n == VISION_MODEL or n.split(":")[0] == base for n in names)
    except Exception:
        ok = False
    _VISION_OK["v"] = ok; _VISION_OK["ts"] = time.time()
    return ok


def _vision_describe(raw: bytes, prompt: str = "") -> str:
    """Descreve/analisa uma imagem com o VLM LOCAL (100% soberano — a imagem nunca sai da máquina)."""
    import base64
    b64 = base64.b64encode(raw).decode()
    p = prompt or ("Descreva esta imagem em português, de forma detalhada e fiel. "
                   "Se houver texto, tabelas, gráficos ou diagramas, transcreva e explique o conteúdo. "
                   "Não invente nada que não esteja visível na imagem.")
    r = httpx.post(f"{OLLAMA_URL}/api/chat", timeout=600,
                   json={"model": VISION_MODEL, "stream": False,
                         "messages": [{"role": "user", "content": p, "images": [b64]}],
                         "options": {"temperature": 0.2}})
    r.raise_for_status()
    return ((r.json().get("message") or {}).get("content") or "").strip()


def extract_text(filename: str, raw: bytes) -> str:
    fn = filename.lower()
    if fn.endswith(".pdf"):
        reader = PdfReader(io.BytesIO(raw))
        return "\n".join((p.extract_text() or "") for p in reader.pages)
    if fn.endswith(IMG_EXT):                              # imagem/scan -> OCR (Tesseract) + visão local (VLM)
        import pytesseract
        from PIL import Image
        try:
            ocr = pytesseract.image_to_string(Image.open(io.BytesIO(raw)), lang="por+eng").strip()
        except Exception:
            ocr = ""
        desc = ""
        if _vision_available():                          # entendimento visual: gráficos, tabelas, fotos, diagramas
            try:
                desc = _vision_describe(raw)
            except Exception:
                desc = ""
        partes = []
        if ocr:
            partes.append("[Texto extraído por OCR]\n" + ocr)
        if desc:
            partes.append("[Descrição visual — modelo de visão local]\n" + desc)
        return "\n\n".join(partes)
    return raw.decode("utf-8", errors="ignore")


_INGEST_EXT = (".pdf", ".txt", ".md", ".csv", ".json", ".log", ".html", ".xml", ".yaml", ".yml") + IMG_EXT


def _is_ingestable(name):
    return (name or "").lower().endswith(_INGEST_EXT)


def _expand_archive(filename, raw):
    """Retorna [(nome, bytes)] dos arquivos dentro de zip/tar/rar/7z; [] se não for compactado."""
    fn = (filename or "").lower()
    out = []
    try:
        if fn.endswith(".zip"):
            import zipfile
            z = zipfile.ZipFile(io.BytesIO(raw))
            for n in z.namelist():
                if not n.endswith("/") and "__MACOSX" not in n:
                    out.append((n.split("/")[-1] or n, z.read(n)))
        elif fn.endswith((".tar", ".tar.gz", ".tgz", ".tar.bz2")):
            import tarfile
            t = tarfile.open(fileobj=io.BytesIO(raw))
            for m in t.getmembers():
                if m.isfile():
                    out.append((m.name.split("/")[-1] or m.name, t.extractfile(m).read()))
        elif fn.endswith(".rar"):
            import rarfile
            r = rarfile.RarFile(io.BytesIO(raw))
            for n in r.namelist():
                if not r.getinfo(n).isdir():
                    out.append((n.split("/")[-1] or n, r.read(n)))
        elif fn.endswith(".7z"):
            import py7zr
            with py7zr.SevenZipFile(io.BytesIO(raw)) as z:
                for n, bio in z.readall().items():
                    out.append((n.split("/")[-1] or n, bio.read()))
    except Exception as ex:
        raise HTTPException(status_code=400, detail=f"falha ao abrir o arquivo compactado: {str(ex)[:120]}")
    return out


def _ingest(text: str, source: str, coll: str = COLLECTION) -> dict:
    coll = coll or COLLECTION
    if not _org_can_write(coll):                    # isolamento: não ingere em coleção de outra org
        raise HTTPException(status_code=403, detail="coleção não pertence à sua organização")
    novo = not _coll_exists(coll)
    _ensure_collection(coll)
    if novo:                                        # coleção nova pertence a quem a criou
        _org_claim(coll)
    raw_chunks = chunk_text(text)
    if not raw_chunks:
        return {"source": source, "chunks_indexed": 0, "pii_entity_types_masked": [], "pii_entities_count": 0}
    # 1) Mascara PII POR TRECHO, em PARALELO. Docs grandes (centenas de páginas) estouravam o timeout
    #    do Presidio ao mascarar o texto inteiro de uma vez; por trecho cada chamada é pequena e segura.
    masks = [None] * len(raw_chunks)
    with concurrent.futures.ThreadPoolExecutor(max_workers=6) as ex:
        for i, m in zip(range(len(raw_chunks)), ex.map(mask_pii, raw_chunks)):
            masks[i] = m                            # se algum mask falhar, a exceção sobe: nunca indexamos texto CRU
    pii_total, ents_reais, entity_types = 0, [], set()
    for ch, m in zip(raw_chunks, masks):
        pii_total += len(m.get("entities_found", []))
        for t in (m.get("entity_types") or []):
            entity_types.add(t)
        if NEO4J_URL:                               # grafo recebe entidades REAIS (local/soberano)
            ents_reais.extend(_real_entities(ch, m.get("entities_found", [])))
    masked_texts = [m["masked_text"] for m in masks]
    # 2) Embeddings em LOTE (muito mais rápido em CPU) e gravação em lotes (progresso parcial persiste)
    total = 0
    for start in range(0, len(masked_texts), 24):
        batch = masked_texts[start:start + 24]
        vecs = embed_many(batch)
        pts = [PointStruct(id=str(uuid.uuid4()), vector=vecs[i], payload={"text": batch[i], "source": source})
               for i in range(len(batch))]
        qdrant.upsert(collection_name=coll, points=pts); total += len(pts)
    if NEO4J_URL and ents_reais:
        _graph_add(source, ents_reais)
    STATS["docs_ingeridos"] += 1
    STATS["chunks_indexados"] += total
    STATS["pii_mascaradas"] += pii_total
    _cache_limpar_org()                              # acervo mudou → invalida o cache semântico da org
    _event("ingestão", f"{source} → {coll} · {total} trechos · {pii_total} PII mascaradas")
    return {
        "source": source,
        "chunks_indexed": total,
        "pii_entity_types_masked": sorted(entity_types),
        "pii_entities_count": pii_total,
    }


