@app.get("/acervo")
def acervo(colecao: str = COLLECTION):
    if not _org_can(colecao or COLLECTION):          # isolamento: não lista documentos de outra org
        return {"total": 0, "fontes": []}
    try:
        points, _ = qdrant.scroll(collection_name=colecao or COLLECTION, limit=2000,
                                  with_payload=True, with_vectors=False)
    except Exception:
        points = []
    counts = {}
    for p in points:
        src = (p.payload or {}).get("source", "?")
        counts[src] = counts.get(src, 0) + 1
    return {"total": sum(counts.values()),
            "fontes": [{"source": k, "chunks": v} for k, v in sorted(counts.items())]}


@app.post("/clear")
def clear(body: dict | None = None):
    col = ((body or {}).get("colecao") or COLLECTION)     # respeita a coleção ativa; não apaga a errada
    _assert_coll(col)                                     # isolamento: só limpa coleção da própria org
    try:
        qdrant.delete_collection(col)
    except Exception:
        pass
    _ensure_collection(col)
    _event("acervo limpo", f"coleção {col} — vetores removidos")
    return {"status": "limpo", "colecao": col, "vetores": 0}


@app.post("/reindex")
def reindex(body: dict | None = None):
    """Migração de embeddings: recria as coleções na dimensão ATUAL (EMBED_DIM) re-embeddando os TEXTOS
    já armazenados no Qdrant. Preserva todo o conteúdo (não precisa dos arquivos originais). Uso admin."""
    _assert_admin()                                          # só a org administradora migra o índice
    try:
        todas = [c.name for c in qdrant.get_collections().collections]
    except Exception as e:
        return JSONResponse(status_code=502, content={"error": "qdrant: " + str(e)[:200]})
    alvo = ((body or {}).get("colecoes") or todas)
    out = []
    for name in alvo:
        if name not in todas:
            out.append({"colecao": name, "erro": "inexistente"}); continue
        pts, offset = [], None                               # 1) lê todos os textos (independe da dimensão)
        try:
            while True:
                res, offset = qdrant.scroll(collection_name=name, limit=256, with_payload=True, with_vectors=False, offset=offset)
                pts += [(p.payload.get("text", ""), p.payload.get("source", "?")) for p in res if (p.payload or {}).get("text")]
                if offset is None:
                    break
        except Exception as e:
            out.append({"colecao": name, "erro": "scroll: " + str(e)[:80]}); continue
        try:                                                 # 2) recria na dimensão atual
            qdrant.delete_collection(name)
        except Exception:
            pass
        _ensure_collection(name)
        total = 0                                            # 3) re-embed em lote (modelo atual) + upsert
        try:
            for i in range(0, len(pts), 24):
                b = pts[i:i + 24]
                vecs = embed_many([t for t, _ in b])
                qdrant.upsert(collection_name=name, points=[PointStruct(id=str(uuid.uuid4()), vector=vecs[j],
                              payload={"text": b[j][0], "source": b[j][1]}) for j in range(len(b))])
                total += len(b)
        except Exception as e:
            out.append({"colecao": name, "trechos": len(pts), "reindexado": total, "erro": str(e)[:80]}); continue
        out.append({"colecao": name, "trechos": len(pts), "reindexado": total})
    _event("reindex", f"{len(alvo)} coleções · dim={EMBED_DIM}")
    return {"dim": EMBED_DIM, "resultado": out}


@app.post("/ingest")
def ingest(body: IngestText):
    return _ingest(body.text, body.source, body.colecao)


@app.post("/ingest-file")
async def ingest_file(file: UploadFile = File(...), colecao: str = COLLECTION):
    raw = await file.read()
    inner = _expand_archive(file.filename, raw)
    if inner:                                                  # compactado -> ingere cada arquivo de dentro
        itens, chunks_total, pii_total = [], 0, 0
        for nome, b in inner:
            if not _is_ingestable(nome):
                itens.append({"arquivo": nome, "chunks": 0, "aviso": "tipo não suportado"})
                continue
            try:
                txt = await run_in_threadpool(extract_text, nome, b)
                if (txt or "").strip():
                    r = await run_in_threadpool(_ingest, txt, nome, colecao)
                    chunks_total += r.get("chunks_indexed", 0); pii_total += r.get("pii_entities_count", 0)
                    itens.append({"arquivo": nome, "chunks": r.get("chunks_indexed", 0)})
                else:
                    itens.append({"arquivo": nome, "chunks": 0, "aviso": "sem texto extraível"})
            except HTTPException:
                raise
            except Exception as e:
                itens.append({"arquivo": nome, "erro": str(e)[:80]})
        return {"arquivo_compactado": True, "arquivos": len(itens), "itens": itens,
                "chunks_indexed": chunks_total, "pii_entities_count": pii_total}
    txt = await run_in_threadpool(extract_text, file.filename, raw)
    if not (txt or "").strip():                                # PDF escaneado/imagem sem texto etc.
        is_img = (file.filename or "").lower().endswith(IMG_EXT)
        if is_img and not _vision_available():
            aviso = ("imagem sem texto de OCR e o modelo de visão local não está disponível. "
                     f"Baixe o modelo no Ollama (ollama pull {VISION_MODEL}) para o Cerne entender imagens.")
        elif is_img:
            aviso = "não foi possível extrair texto nem descrição visual desta imagem."
        else:
            aviso = "nenhum texto extraível (PDF digitalizado sem OCR? tente exportar como texto)."
        return {"source": file.filename, "chunks_indexed": 0, "pii_entities_count": 0, "aviso": aviso}
    return await run_in_threadpool(_ingest, txt, file.filename, colecao)


# ---- Conectores de dados: páginas web (URL) e pasta monitorada (inbox) ----
INBOX_PATH = os.getenv("INBOX_PATH", "/data/inbox")
INBOX_INTERVALO = max(5, int(os.getenv("INBOX_INTERVALO", "20")))


class IngestUrl(BaseModel):
    url: str
    colecao: str = COLLECTION


def _conn_stat(tipo, item=None, erro=None):
    """Contadores e últimos itens de cada conector (persistidos; alimentam a tela Conectores)."""
    st = APPSTATE.setdefault("conectores", {})
    e = st.setdefault(tipo, {"processados": 0, "erros": 0, "ultimos": []})
    if erro:
        e["erros"] = e.get("erros", 0) + 1
    else:
        e["processados"] = e.get("processados", 0) + 1
    e["ultimos"] = ([{"quando": time.strftime("%d/%m %H:%M"), "item": (item or "")[:90],
                      "erro": (erro or "")[:90]}] + e.get("ultimos", []))[:8]
    _appstate_save(APPSTATE)


def _url_publica_ok(url: str) -> bool:
    """Anti-SSRF: só http(s) para hosts públicos — nunca localhost, IP privado/link-local ou nomes internos."""
    try:
        from urllib.parse import urlparse
        import ipaddress
        import socket
        p = urlparse(url)
        if p.scheme not in ("http", "https") or not p.hostname:
            return False
        host = p.hostname.lower()
        if host == "localhost" or host.endswith((".local", ".internal", ".lan")):
            return False
        for info in socket.getaddrinfo(host, None):
            ip = ipaddress.ip_address(info[4][0])
            if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved or ip.is_multicast:
                return False
        return True
    except Exception:
        return False


def _html_para_texto(raw: str) -> str:
    import html as _html
    raw = re.sub(r"<(script|style|noscript|svg|iframe)[^>]*>.*?</\1>", " ", raw, flags=re.S | re.I)
    raw = re.sub(r"<br\s*/?>|</p>|</div>|</li>|</h[1-6]>|</tr>|</section>|</article>", "\n", raw, flags=re.I)
    txt = _html.unescape(re.sub(r"<[^>]+>", " ", raw))
    txt = re.sub(r"[ \t]+", " ", txt)
    return re.sub(r"\n\s*\n+", "\n\n", txt).strip()


@app.post("/ingest-url")
def ingest_url(body: IngestUrl):
    url = (body.url or "").strip()
    if not _url_publica_ok(url):
        raise HTTPException(status_code=400, detail="URL inválida — apenas endereços http(s) públicos")
    try:
        r = httpx.get(url, timeout=30, follow_redirects=True,
                      headers=CRAWL_HEADERS)
        r.raise_for_status()
    except Exception as ex:
        _conn_stat("url", url, erro=str(ex)[:90])
        raise HTTPException(status_code=400, detail=f"não consegui acessar a página: {str(ex)[:100]}")
    if not _url_publica_ok(str(r.url)):                        # redirecionamento para host interno
        raise HTTPException(status_code=400, detail="a página redirecionou para um endereço interno — bloqueado")
    raw = r.content[:3_000_000]
    ct = (r.headers.get("content-type") or "").lower()
    nome = str(r.url).split("//", 1)[-1][:120]
    if "pdf" in ct or nome.lower().endswith(".pdf"):
        txt = extract_text("pagina.pdf", raw)
    elif "html" in ct or b"<html" in raw[:2000].lower():
        txt = _html_para_texto(raw.decode(r.encoding or "utf-8", errors="ignore"))
    else:
        txt = raw.decode(r.encoding or "utf-8", errors="ignore")
    if not (txt or "").strip():
        return {"source": nome, "chunks_indexed": 0, "pii_entities_count": 0, "aviso": "página sem texto extraível"}
    res = _ingest(txt, nome, body.colecao)
    _conn_stat("url", f"{nome} → {body.colecao or COLLECTION}")
    return res


def _inbox_scan():
    """Pasta monitorada: arquivo em data/inbox/<colecao>/ é ingerido na coleção (raiz → coleção padrão).
    Sucesso move para _processados/ (carimbado); falha move para _erros/. Subpastas _* são ignoradas."""
    if not os.path.isdir(INBOX_PATH):
        return
    for root, dirs, files in os.walk(INBOX_PATH):
        dirs[:] = [d for d in dirs if not d.startswith(("_", "."))]
        rel = os.path.relpath(root, INBOX_PATH)
        coll = COLLECTION if rel == "." else re.sub(r"[^a-z0-9_-]", "", rel.split(os.sep)[0].lower()) or COLLECTION
        for f in files:
            if f.startswith((".", "_", "~")):
                continue
            path = os.path.join(root, f)
            try:
                s1 = os.path.getsize(path)
                time.sleep(1.5)
                if os.path.getsize(path) != s1:                # ainda sendo copiado — fica pro próximo ciclo
                    continue
                with open(path, "rb") as fh:
                    raw = fh.read()
                inner = _expand_archive(f, raw) or ([(f, raw)] if _is_ingestable(f) else [])
                if not inner:
                    raise ValueError("tipo de arquivo não suportado")
                chunks = 0
                for nome, b in inner:
                    if not _is_ingestable(nome):
                        continue
                    txt = extract_text(nome, b)
                    if (txt or "").strip():
                        chunks += _ingest(txt, nome, coll).get("chunks_indexed", 0)
                dest = os.path.join(INBOX_PATH, "_processados")
                os.makedirs(dest, exist_ok=True)
                os.replace(path, os.path.join(dest, time.strftime("%Y%m%d-%H%M%S-") + f))
                _conn_stat("inbox", f"{f} → {coll} · {chunks} trechos")
            except Exception as ex:
                try:
                    dest = os.path.join(INBOX_PATH, "_erros")
                    os.makedirs(dest, exist_ok=True)
                    os.replace(path, os.path.join(dest, f))
                except Exception:
                    pass
                _conn_stat("inbox", f, erro=str(ex)[:90])


def _inbox_loop():
    os.makedirs(INBOX_PATH, exist_ok=True)
    while True:
        try:
            _inbox_scan()                                      # roda na org padrão (default do contextvar)
        except Exception as ex:
            print("[cerne] inbox:", ex)
        time.sleep(INBOX_INTERVALO)


# ---- Crawler: rastreia um site inteiro (BFS) dentro de escopo, respeitando robots.txt ----
CRAWLS = {}                                                 # id -> estado do rastreamento (em memória)
_ROBOTS_CACHE = {}
# UA de navegador: muitos sites (ex.: portais gov) devolvem 403 a User-Agents de bot.
# Continuamos respeitando robots.txt e o intervalo entre acessos — isto só evita a
# recusa sumária por identificação de bot ao indexar conteúdo público autorizado.
CRAWL_UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36"
CRAWL_HEADERS = {"User-Agent": CRAWL_UA,
                 "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,application/pdf;q=0.9,*/*;q=0.8",
                 "Accept-Language": "pt-BR,pt;q=0.9,en;q=0.8",
                 "Upgrade-Insecure-Requests": "1",
                 "Sec-Fetch-Dest": "document", "Sec-Fetch-Mode": "navigate",
                 "Sec-Fetch-Site": "none", "Sec-Fetch-User": "?1",
                 "Sec-CH-UA": '"Chromium";v="125", "Google Chrome";v="125", "Not.A/Brand";v="24"',
                 "Sec-CH-UA-Mobile": "?0", "Sec-CH-UA-Platform": '"Windows"'}


def _waf_nome(h) -> str:
    """Identifica proteção anti-bot pela resposta — para explicar 403/503 de forma honesta."""
    server = (str(h.get("server", "")) or "").lower()
    setck = str(h.get("set-cookie", "") or "")
    if "cloudflare" in server or h.get("cf-mitigated") or h.get("cf-ray"):
        return "Cloudflare"
    if "incapsula" in server or h.get("x-iinfo") or "visid_incap" in setck or "incap_ses" in setck:
        return "Imperva/Incapsula"
    if h.get("x-akamai-transformed") or "akamai" in server or "ak_bmsc" in setck:
        return "Akamai"
    if h.get("x-sucuri-id") or h.get("x-sucuri-block"):
        return "Sucuri"
    return ""


def _url_norm(u: str) -> str:
    """Normaliza para deduplicar: sem fragmento, host minúsculo, sem barra final redundante."""
    try:
        from urllib.parse import urlparse, urlunparse
        p = urlparse(u)
        path = re.sub(r"/+$", "", p.path) or "/"
        return urlunparse((p.scheme, p.netloc.lower(), path, "", p.query, ""))
    except Exception:
        return u


def _robots_ok(url: str) -> bool:
    """Consulta o robots.txt do host (cacheado). Falha ao ler robots = permite (padrão da web)."""
    try:
        from urllib.parse import urlparse
        from urllib.robotparser import RobotFileParser
        p = urlparse(url)
        base = f"{p.scheme}://{p.netloc}"
        rp = _ROBOTS_CACHE.get(base)
        if rp is None:
            rp = RobotFileParser()
            try:
                r = httpx.get(base + "/robots.txt", timeout=12, follow_redirects=True,
                              headers=CRAWL_HEADERS)
                rp.parse(r.text.splitlines() if r.status_code == 200 else [])
            except Exception:
                rp.parse([])                                # sem robots acessível → libera
            _ROBOTS_CACHE[base] = rp
        return rp.can_fetch(CRAWL_UA, url)
    except Exception:
        return True


def _links_escopo(html: str, base_url: str, host: str, prefixo: str) -> list:
    """Extrai links da página que ficam DENTRO do escopo (mesmo host e, se houver, mesmo caminho)."""
    from urllib.parse import urljoin, urlparse
    out = []
    for m in re.finditer(r'href\s*=\s*["\']([^"\'#]+)', html, re.I):
        href = m.group(1).strip()
        if not href or href.lower().startswith(("mailto:", "tel:", "javascript:", "data:")):
            continue
        full = urljoin(base_url, href)
        p = urlparse(full)
        if p.scheme not in ("http", "https") or p.netloc.lower() != host:
            continue
        if prefixo and not p.path.startswith(prefixo):
            continue
        if re.search(r"\.(jpg|jpeg|png|gif|svg|webp|ico|css|js|zip|rar|7z|mp4|mp3|avi|mov|woff2?|ttf)(\?|$)", p.path, re.I):
            continue
        out.append(_url_norm(full))
    return out


def _crawl_pub(c: dict) -> dict:
    return {"id": c["id"], "seed": c["seed"], "colecao": c["colecao"], "status": c["status"],
            "indexados": c["indexados"], "paginas_vistas": c["vistas"], "chunks": c["chunks"],
            "pii": c["pii"], "max_pages": c["max_pages"], "profundidade": c["max_depth"],
            "atual": c.get("atual", ""), "erro": c.get("erro", ""), "log": c.get("log", [])[-12:]}


def _crawl_run(cid: str):
    from collections import deque
    from urllib.parse import urlparse
    c = CRAWLS[cid]
    tok = _ORG_CTX.set(c["org"])                            # roda com a identidade da org que iniciou
    try:
        c["status"] = "rodando"
        seed = c["seed"]
        host = urlparse(seed).netloc.lower()
        prefixo = c["prefixo"]
        fila = deque([(_url_norm(seed), 0)])
        vistos = {_url_norm(seed)}
        teto_descoberta = max(c["max_pages"] * 12, 200)
        while fila and c["indexados"] < c["max_pages"] and not c.get("parar"):
            url, depth = fila.popleft()
            c["vistas"] += 1
            c["atual"] = url
            if not _url_publica_ok(url):
                continue
            if not _robots_ok(url):
                c["log"].append(f"⨯ bloqueado por robots.txt: {url[:80]}")
                continue
            try:
                r = httpx.get(url, timeout=30, follow_redirects=True, headers=CRAWL_HEADERS)
                r.raise_for_status()
            except httpx.HTTPStatusError as ex:
                sc = ex.response.status_code
                waf = _waf_nome(ex.response.headers)
                if sc in (403, 503) and waf:
                    c["waf"] = waf
                    c["log"].append(f"⛔ {waf} bloqueou (desafio anti-bot): {url[:55]} — este site exige um navegador real; o rastreador soberano (sem JavaScript) não passa. Use a API/dados oficiais do órgão, ou baixe os documentos e ingira por upload.")
                else:
                    c["log"].append(f"⚠ HTTP {sc} em {url[:60]}")
                continue
            except Exception as ex:
                c["log"].append(f"⚠ falha {url[:70]}: {str(ex)[:50]}")
                continue
            if urlparse(str(r.url)).netloc.lower() != host:  # redirecionou para fora do escopo
                continue
            ct = (r.headers.get("content-type") or "").lower()
            raw = r.content[:3_000_000]
            is_html = "html" in ct or b"<html" in raw[:2000].lower()
            try:
                if "pdf" in ct or url.lower().endswith(".pdf"):
                    txt = extract_text("pagina.pdf", raw)
                elif is_html:
                    txt = _html_para_texto(raw.decode(r.encoding or "utf-8", errors="ignore"))
                else:
                    txt = raw.decode(r.encoding or "utf-8", errors="ignore")
            except Exception as ex:
                c["log"].append(f"⚠ extração {url[:60]}: {str(ex)[:40]}")
                txt = ""
            nome = str(r.url).split("//", 1)[-1][:120]
            if (txt or "").strip():
                try:
                    res = _ingest(txt, nome, c["colecao"])
                    c["indexados"] += 1
                    c["chunks"] += res.get("chunks_indexed", 0)
                    c["pii"] += res.get("pii_entities_count", 0)
                    c["log"].append(f"✓ {nome[:78]} · {res.get('chunks_indexed', 0)} trechos")
                except Exception as ex:
                    c["log"].append(f"⚠ indexação {nome[:55]}: {str(ex)[:40]}")
            else:
                c["log"].append(f"· sem texto: {nome[:80]}")
            if is_html and depth < c["max_depth"] and len(vistos) < teto_descoberta:
                for link in _links_escopo(raw.decode(r.encoding or "utf-8", errors="ignore"), str(r.url), host, prefixo):
                    if link not in vistos:
                        vistos.add(link)
                        fila.append((link, depth + 1))
            time.sleep(c["delay"])
        c["status"] = "parado" if c.get("parar") else "concluido"
        _conn_stat("crawl", f"{seed} → {c['colecao']} · {c['indexados']} páginas · {c['chunks']} trechos"
                   + (" (interrompido)" if c.get("parar") else ""))
        _event("rastreamento de site", f"{seed} · {c['indexados']} páginas · {c['chunks']} trechos", actor=c["org"])
    except Exception as ex:
        c["status"] = "erro"; c["erro"] = str(ex)[:200]
        _conn_stat("crawl", c["seed"], erro=str(ex)[:80])
    finally:
        c["atualizado"] = time.time()
        _ORG_CTX.reset(tok)


class CrawlReq(BaseModel):
    url: str
    colecao: str = COLLECTION
    max_pages: int = 25
    max_depth: int = 2
    delay: float = 1.0
    same_path: bool = True


@app.post("/crawl")
def crawl_start(body: CrawlReq):
    from urllib.parse import urlparse
    url = (body.url or "").strip()
    if not _url_publica_ok(url):
        raise HTTPException(status_code=400, detail="URL inválida — apenas endereços http(s) públicos")
    org = _tenant()
    if any(c["org"] == org and c["status"] == "rodando" for c in CRAWLS.values()):
        raise HTTPException(status_code=409, detail="já existe um rastreamento em andamento — aguarde ou pare o atual")
    p = urlparse(url)
    prefixo = ""
    if body.same_path:
        prefixo = p.path.rsplit("/", 1)[0] + "/" if "/" in p.path.strip("/") else p.path if p.path.endswith("/") else p.path.rsplit("/", 1)[0] + "/"
        if not prefixo or prefixo == "/":
            prefixo = ""
    cid = uuid.uuid4().hex[:10]
    CRAWLS[cid] = {"id": cid, "seed": url, "colecao": body.colecao or COLLECTION, "org": org,
                   "status": "na_fila", "prefixo": prefixo,
                   "max_pages": max(1, min(200, int(body.max_pages or 25))),
                   "max_depth": max(0, min(4, int(body.max_depth or 2))),
                   "delay": max(0.3, min(10.0, float(body.delay or 1.0))),
                   "indexados": 0, "vistas": 0, "chunks": 0, "pii": 0,
                   "log": [], "iniciado": time.time(), "atualizado": time.time()}
    if len(CRAWLS) > 40:                                    # poda crawls antigos já finalizados
        for k in sorted([k for k, v in CRAWLS.items() if v["status"] != "rodando"],
                        key=lambda k: CRAWLS[k]["iniciado"])[:20]:
            CRAWLS.pop(k, None)
    threading.Thread(target=_crawl_run, args=(cid,), name="cerne-crawl", daemon=True).start()
    return _crawl_pub(CRAWLS[cid])


@app.get("/crawl/{cid}")
def crawl_status(cid: str):
    c = CRAWLS.get(cid)
    if not c or c["org"] != _tenant():
        raise HTTPException(status_code=404, detail="rastreamento não encontrado")
    return _crawl_pub(c)


@app.post("/crawl/{cid}/parar")
def crawl_stop(cid: str):
    c = CRAWLS.get(cid)
    if not c or c["org"] != _tenant():
        raise HTTPException(status_code=404, detail="rastreamento não encontrado")
    c["parar"] = True
    return {"ok": True, "status": c["status"]}


@app.get("/conectores")
def conectores():
    st = APPSTATE.get("conectores", {})
    org = _tenant()
    ativos = [_crawl_pub(c) for c in CRAWLS.values() if c["org"] == org and c["status"] in ("na_fila", "rodando")]
    return {"inbox": dict({"path": INBOX_PATH, "intervalo_s": INBOX_INTERVALO, "ativo": os.path.isdir(INBOX_PATH)},
                          **st.get("inbox", {})),
            "url": st.get("url", {}),
            "crawl": st.get("crawl", {}),
            "crawls_ativos": ativos,
            "planejados": ["ERP/CRM (Airbyte)", "E-mail (IMAP)", "Bancos SQL", "SharePoint / Google Drive"]}


