@app.get("/preflight")
def preflight():
    checks = []
    def add(nome, ok, det=""):
        checks.append({"check": nome, "ok": bool(ok), "detalhe": det})
    add("Gateway (LiteLLM) acessível", _svc_up(f"{GATEWAY_URL}/health/liveliness"))
    add("PII masking (Presidio) saudável", _svc_up(f"{PII_URL}/health"))
    add("Qdrant pronto", _svc_up(f"{QDRANT_URL}/readyz"))
    try:
        names = [m.get("name", "") for m in httpx.get(f"{OLLAMA_URL}/api/tags", timeout=8).json().get("models", [])]
        add("Ollama acessível", True, f"{len(names)} modelos")
        add("Modelo de chat presente", any(("qwen" in n or "llama" in n) for n in names), ", ".join(names))
        add("Modelo de embedding presente", any(("nomic" in n or "embed" in n) for n in names))
        _vb = VISION_MODEL.split(":")[0]
        add("Modelo de visão presente (opcional)",
            any(n == VISION_MODEL or n.split(":")[0] == _vb for n in names),
            f"{VISION_MODEL} — entende imagens/gráficos/tabelas (OCR + VLM local)")
    except Exception:
        add("Ollama acessível", False)
        add("Modelo de chat presente", False)
        add("Modelo de embedding presente", False)
    if RERANK_URL:
        add("Reranker (BGE) acessível", _svc_up(f"{RERANK_URL}/health"))
    if NEO4J_URL:
        add("Grafo (Neo4j) acessível", _graph_counts() is not None)
    lg = _audit_read(1)
    add("Audit ledger íntegro", lg.get("integro", True), f"{lg.get('total', 0)} registros")
    passing = sum(1 for c in checks if c["ok"])
    return {"passando": passing, "total": len(checks), "checks": checks}


# ============ Skills / Prompt Templates · Instruções globais · Projetos · Adoção ============
class SkillReq(BaseModel):
    id: str | None = None
    nome: str
    descricao: str = ""
    prompt: str
    colecao: str = ""
    categoria: str = ""
    tags: list[str] | None = None


class InstrucaoReq(BaseModel):
    system_prompt: str = ""


class ColecaoReq(BaseModel):
    nome: str


@app.get("/skills")
def skills_list():
    out = []
    for s in _skills():
        cat = s.get("categoria") or "Minhas Skills"
        out.append({**s, "categoria": cat, "icon": s.get("icon") or _CAT_ICON.get(cat, "🧩"),
                    "gerenciada": str(s.get("id", "")).startswith("cat-")})
    # ordena por categoria, depois nome — a UI monta a árvore a partir disso
    out.sort(key=lambda x: (x.get("categoria", ""), x.get("nome", "")))
    return {"skills": out, "categorias": sorted({s["categoria"] for s in out})}


@app.post("/skills")
def skills_save(body: SkillReq):
    sk = _skills()
    sid = body.id or uuid.uuid4().hex[:8]
    cat = (body.categoria or "").strip() or "Minhas Skills"
    item = {"id": sid, "nome": body.nome, "descricao": body.descricao,
            "prompt": body.prompt, "colecao": body.colecao,
            "categoria": cat, "icon": _CAT_ICON.get(cat, "🧩"),
            "tags": [t.strip() for t in (body.tags or []) if t.strip()]}
    APPSTATE["skills"] = [s for s in sk if s.get("id") != sid] + [item]
    _appstate_save(APPSTATE)
    _event("skill salva", f"{body.nome}" + (f" · {cat}" if cat else "") + (f" · coleção {body.colecao}" if body.colecao else ""))
    return item


@app.delete("/skills/{sid}")
def skills_del(sid: str):
    APPSTATE["skills"] = [s for s in _skills() if s.get("id") != sid]
    _appstate_save(APPSTATE)
    _event("skill removida", sid)
    return {"status": "removido", "id": sid}


# ---- Catálogo de skills (personas por área) com método/checklist/formato. Skills 'cat-' são gerenciadas
