def _seed_skills():
    """Sincroniza o catálogo gerenciado (ids 'cat-'): adiciona as que faltam e ATUALIZA as personas para a
    versão mais recente, preservando o vínculo de coleção. Skills criadas pelo usuário não são tocadas."""
    try:
        by_id = {s.get("id"): s for s in _skills()}
        changed = False
        for (sid, categoria, nome, desc, prompt) in _CATALOGO_SKILLS:
            icon = _CAT_ICON.get(categoria, "🧩")
            cur = by_id.get(sid)
            if cur is None:
                by_id[sid] = {"id": sid, "nome": nome, "descricao": desc, "prompt": prompt,
                              "colecao": "", "categoria": categoria, "icon": icon}
                changed = True
            elif (cur.get("prompt"), cur.get("nome"), cur.get("descricao"), cur.get("categoria")) != (prompt, nome, desc, categoria):
                cur.update({"nome": nome, "descricao": desc, "prompt": prompt,
                            "categoria": categoria, "icon": icon})   # preserva 'colecao' do usuário
                changed = True
        if changed:
            APPSTATE["skills"] = list(by_id.values())
            _appstate_save(APPSTATE)
            _event("catálogo de skills", "personas sincronizadas/afinadas")
    except Exception as ex:
        print("[cerne] seed skills:", ex)


