def _memoria_ativa():
    return _org().get("memoria_ativa", True) is not False    # opt-out por organização; padrão ligado


def _memoria_bloco():
    """Bloco de contexto com os fatos que o usuário pediu para lembrar (injetado no chat)."""
    if not _memoria_ativa():
        return ""
    ms = _memorias()[-24:]
    if not ms:
        return ""
    linhas = "\n".join("- " + (m.get("texto", "") or "")[:220] for m in ms)
    return "[MEMÓRIA DO USUÁRIO — fatos que ele pediu para lembrar; use quando for relevante à pergunta]\n" + linhas


