    org = _tenant()
    fb = [f for f in APPSTATE.get("feedback", []) if f.get("org") == org]
    pos = sum(1 for f in fb if f["rating"] > 0)
    neg = sum(1 for f in fb if f["rating"] < 0)
    tot = len(fb)
    negs = [{"pergunta": f["pergunta"], "comentario": f.get("comentario", ""), "ts": f["ts"]}
            for f in fb if f["rating"] < 0][-20:][::-1]
    return {"total": tot, "positivos": pos, "negativos": neg,
            "satisfacao": (round(pos / tot * 100, 1) if tot else None), "negativos_recentes": negs}


