# ================= PLANO AGÊNTICO · Execução durável + fila de aprovação =================
# Tarefas longas do orquestrador rodam em 2º plano (não travam a requisição) e podem exigir
# APROVAÇÃO HUMANA antes de executar (human-in-the-loop assíncrono). Estado durável em memória
# do processo + fila com um worker dedicado. Cada job é isolado por organização.
_JOBS: dict = {}
_JOBS_MAX = 500
_JOBS_Q: "queue.Queue" = queue.Queue()
_JOBS_WORKER_ON = {"v": False}

def _job_pub(j: dict) -> dict:
    """Projeção segura do job para a API (resposta pode ser grande; mantemos o essencial)."""
    return {k: j.get(k) for k in ("id", "tipo", "titulo", "status", "pergunta", "colecoes", "skill_id",
                                  "resultado", "fontes", "erro", "criado", "atualizado", "aprovacao", "por")}

def _orquestrar_sync(message: str, colls: list, skill_prompt: str = None):
    """Orquestrador NÃO-streaming (usado pela fila): plano → subtarefas em paralelo → síntese.
    Espelha o /agent-stream. Retorna (resposta_final, fontes)."""
    org = _org(); pool = _ext_permitidos(org); strong = _best_provider(org) or "chat"
    planner_m = next((p for p in ("ext-cerebras", "ext-groq", "ext-qwen", "ext-mistral") if p in pool), strong)
    plan = [{"role": "system", "content": "Você é um planejador. Quebre o pedido do usuário em 3 a 6 subtarefas objetivas, independentes e complementares que, somadas, entregam um resultado completo. Responda SOMENTE com um array JSON válido, sem markdown e sem texto ao redor, no formato: [{\"titulo\":\"curto\",\"prompt\":\"instrução completa e autossuficiente para uma IA executar essa subtarefa\"}]"},
            {"role": "user", "content": message}]
    subs = _parse_json_list(_strip_think(_chat_resiliente(planner_m, plan, max_tokens=1600) or "")) or [{"titulo": "Resposta", "prompt": message}]
    subs = subs[:6]
    shared = ""; fontes_reais = []
    if colls:
        hh = _search_multi(_rewrite_query(message, "chat"), 5, colls)
        shared = _compress("\n\n---\n\n".join(h.payload.get("text", "") for h in hh), message)
        fontes_reais = [{"source": h.payload.get("source", "?"),
                         "trecho": (h.payload.get("text", "") or "")[:220],
                         "score": round(float(getattr(h, "score", 0) or 0), 2)} for h in hh[:6]]
    if org.get("busca_web"):
        wt, wf = _web_search(message)
        shared = (shared + "\n\n" + wt).strip() if shared else wt
        fontes_reais += wf
    titulos = [s.get("titulo", "") for s in subs]
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=min(5, len(subs))) as exx:
        futs = {exx.submit(_orch_worker, (pool[i % len(pool)] if pool else "chat"), s, shared): s for i, s in enumerate(subs)}
        for f in concurrent.futures.as_completed(futs):
            try:
                results.append(f.result())
            except Exception:
                pass
    results.sort(key=lambda r: titulos.index(r["titulo"]) if r["titulo"] in titulos else 99)
    partes = "\n\n".join(f"### {r['titulo']}\n{r['saida']}" for r in results)
    sys_syn = (skill_prompt + "\n\n" if skill_prompt else "") + "Você é um sintetizador especialista. Junte as PARTES num resultado final coeso, completo e pronto para uso, em português. Remova redundâncias, mantenha o melhor de cada, formate bem (títulos/listas quando ajudar)."
    syn = [{"role": "system", "content": sys_syn},
           {"role": "user", "content": f"PEDIDO ORIGINAL:\n{message}\n\nPARTES PRODUZIDAS:\n{partes}"}]
    final, _ = guard_output(_strip_think(_chat_resiliente(strong, syn, max_tokens=3000) or "") or partes)
    fontes = fontes_reais + [{"source": "🧩 " + t, "trecho": "", "score": ""} for t in titulos]
    return final, fontes

def _job_run(job: dict):
    tok = _ORG_CTX.set(job["org"])                      # roda com a identidade da org dona do job
    try:
        job["status"] = "rodando"; job["atualizado"] = time.time()
        colls = _org_colls_ok(job.get("colecoes") or [])
        _jids = job.get("skill_ids") or ([job["skill_id"]] if job.get("skill_id") else [])
        prompt, _jnome, _jcols = _skills_combinar(_jids)      # combina 1+ skills também na fila
        if _jcols:
            colls = _org_colls_ok(list(dict.fromkeys((colls or []) + _jcols)))
        ans, fontes = _orquestrar_sync(job["pergunta"], colls, prompt)
        job["resultado"] = ans; job["fontes"] = fontes; job["status"] = "concluido"
        _event("job concluído", f'{job["titulo"][:50]} · {job["id"]}', actor=job["org"])
    except Exception as e:
        job["status"] = "erro"; job["erro"] = str(e)[:300]
        _event("job erro", f'{job.get("id")} · {str(e)[:80]}', actor=job.get("org"))
    finally:
        job["atualizado"] = time.time()
        _ORG_CTX.reset(tok)

def _jobs_worker():
    while True:
        job = _JOBS_Q.get()
        try:
            if job and job.get("status") == "na_fila":
                _job_run(job)
        except Exception:
            pass
        finally:
            _JOBS_Q.task_done()

def _jobs_worker_start():
    if _JOBS_WORKER_ON["v"]:
        return
    _JOBS_WORKER_ON["v"] = True
    threading.Thread(target=_jobs_worker, name="cerne-jobs", daemon=True).start()

def _job_enfileirar(j):
    _jobs_worker_start()
    _JOBS_Q.put(j)


class JobReq(BaseModel):
    message: str
    titulo: str = ""
    colecoes: list | None = None
    skill_id: str = ""
    skill_ids: list | None = None    # múltiplas skills também na fila
    aprovacao: bool = False          # exige aprovação humana antes de executar (human-in-the-loop)


@app.post("/jobs")
def jobs_create(body: JobReq):
    msg = (body.message or "").strip()
    if not msg:
        return JSONResponse(status_code=400, content={"error": "pedido vazio"})
    okg, reason = guard_input(msg)
    if not okg:
        return JSONResponse(status_code=400, content={"error": f"bloqueado pelo guardrail: {reason}"})
    jid = uuid.uuid4().hex[:10]
    j = {"id": jid, "org": _tenant(), "tipo": "orquestracao",
         "titulo": (body.titulo or msg[:60]).strip(),
         "status": "aguardando_aprovacao" if body.aprovacao else "na_fila",
         "pergunta": msg, "colecoes": body.colecoes or [], "skill_id": body.skill_id or "",
         "skill_ids": body.skill_ids or ([body.skill_id] if body.skill_id else []),
         "resultado": None, "fontes": [], "erro": None,
         "criado": time.time(), "atualizado": time.time(), "aprovacao": bool(body.aprovacao), "por": None}
    _JOBS[jid] = j
    if len(_JOBS) > _JOBS_MAX:                          # bounded: descarta os mais antigos
        for k in sorted(_JOBS, key=lambda k: _JOBS[k]["criado"])[:len(_JOBS) - _JOBS_MAX]:
            _JOBS.pop(k, None)
    _event("job criado", f'{j["titulo"][:50]} · {"aguarda aprovação" if body.aprovacao else "enfileirado"}')
    if not body.aprovacao:
        _job_enfileirar(j)
    return _job_pub(j)


@app.get("/jobs")
def jobs_list():
    org = _tenant()
    js = [_job_pub(j) for j in _JOBS.values() if j.get("org") == org]
    js.sort(key=lambda x: x["criado"], reverse=True)
    return {"jobs": js[:100]}


@app.get("/jobs/{jid}")
def job_get(jid: str):
    j = _JOBS.get(jid)
    if not j or j.get("org") != _tenant():
        return JSONResponse(status_code=404, content={"error": "job não encontrado"})
    return _job_pub(j)


@app.post("/jobs/{jid}/aprovar")
def job_aprovar(jid: str):
    j = _JOBS.get(jid)
    if not j or j.get("org") != _tenant():
        return JSONResponse(status_code=404, content={"error": "job não encontrado"})
    if j["status"] != "aguardando_aprovacao":
        return _job_pub(j)
    j["status"] = "na_fila"; j["por"] = _tenant(); j["atualizado"] = time.time()
    _event("job aprovado", f'{j["titulo"][:50]} · {jid}')
    _job_enfileirar(j)
    return _job_pub(j)


@app.post("/jobs/{jid}/recusar")
def job_recusar(jid: str):
    j = _JOBS.get(jid)
    if not j or j.get("org") != _tenant():
        return JSONResponse(status_code=404, content={"error": "job não encontrado"})
    if j["status"] == "aguardando_aprovacao":
        j["status"] = "recusado"; j["atualizado"] = time.time()
        _event("job recusado", jid)
    return _job_pub(j)


@app.get("/colecoes")
def colecoes():
    out = []
    try:
        for c in qdrant.get_collections().collections:
            if not _org_can(c.name):                 # isolamento: só lista coleções da própria org
                continue
            try:
                n = qdrant.count(collection_name=c.name, exact=True).count
            except Exception:
                n = None
            out.append({"nome": c.name, "vetores": n, "padrao": c.name == COLLECTION})
    except Exception:
        pass
    return {"colecoes": sorted(out, key=lambda x: x["nome"])}


@app.post("/colecoes")
def colecoes_create(body: ColecaoReq):
    nome = re.sub(r"[^a-zA-Z0-9_-]", "_", (body.nome or "").strip())[:40] or "projeto"
    if not _org_can_write(nome):
        return JSONResponse(status_code=403, content={"error": "coleção pertence a outra organização"})
    novo = not _coll_exists(nome)
    _ensure_collection(nome)
    if novo:
        _org_claim(nome)                             # coleção nova pertence à org que a criou
    _event("coleção criada", nome)
    return {"status": "ok", "nome": nome}


class ColRef(BaseModel):
    colecao: str
    source: str = ""


@app.delete("/colecoes/{nome}")
def colecoes_del(nome: str):
    if nome == COLLECTION:
        return JSONResponse(status_code=400, content={"error": "a coleção padrão não pode ser excluída"})
    _assert_coll(nome)                               # isolamento: só exclui coleção da própria org
    try:
        qdrant.delete_collection(nome)
    except Exception as e:
        return JSONResponse(status_code=502, content={"error": str(e)[:200]})
    for cfg in _orgs_cfg().values():                 # libera a posse
        if nome in (cfg.get("colecoes") or []):
            cfg["colecoes"].remove(nome)
    _appstate_save(APPSTATE)
    _event("coleção excluída", nome)
    return {"status": "excluida", "nome": nome}


@app.post("/colecoes/limpar")
def colecoes_limpar(body: ColRef):
    nome = body.colecao or COLLECTION
    _assert_coll(nome)                               # isolamento: só limpa coleção da própria org
    try:
        qdrant.delete_collection(nome)
        _ensure_collection(nome)
    except Exception as e:
        return JSONResponse(status_code=502, content={"error": str(e)[:200]})
    _event("coleção limpa", nome)
    return {"status": "limpa", "nome": nome}


@app.post("/acervo/remover")
def acervo_remover(body: ColRef):
    if not body.source:
        return JSONResponse(status_code=400, content={"error": "informe o documento"})
    _assert_coll(body.colecao or COLLECTION)         # isolamento: só remove doc de coleção da própria org
    try:
        qdrant.delete(collection_name=body.colecao or COLLECTION,
                      points_selector=Filter(must=[FieldCondition(key="source", match=MatchValue(value=body.source))]))
    except Exception as e:
        return JSONResponse(status_code=502, content={"error": str(e)[:200]})
    _event("documento removido", f"{body.source} · {body.colecao}")
    return {"status": "removido", "source": body.source}


# ---- gestão de organizações (multi-tenant) — restrito à org administradora (padrão) ----
class OrgNew(BaseModel):
    nome: str


class OrgColl(BaseModel):
    colecao: str


@app.get("/orgs")
def orgs_list():
    _assert_admin()
    out = []
    for name, cfg in _orgs_cfg().items():
        k = cfg.get("api_key")
        out.append({"org": name, "nome": cfg.get("nome", name),
                    "colecoes": cfg.get("colecoes", []),
                    "api_key_mask": (k[:10] + "…" + k[-4:]) if k else None,
                    "padrao": name == DEFAULT_ORG})
    return {"orgs": sorted(out, key=lambda x: (not x["padrao"], x["org"])), "default": DEFAULT_ORG}


@app.post("/orgs")
def orgs_create(body: OrgNew):
    _assert_admin()
    slug = re.sub(r"[^a-z0-9_-]", "", (body.nome or "").strip().lower().replace(" ", "-"))[:32] or "org"
    orgs = _orgs_cfg()
    if slug in orgs:
        return JSONResponse(status_code=400, content={"error": "organização já existe"})
    key = "cerne_" + uuid.uuid4().hex
    orgs[slug] = {"nome": (body.nome or slug).strip(), "colecoes": [], "api_key": key}
    _appstate_save(APPSTATE)
    _event("organização criada", slug)
    return {"org": slug, "api_key": key}             # a chave é exibida UMA vez


@app.post("/orgs/{org}/rotate")
def orgs_rotate(org: str):
    _assert_admin()
    orgs = _orgs_cfg()
    if org not in orgs:
        return JSONResponse(status_code=404, content={"error": "organização inexistente"})
    key = "cerne_" + uuid.uuid4().hex
    orgs[org]["api_key"] = key
    _appstate_save(APPSTATE)
    _event("organização · chave rotacionada", org)
    return {"org": org, "api_key": key}


@app.post("/orgs/{org}/colecoes")
def orgs_assign(org: str, body: OrgColl):
    _assert_admin()
    if org not in _orgs_cfg():
        return JSONResponse(status_code=404, content={"error": "organização inexistente"})
    _org_claim(body.colecao, org)
    return {"status": "ok", "org": org, "colecao": body.colecao}


@app.delete("/orgs/{org}")
def orgs_del(org: str):
    _assert_admin()
    if org == DEFAULT_ORG:
        return JSONResponse(status_code=400, content={"error": "a organização padrão não pode ser excluída"})
    _orgs_cfg().pop(org, None)
    _appstate_save(APPSTATE)
    _event("organização excluída", org)
    return {"status": "excluida", "org": org}


@app.post("/anexo")
async def anexo_add(file: UploadFile = File(...), sid: str = ""):
    raw = await file.read()
    try:
        txt = extract_text(file.filename, raw)
    except Exception:
        txt = raw.decode("utf-8", errors="ignore")
    masked = mask_pii(txt).get("masked_text", txt)   # anexo fica mascarado (soberano; seguro p/ externo)
    aid = uuid.uuid4().hex[:10]
    APPSTATE.setdefault("anexos", []).append({"id": aid, "org": _tenant(), "sid": sid,
                                              "nome": file.filename, "texto": masked, "ts": time.time()})
    _anexos_cleanup()
    _appstate_save(APPSTATE)
    _event("anexo de chat", f"{file.filename}")
    return {"id": aid, "nome": file.filename, "retencao_dias": _org_retention()}


@app.get("/anexos")
def anexos_list(sid: str = ""):
    _anexos_cleanup()
    itens = [{"id": a["id"], "nome": a.get("nome")} for a in APPSTATE.get("anexos", [])
             if a.get("sid") == sid and a.get("org") == _tenant()]
    return {"anexos": itens, "retencao_dias": _org_retention()}


