# ---- pastas do acervo (árvore virtual para organizar as coleções; as coleções seguem planas no Qdrant) ----
def _pastas():
    return sorted(set(APPSTATE.get("pastas") or []))


def _pastas_mapa():
    return APPSTATE.get("pastas_mapa") or {}


def _pasta_norm(caminho: str) -> str:
    """Normaliza 'a / b\\c' -> 'a/b/c': até 3 níveis, 40 chars por nível, sem nomes reservados."""
    partes = [re.sub(r"[<>\"'`]", "", p.strip())[:40] for p in (caminho or "").replace("\\", "/").split("/")]
    partes = [p for p in partes if p and p not in (".", "..") and not p.startswith("_")]
    return "/".join(partes[:3])


@app.get("/pastas")
def pastas_get():
    return {"pastas": _pastas(), "mapa": _pastas_mapa()}


@app.post("/pastas")
def pastas_create(body: dict | None = None):
    cam = _pasta_norm((body or {}).get("caminho", ""))
    if not cam:
        raise HTTPException(status_code=400, detail="nome de pasta inválido")
    ps = set(_pastas())
    seg = cam.split("/")
    for i in range(1, len(seg) + 1):                        # garante os ancestrais
        ps.add("/".join(seg[:i]))
    APPSTATE["pastas"] = sorted(ps)
    _appstate_save(APPSTATE)
    _event("pasta criada", cam, actor=_actor())
    return {"pastas": _pastas()}


@app.post("/pastas/remover")
def pastas_remover(body: dict | None = None):
    cam = _pasta_norm((body or {}).get("caminho", ""))
    if cam not in _pastas():
        raise HTTPException(status_code=404, detail="pasta não encontrada")
    pai = cam.rsplit("/", 1)[0] if "/" in cam else ""
    APPSTATE["pastas"] = [p for p in _pastas() if p != cam and not p.startswith(cam + "/")]
    mapa = dict(_pastas_mapa())
    for coll, p in list(mapa.items()):                      # conteúdo (inclusive de subpastas) sobe para a pasta pai
        if p == cam or p.startswith(cam + "/"):
            if pai:
                mapa[coll] = pai
            else:
                mapa.pop(coll, None)
    APPSTATE["pastas_mapa"] = mapa
    _appstate_save(APPSTATE)
    _event("pasta removida", cam, actor=_actor())
    return {"pastas": _pastas(), "mapa": mapa}


@app.post("/pastas/mover")
def pastas_mover(body: dict | None = None):
    b = body or {}
    coll = (b.get("colecao") or "").strip()
    cam = _pasta_norm(b.get("pasta", ""))
    if not coll or not _coll_exists(coll):
        raise HTTPException(status_code=404, detail="coleção não encontrada")
    mapa = dict(_pastas_mapa())
    if cam:
        if cam not in _pastas():
            raise HTTPException(status_code=404, detail="pasta não existe")
        mapa[coll] = cam
    else:
        mapa.pop(coll, None)                                # raiz do acervo
    APPSTATE["pastas_mapa"] = mapa
    _appstate_save(APPSTATE)
    return {"mapa": mapa}


# ---- usuários, perfis & autenticação (login por e-mail + senha; RBAC aplicado no servidor) ----
class UsuarioReq(BaseModel):
    id: str | None = None
    nome: str
    email: str = ""
    perfil: str = "colaborador"


class LoginReq(BaseModel):
    email: str
    senha: str


class TrocaSenhaReq(BaseModel):
    senha_atual: str
    senha_nova: str


def _usuarios():
    us = APPSTATE.get("usuarios")
    if not us:
        us = [{"id": "admin", "nome": "Administrador", "email": "admin@orqion.com.br", "perfil": "admin", "status": "ativo"}]
        APPSTATE["usuarios"] = us
    return us


def _usuario_por_email(email):
    email = (email or "").strip().lower()
    return next((u for u in _usuarios() if (u.get("email") or "").strip().lower() == email), None)


def _usuario_por_id(uid):
    return next((u for u in _usuarios() if u.get("id") == uid), None)


def _admins_ativos():
    return [u for u in _usuarios() if u.get("perfil") == "admin" and u.get("status") != "inativo"]


def _usuario_pub(u):
    """Projeção pública do usuário — NUNCA expõe hash de senha."""
    return {"id": u["id"], "nome": u.get("nome", ""), "email": u.get("email", ""),
            "perfil": u.get("perfil", "colaborador"), "status": u.get("status", "ativo"),
            "trocar_senha": bool(u.get("trocar_senha"))}


def _actor():
    u = _usuario_atual()
    return (u or {}).get("email") or "sistema"


def _auth_seed():
    """Primeiro boot: dá senha ao admin (ADMIN_SENHA do ambiente ou gerada e impressa no log)."""
    adm = next((u for u in _usuarios() if u.get("perfil") == "admin"), None)
    if adm is None or adm.get("senha"):
        return
    senha = os.getenv("ADMIN_SENHA", "").strip() or _gerar_senha()
    adm["senha"] = _hash_senha(senha)
    adm["trocar_senha"] = True
    adm["status"] = "ativo"
    _appstate_save(APPSTATE)
    if not os.getenv("ADMIN_SENHA", "").strip():
        print(f"[cerne] senha inicial do admin ({adm.get('email')}): {senha}  — o primeiro login pede a troca")
    _audit("senha inicial do admin definida", adm.get("email", ""))


@app.post("/auth/login")
def auth_login(body: LoginReq):
    u = _usuario_por_email(body.email)
    if not u or not u.get("senha") or not _senha_confere(body.senha, u["senha"]):
        _event("login recusado", (body.email or "?").strip().lower(), actor="sistema")
        raise HTTPException(status_code=401, detail="e-mail ou senha inválidos")
    if u.get("status") == "inativo":
        raise HTTPException(status_code=403, detail="usuário desativado — fale com o administrador")
    if u.get("status") == "convidado":
        u["status"] = "ativo"
        _appstate_save(APPSTATE)
    tok = _sess_criar(u["id"])
    _event("login", f"{u.get('nome')} · {u.get('perfil')}", actor=u.get("email", ""))
    resp = JSONResponse({"ok": True, "usuario": _usuario_pub(u), "trocar_senha": bool(u.get("trocar_senha"))})
    resp.set_cookie(AUTH_COOKIE, tok, httponly=True, samesite="lax", max_age=AUTH_TTL, path="/")
    return resp


@app.post("/auth/logout")
def auth_logout(request: Request):
    _sess_encerrar(request.cookies.get(AUTH_COOKIE, ""))
    resp = JSONResponse({"ok": True})
    resp.delete_cookie(AUTH_COOKIE, path="/")
    return resp


@app.get("/auth/me")
def auth_me():
    u = _usuario_atual()
    if not u:
        return {"auth": False}
    return {"auth": True, "usuario": _usuario_pub(u), "trocar_senha": bool(u.get("trocar_senha"))}


@app.post("/auth/senha")
def auth_senha(body: TrocaSenhaReq):
    u = _usuario_atual()
    if not u:
        raise HTTPException(status_code=401, detail="não autenticado")
    if not _senha_confere(body.senha_atual, u.get("senha", "")):
        raise HTTPException(status_code=403, detail="senha atual incorreta")
    if len(body.senha_nova or "") < 8:
        raise HTTPException(status_code=400, detail="a nova senha precisa de ao menos 8 caracteres")
    u["senha"] = _hash_senha(body.senha_nova)
    u["trocar_senha"] = False
    _appstate_save(APPSTATE)
    _event("senha alterada", u.get("nome", ""), actor=_actor())
    return {"ok": True}


@app.get("/usuarios")
def usuarios_list():
    return {"usuarios": [_usuario_pub(u) for u in _usuarios()],
            "perfis": {"colaborador": ["work"], "gestor": ["work", "deck"], "admin": ["work", "deck", "ops"]}}


@app.post("/usuarios")
def usuarios_save(body: UsuarioReq):
    us = _usuarios()
    perfil = body.perfil if body.perfil in ("colaborador", "gestor", "admin") else "colaborador"
    email = (body.email or "").strip().lower()
    atual = _usuario_por_id(body.id) if body.id else None
    if atual:                                               # edição: nome/e-mail/perfil (senha não muda aqui)
        if atual.get("perfil") == "admin" and perfil != "admin" and len(_admins_ativos()) <= 1:
            raise HTTPException(status_code=400, detail="não é possível rebaixar o último administrador")
        outro = _usuario_por_email(email)
        if outro and outro.get("id") != atual["id"]:
            raise HTTPException(status_code=400, detail="já existe usuário com este e-mail")
        atual.update({"nome": body.nome.strip() or atual.get("nome"), "email": email or atual.get("email"), "perfil": perfil})
        _appstate_save(APPSTATE)
        _event("usuário atualizado", f"{atual.get('nome')} · {perfil}", actor=_actor())
        return _usuario_pub(atual)
    if not body.nome.strip() or "@" not in email:
        raise HTTPException(status_code=400, detail="informe nome e e-mail válidos")
    if _usuario_por_email(email):
        raise HTTPException(status_code=400, detail="já existe usuário com este e-mail")
    senha = _gerar_senha()                                  # senha temporária: exibida UMA vez ao admin
    item = {"id": uuid.uuid4().hex[:8], "nome": body.nome.strip(), "email": email, "perfil": perfil,
            "status": "convidado", "senha": _hash_senha(senha), "trocar_senha": True}
    APPSTATE["usuarios"] = us + [item]
    _appstate_save(APPSTATE)
    _event("usuário cadastrado", f"{item['nome']} · {perfil}", actor=_actor())
    return dict(_usuario_pub(item), senha_temporaria=senha)


@app.post("/usuarios/{uid}/nova-senha")
def usuarios_nova_senha(uid: str):
    u = _usuario_por_id(uid)
    if not u:
        raise HTTPException(status_code=404, detail="usuário não encontrado")
    senha = _gerar_senha()
    u["senha"] = _hash_senha(senha)
    u["trocar_senha"] = True
    _appstate_save(APPSTATE)
    _sess_derrubar(uid)                                     # derruba sessões abertas com a senha antiga
    _event("senha redefinida", u.get("nome", ""), actor=_actor())
    return {"ok": True, "senha_temporaria": senha}


@app.post("/usuarios/{uid}/status")
def usuarios_status(uid: str, body: dict | None = None):
    u = _usuario_por_id(uid)
    if not u:
        raise HTTPException(status_code=404, detail="usuário não encontrado")
    novo = ((body or {}).get("status") or "").strip()
    if novo not in ("ativo", "inativo"):
        raise HTTPException(status_code=400, detail="status deve ser 'ativo' ou 'inativo'")
    eu = _usuario_atual() or {}
    if novo == "inativo":
        if u.get("id") == eu.get("id"):
            raise HTTPException(status_code=400, detail="você não pode desativar a si mesmo")
        if u.get("perfil") == "admin" and len(_admins_ativos()) <= 1:
            raise HTTPException(status_code=400, detail="não é possível desativar o último administrador")
        _sess_derrubar(uid)
    u["status"] = novo
    _appstate_save(APPSTATE)
    _event("usuário " + ("desativado" if novo == "inativo" else "reativado"), u.get("nome", ""), actor=_actor())
    return _usuario_pub(u)


@app.delete("/usuarios/{uid}")
def usuarios_del(uid: str):
    u = _usuario_por_id(uid)
    if not u:
        raise HTTPException(status_code=404, detail="usuário não encontrado")
    eu = _usuario_atual() or {}
    if u.get("id") == eu.get("id"):
        raise HTTPException(status_code=400, detail="você não pode excluir a si mesmo")
    if u.get("perfil") == "admin" and len(_admins_ativos()) <= 1:
        raise HTTPException(status_code=400, detail="não é possível excluir o último administrador")
    APPSTATE["usuarios"] = [x for x in _usuarios() if x.get("id") != uid]
    _appstate_save(APPSTATE)
    _sess_derrubar(uid)
    _event("usuário excluído", u.get("nome", ""), actor=_actor())
    return {"status": "removido", "id": uid}


# ---- cotas de uso por perfil (FinOps: limite diário de tarefas de IA; 0 = ilimitado) ----
QUOTAS_DEFAULT = {"colaborador": {"tarefas_dia": 200, "externas_dia": 40},
                  "gestor": {"tarefas_dia": 500, "externas_dia": 100},
                  "admin": {"tarefas_dia": 0, "externas_dia": 0}}


def _quotas():
    q = {p: dict(v) for p, v in QUOTAS_DEFAULT.items()}
    for p, v in (APPSTATE.get("quotas") or {}).items():
        if p in q and isinstance(v, dict):
            for k in ("tarefas_dia", "externas_dia"):
                try:
                    q[p][k] = max(0, int(v.get(k, q[p][k]) or 0))
                except Exception:
                    pass
    return q


def _uso_hoje():
    dia = time.strftime("%Y-%m-%d")
    uso = APPSTATE.setdefault("uso_diario", {})
    if dia not in uso:                                          # vira o dia: zera (só o dia corrente interessa)
        uso.clear()
        uso[dia] = {}
    return uso[dia]


def _quota_consumir(externa=False):
    """Conta a tarefa do usuário logado e aplica o limite diário do perfil (0 = ilimitado).
    Chamadas por API key (integração de org) não têm usuário e não passam por cota."""
    u = _usuario_atual()
    if not u:
        return
    q = _quotas().get(u.get("perfil", "colaborador")) or {}
    m = _uso_hoje().setdefault(u["id"], {"tarefas": 0, "externas": 0})
    lim_t, lim_e = q.get("tarefas_dia", 0), q.get("externas_dia", 0)
    if lim_t and m["tarefas"] >= lim_t:
        raise HTTPException(status_code=429,
                            detail=f"limite diário de tarefas de IA do seu perfil atingido ({lim_t}/dia) — fale com o administrador")
    if externa and lim_e and m["externas"] >= lim_e:
        raise HTTPException(status_code=429,
                            detail=f"limite diário de consultas a provedores externos atingido ({lim_e}/dia) — fale com o administrador")
    m["tarefas"] += 1
    if externa:
        m["externas"] += 1
    _appstate_save(APPSTATE)


@app.get("/quotas")
def quotas_get():
    nomes = {u["id"]: u.get("nome", u["id"]) for u in _usuarios()}
    uso = {uid: dict(v, nome=nomes.get(uid, uid)) for uid, v in _uso_hoje().items()}
    return {"quotas": _quotas(), "uso_hoje": uso, "dia": time.strftime("%Y-%m-%d")}


@app.post("/quotas")
def quotas_set(body: dict | None = None):
    b = body or {}
    novo = {}
    for perfil in ("colaborador", "gestor", "admin"):
        v = b.get(perfil) or {}
        try:
            novo[perfil] = {"tarefas_dia": max(0, int(v.get("tarefas_dia", 0) or 0)),
                            "externas_dia": max(0, int(v.get("externas_dia", 0) or 0))}
        except Exception:
            raise HTTPException(status_code=400, detail=f"valores inválidos para o perfil {perfil}")
    APPSTATE["quotas"] = novo
    _appstate_save(APPSTATE)
    _event("cotas atualizadas", " · ".join(f"{p}: {novo[p]['tarefas_dia']}/{novo[p]['externas_dia']}" for p in novo),
           actor=_actor())
    return {"quotas": _quotas()}


# ---- Agentes (Fase 2): Skills evoluídas com ferramentas + permissões + coleção; executam soberano ----
