def _mcp_custom():
    return APPSTATE.get("mcp_custom", [])


def _mcp_lib():
    """TIPOS de conector (templates/shapes): catálogo curado + tipos MCP custom do admin.
    Definem o formato (command/args + NOMES das credenciais). Não contêm credenciais."""
    lib = {k: dict(v, id=k, tipo="catalogo") for k, v in MCP_CATALOGO.items()}
    for c in _mcp_custom():
        lib[c["id"]] = dict(c, tipo="custom")
    return lib


# ---- Cofre de credenciais: cifragem em repouso (Fernet, chave derivada da master key do gateway) ----
_FERNET = None


def _fernet():
    global _FERNET
    if _FERNET is None:
        import base64
        from cryptography.fernet import Fernet
        key = base64.urlsafe_b64encode(hashlib.sha256(("cerne-conn:" + (GATEWAY_KEY or "cerne")).encode()).digest())
        _FERNET = Fernet(key)
    return _FERNET


def _enc(v: str) -> str:
    try:
        return "enc:" + _fernet().encrypt((v or "").encode()).decode()
    except Exception:
        return ""


def _dec(v: str) -> str:
    try:
        if not v:
            return ""
        return _fernet().decrypt(v[4:].encode()).decode() if v.startswith("enc:") else v
    except Exception:
        return ""


# ---- INSTÂNCIAS de conector: um tipo + nome + credenciais próprias (ex.: "SharePoint Jurídico"). ----
# Vários da mesma família (2 SharePoints, 2 e-mails) coexistem; o agente anexa instâncias específicas.
def _conn_instancias():
    return APPSTATE.get("conectores_cfg", [])


def _conn_por_id(iid):
    return next((c for c in _conn_instancias() if c.get("id") == iid), None)


def _instancia_pub(inst):
    """Projeção segura: mostra QUAIS credenciais estão preenchidas, nunca o valor (••••)."""
    tipo = _mcp_lib().get(inst.get("tipo"), {})
    campos = tipo.get("env", []) or []
    envs = inst.get("env", {}) or {}
    return {"id": inst["id"], "tipo": inst.get("tipo"), "nome": inst.get("nome", ""),
            "icon": tipo.get("icon", "🔌"), "cat": tipo.get("cat", ""), "acoes": tipo.get("acoes", ""),
            "campos": campos,
            "credenciais": {k: ("••••••" if (envs.get(k) or "").strip() else "") for k in campos},
            "completo": all((envs.get(k) or "").strip() for k in campos) if campos else True}


def _agente_mcp_servers(a, revelar=False):
    """Materializa os conectores do agente no formato do NanoClaw (container_configs.mcp_servers).
    revelar=False (padrão, p/ UI): credenciais mascaradas. revelar=True: valores reais (só p/ o runtime)."""
    lib = _mcp_lib()
    out = {}
    for iid in (a.get("mcp") or []):
        inst = _conn_por_id(iid)
        if not inst:
            continue
        tipo = lib.get(inst.get("tipo"), {})
        envs = inst.get("env", {}) or {}
        env_out = {}
        for k in (tipo.get("env", []) or []):
            raw = envs.get(k, "")
            env_out[k] = _dec(raw) if revelar else ("••••••" if (raw or "").strip() else "")
        out[iid] = {"nome": inst.get("nome", ""), "command": tipo.get("command", "npx"),
                    "args": tipo.get("args", []), "env": env_out}
    return out


