def _seed_agentes_exemplo():
    """Idempotente: adiciona os agentes 'ex-' que faltam e afina persona/ferramentas/descrição para a versão atual.
    Anexa automaticamente uma instância de conector cujo tipo == mcp_hint (ex.: SharePoint), se já existir."""
    try:
        ags = _agentes()
        by_id = {a.get("id"): a for a in ags}
        insts = _conn_instancias()
        changed = False
        for ex in _AGENTES_EXEMPLO:
            mcp = []
            hint = ex.get("mcp_hint")
            if hint:
                mcp = [c["id"] for c in insts if c.get("tipo") == hint]   # anexa conector do tipo pedido, se configurado
            novo = {"id": ex["id"], "nome": ex["nome"], "descricao": ex["descricao"], "persona": ex["persona"],
                    "skill_id": "", "ferramentas": list(ex["ferramentas"]), "mcp": mcp, "colecao": "",
                    "modelo": "agent", "perfil_minimo": ex["perfil_minimo"], "ativo": True, "exemplo": True}
            cur = by_id.get(ex["id"])
            if cur is None:
                by_id[ex["id"]] = novo
                changed = True
            else:
                # preserva escolhas do usuário (coleção, modelo, mcp anexados, ativo) e afina só os textos/ferramentas
                for campo in ("nome", "descricao", "persona", "ferramentas"):
                    if cur.get(campo) != novo[campo]:
                        cur[campo] = novo[campo]; changed = True
                cur.setdefault("exemplo", True)
                if not cur.get("mcp") and mcp:
                    cur["mcp"] = mcp; changed = True
        if changed:
            APPSTATE["agentes"] = list(by_id.values())
            _appstate_save(APPSTATE)
            _event("agentes de exemplo", "biblioteca sincronizada (Excel/Word/PPT/SharePoint)")
    except Exception as ex:
        print("[cerne] seed agentes exemplo:", ex)


