@app.post("/ferramentas/mcp")
def ferramentas_mcp_add(body: McpCustomReq):
    """Adiciona um servidor MCP CUSTOM à biblioteca (extensibilidade: qualquer ferramenta não prevista)."""
    _assert_admin_sessao()
    if not (body.nome or "").strip():
        raise HTTPException(status_code=400, detail="informe o nome do conector")
    cid = body.id or ("custom_" + re.sub(r"[^a-z0-9_]", "", body.nome.lower().replace(" ", "_"))[:24] or uuid.uuid4().hex[:6])
    item = {"id": cid, "nome": body.nome.strip(), "cat": (body.categoria or "Custom").strip(), "icon": body.icon or "🔌",
            "acoes": (body.acoes or "").strip(), "command": (body.command or "npx").strip(),
            "args": [str(a) for a in (body.args or [])], "env": [str(e).strip() for e in (body.env or []) if str(e).strip()]}
    APPSTATE["mcp_custom"] = [c for c in _mcp_custom() if c.get("id") != cid] + [item]
    _appstate_save(APPSTATE)
    _event("conector MCP adicionado", f"{item['nome']} ({item['cat']})", actor=_actor())
    return item


@app.delete("/ferramentas/mcp/{cid}")
def ferramentas_mcp_del(cid: str):
    _assert_admin_sessao()
    APPSTATE["mcp_custom"] = [c for c in _mcp_custom() if c.get("id") != cid]
    _appstate_save(APPSTATE)
    return {"status": "removido", "id": cid}


# ---- Instâncias de conector configuradas (com credenciais cifradas) ----
class InstanciaReq(BaseModel):
    id: str | None = None
    tipo: str                                 # id do tipo (catálogo ou custom)
    nome: str                                 # nome da instância, ex.: "SharePoint Jurídico"
    env: dict = {}                            # {NOME_CREDENCIAL: valor} — cifrado ao salvar


@app.get("/conectores/instancias")
def conn_instancias_list(tipo: str = ""):
    insts = [_instancia_pub(c) for c in _conn_instancias() if (not tipo or c.get("tipo") == tipo)]
    return {"instancias": insts}


@app.post("/conectores/instancias")
def conn_instancia_save(body: InstanciaReq):
    _assert_admin_sessao()
    lib = _mcp_lib()
    tipo = lib.get(body.tipo)
    if not tipo:
        raise HTTPException(status_code=400, detail="tipo de conector inválido")
    if not (body.nome or "").strip():
        raise HTTPException(status_code=400, detail="dê um nome à configuração (ex.: SharePoint Jurídico)")
    atual = _conn_por_id(body.id) if body.id else None
    envs = dict((atual or {}).get("env", {}))                 # preserva credenciais não reenviadas
    for k in (tipo.get("env", []) or []):
        v = (body.env or {}).get(k)
        if v is None:
            continue
        v = str(v)
        if v == "" or v == "••••••":                          # vazio/placeholder = mantém o valor atual
            continue
        envs[k] = _enc(v)                                     # cifra em repouso
    item = {"id": (atual or {}).get("id") or ("ci_" + uuid.uuid4().hex[:8]),
            "tipo": body.tipo, "nome": body.nome.strip(), "env": envs}
    APPSTATE["conectores_cfg"] = [c for c in _conn_instancias() if c.get("id") != item["id"]] + [item]
    _appstate_save(APPSTATE)
    _event("conector configurado", f"{item['nome']} ({tipo.get('nome', body.tipo)})", actor=_actor())
    return _instancia_pub(item)


@app.delete("/conectores/instancias/{iid}")
def conn_instancia_del(iid: str):
    _assert_admin_sessao()
    inst = _conn_por_id(iid)
    if not inst:
        raise HTTPException(status_code=404, detail="configuração não encontrada")
    APPSTATE["conectores_cfg"] = [c for c in _conn_instancias() if c.get("id") != iid]
    # desanexa a instância de qualquer agente que a use
    for a in _agentes():
        if iid in (a.get("mcp") or []):
            a["mcp"] = [m for m in a["mcp"] if m != iid]
    _appstate_save(APPSTATE)
    _event("conector removido", inst.get("nome", ""), actor=_actor())
    return {"status": "removido", "id": iid}


