def _acervo_pub(inst):
    t = ACERVO_TIPOS.get(inst.get("tipo"), {})
    cfg = inst.get("cfg", {}) or {}
    campos = t.get("campos", [])
    vals = {}
    for c in campos:
        k = c["k"]
        vals[k] = ("••••••" if (cfg.get(k) or "").strip() else "") if c.get("secret") else cfg.get(k, "")
    return {"id": inst["id"], "tipo": inst.get("tipo"), "nome": inst.get("nome", ""),
            "icon": t.get("icon", "📧"), "cat": t.get("cat", "E-mail"), "acoes": t.get("acoes", ""),
            "colecao": inst.get("colecao", ""), "max_msgs": inst.get("max_msgs", 20),
            "valores": vals, "campos": campos,
            "completo": all((cfg.get(c["k"]) or "").strip() for c in campos if c.get("obrig", True))}


def _acervo_cfg_real(inst):
    """Descriptografa os campos secret para uso na ingestão."""
    t = ACERVO_TIPOS.get(inst.get("tipo"), {})
    cfg = dict(inst.get("cfg", {}) or {})
    for c in t.get("campos", []):
        if c.get("secret"):
            cfg[c["k"]] = _dec(cfg.get(c["k"], ""))
    return cfg


def _email_corpo(msg):
    from email.header import decode_header
    def _dh(v):
        try:
            return "".join((s.decode(enc or "utf-8", "ignore") if isinstance(s, bytes) else s) for s, enc in decode_header(v or ""))
        except Exception:
            return v or ""
    subj, frm = _dh(msg.get("Subject")), _dh(msg.get("From"))
    body, html = "", ""
    if msg.is_multipart():
        for part in msg.walk():
            ct = part.get_content_type()
            disp = str(part.get("Content-Disposition") or "")
            if "attachment" in disp:
                continue
            try:
                payload = part.get_payload(decode=True)
                if not payload:
                    continue
                txt = payload.decode(part.get_content_charset() or "utf-8", "ignore")
            except Exception:
                continue
            if ct == "text/plain":
                body += txt + "\n"
            elif ct == "text/html" and not html:
                html = txt
    else:
        try:
            body = (msg.get_payload(decode=True) or b"").decode(msg.get_content_charset() or "utf-8", "ignore")
        except Exception:
            body = ""
    if not body.strip() and html:
        body = _html_para_texto(html)
    return subj, frm, body.strip()


def _ingest_email(inst):
    t = ACERVO_TIPOS[inst["tipo"]]
    cfg = _acervo_cfg_real(inst)
    host, user, pw = cfg.get("host", ""), cfg.get("user", ""), cfg.get("password", "")
    n = max(1, min(200, int(inst.get("max_msgs", 20) or 20)))
    coll = inst.get("colecao") or COLLECTION
    if not (host and user and pw):
        raise HTTPException(status_code=400, detail="preencha servidor, usuário e senha da conta")
    emails_ok, chunks, erros = 0, 0, []

    def _index(raw):
        nonlocal emails_ok, chunks
        try:
            msg = email.message_from_bytes(raw)
            subj, frm, corpo = _email_corpo(msg)
            if not corpo:
                return
            texto = f"De: {frm}\nAssunto: {subj}\n\n{corpo}"
            r = _ingest(texto, f"email: {(subj or '(sem assunto)')[:80]}", coll)
            chunks += r.get("chunks_indexed", 0)
            emails_ok += 1
        except Exception as ex:
            erros.append(str(ex)[:60])
    try:
        if t["proto"] == "imap":
            import imaplib
            port = int(cfg.get("port") or 993)
            M = imaplib.IMAP4_SSL(host, port)
            M.login(user, pw)
            M.select(cfg.get("pasta") or "INBOX", readonly=True)
            typ, data = M.search(None, "ALL")
            ids = (data[0].split() if data and data[0] else [])[-n:]
            for i in reversed(ids):
                typ, d = M.fetch(i, "(RFC822)")
                if d and d[0]:
                    _index(d[0][1])
            M.logout()
        else:
            import poplib
            port = int(cfg.get("port") or 995)
            M = poplib.POP3_SSL(host, port)
            M.user(user)
            M.pass_(pw)
            cnt = len(M.list()[1])
            for k in range(cnt, max(0, cnt - n), -1):
                _index(b"\r\n".join(M.retr(k)[1]))
            M.quit()
    except HTTPException:
        raise
    except Exception as ex:
        _conn_stat("email", f"{inst.get('nome')} → {coll}", erro=str(ex)[:90])
        raise HTTPException(status_code=400, detail=f"falha na conexão de e-mail: {str(ex)[:140]}")
    _conn_stat("email", f"{inst.get('nome')} → {coll} · {emails_ok} e-mails · {chunks} trechos")
    return {"emails": emails_ok, "chunks": chunks, "erros": erros[:3]}


def _ingest_db(inst):
    """Ingestão genérica de banco SQL via connection string (SQLAlchemy): roda 1 SELECT e indexa as linhas."""
    from sqlalchemy import create_engine, text
    cfg = _acervo_cfg_real(inst)
    cs = (cfg.get("connection_string") or "").strip()
    q = (cfg.get("query") or "").strip()
    coll = inst.get("colecao") or COLLECTION
    n = max(1, min(5000, int(inst.get("max_msgs", 200) or 200)))
    if not cs or not q:
        raise HTTPException(status_code=400, detail="preencha a connection string e a consulta SQL")
    if not re.match(r"(?is)^\s*(select|with)\b", q):          # segurança: só leitura
        raise HTTPException(status_code=400, detail="por segurança, apenas consultas SELECT/WITH são permitidas")
    linhas, chunks = 0, 0
    try:
        eng = create_engine(cs, pool_pre_ping=True)
        with eng.connect() as con:
            res = con.execute(text(q))
            cols = list(res.keys())
            for i, row in enumerate(res):
                if i >= n:
                    break
                d = dict(zip(cols, row))
                texto = "\n".join(f"{k}: {v}" for k, v in d.items() if v is not None)
                if texto.strip():
                    r = _ingest(texto, f"{inst.get('nome', 'db')}: linha {i + 1}", coll)
                    chunks += r.get("chunks_indexed", 0)
                    linhas += 1
        eng.dispose()
    except HTTPException:
        raise
    except Exception as ex:
        _conn_stat("db", f"{inst.get('nome')} → {coll}", erro=str(ex)[:90])
        raise HTTPException(status_code=400, detail=f"falha ao consultar o banco: {str(ex)[:160]}")
    _conn_stat("db", f"{inst.get('nome')} → {coll} · {linhas} linhas · {chunks} trechos")
    return {"linhas": linhas, "chunks": chunks}


class AcervoConnReq(BaseModel):
    id: str | None = None
    tipo: str
    nome: str
    colecao: str = ""
    max_msgs: int = 20
    cfg: dict = {}


@app.get("/acervo-conectores")
def acervo_conn_list():
    tipos = {k: {"nome": v["nome"], "cat": v["cat"], "icon": v["icon"], "acoes": v["acoes"], "campos": v["campos"]}
             for k, v in ACERVO_TIPOS.items()}
    return {"tipos": tipos, "instancias": [_acervo_pub(c) for c in _acervo_conns()]}


@app.post("/acervo-conectores")
def acervo_conn_save(body: AcervoConnReq):
    _assert_admin_sessao()
    t = ACERVO_TIPOS.get(body.tipo)
    if not t:
        raise HTTPException(status_code=400, detail="tipo de conector inválido")
    if not (body.nome or "").strip():
        raise HTTPException(status_code=400, detail="dê um nome à conta (ex.: E-mail Comercial)")
    atual = _acervo_por_id(body.id) if body.id else None
    cfg = dict((atual or {}).get("cfg", {}))
    for c in t["campos"]:
        k = c["k"]
        v = (body.cfg or {}).get(k)
        if v is None:
            continue
        v = str(v)
        if c.get("secret"):
            if v in ("", "••••••"):
                continue                                      # mantém o segredo atual
            cfg[k] = _enc(v)
        else:
            cfg[k] = v
    item = {"id": (atual or {}).get("id") or ("ac_" + uuid.uuid4().hex[:8]), "tipo": body.tipo,
            "nome": body.nome.strip(), "colecao": (body.colecao or "").strip(),
            "max_msgs": max(1, min(200, int(body.max_msgs or 20))), "cfg": cfg}
    APPSTATE["acervo_conns"] = [c for c in _acervo_conns() if c.get("id") != item["id"]] + [item]
    _appstate_save(APPSTATE)
    _event("conector de acervo configurado", f"{item['nome']} ({t['nome']})", actor=_actor())
    return _acervo_pub(item)


@app.delete("/acervo-conectores/{iid}")
def acervo_conn_del(iid: str):
    _assert_admin_sessao()
    if not _acervo_por_id(iid):
        raise HTTPException(status_code=404, detail="conta não encontrada")
    APPSTATE["acervo_conns"] = [c for c in _acervo_conns() if c.get("id") != iid]
    _appstate_save(APPSTATE)
    return {"status": "removido", "id": iid}


@app.post("/acervo-conectores/{iid}/ingerir")
def acervo_conn_ingerir(iid: str):
    inst = _acervo_por_id(iid)
    if not inst:
        raise HTTPException(status_code=404, detail="conta não encontrada")
    proto = ACERVO_TIPOS.get(inst.get("tipo"), {}).get("proto")
    return _ingest_db(inst) if proto == "sql" else _ingest_email(inst)


# ============ LLMs pagas (Anthropic/OpenAI/Gemini) — configuradas pela UI, chave cifrada ============
# Registradas no gateway LiteLLM em runtime (store_model_in_db) — entram nas regras de híbrido + PII.
def _litellm_apply(alias, model_str, api_key, api_base=None):
    try:                                                     # remove entradas antigas do mesmo nome (idempotente)
        info = httpx.get(f"{GATEWAY_URL}/model/info", headers=HEADERS, timeout=15).json()
        for m in (info.get("data") or []):
            if m.get("model_name") == alias:
                mid = (m.get("model_info") or {}).get("id")
                if mid:
                    httpx.post(f"{GATEWAY_URL}/model/delete", headers=HEADERS, json={"id": mid}, timeout=15)
    except Exception:
        pass
    params = {"model": model_str, "api_key": api_key}
    if api_base:                                             # provedores OpenAI-compatíveis com base própria (ex.: Moonshot)
        params["api_base"] = api_base
    r = httpx.post(f"{GATEWAY_URL}/model/new", headers=HEADERS,
                   json={"model_name": alias, "litellm_params": params}, timeout=25)
    r.raise_for_status()


def _litellm_remove(alias):
    try:
        info = httpx.get(f"{GATEWAY_URL}/model/info", headers=HEADERS, timeout=15).json()
        for m in (info.get("data") or []):
            if m.get("model_name") == alias:
                mid = (m.get("model_info") or {}).get("id")
                if mid:
                    httpx.post(f"{GATEWAY_URL}/model/delete", headers=HEADERS, json={"id": mid}, timeout=15)
    except Exception:
        pass


def _llms_pagas_reaplicar():
    """No startup, re-registra no gateway as pagas já configuradas (sobrevive a reset do gateway).
    Auto-repara: se o modelo salvo saiu do catálogo (ex.: ID descontinuado), migra para o default atual."""
    cfg = APPSTATE.get("llm_pagas") or {}
    changed = False
    for a, c in cfg.items():
        meta = LLM_PAGAS.get(a)
        if not (meta and c.get("api_key") and c.get("ativo", True)):
            continue
        model = c.get("model")
        if model not in meta["modelos"]:                       # modelo obsoleto → volta ao default válido
            model = meta["default"]
            c["model"] = model
            changed = True
        try:
            _litellm_apply(a, f"{meta['provider']}/{model}", _dec(c["api_key"]), meta.get("api_base"))
        except Exception as ex:
            print("[cerne] reaplicar LLM paga:", a, str(ex)[:80])
    if changed:
        _appstate_save(APPSTATE)


class LlmPagaReq(BaseModel):
    alias: str
    model: str = ""
    api_key: str = ""
    ativo: bool = True


@app.get("/llms-pagas")
def llms_pagas_list():
    cfg = APPSTATE.get("llm_pagas") or {}
    out = {}
    for a, meta in LLM_PAGAS.items():
        c = cfg.get(a) or {}
        out[a] = {"nome": meta["nome"], "site": meta.get("site"), "modelos": meta["modelos"], "default": meta["default"],
                  "tags": meta.get("tags", []), "configurado": bool(c.get("api_key")),
                  "model": c.get("model") or meta["default"], "ativo": bool(c.get("ativo", True)) if c else False,
                  "chave": "••••••" if c.get("api_key") else ""}
    return {"pagas": out}


@app.post("/llms-pagas")
def llms_pagas_save(body: LlmPagaReq):
    _assert_admin_sessao()
    meta = LLM_PAGAS.get(body.alias)
    if not meta:
        raise HTTPException(status_code=400, detail="provedor inválido")
    cfg = dict(APPSTATE.get("llm_pagas") or {})
    cur = dict(cfg.get(body.alias) or {})
    model = (body.model or "").strip() or cur.get("model") or meta["default"]
    if model not in meta["modelos"]:
        model = meta["default"]
    key = (body.api_key or "").strip()
    key_enc = cur.get("api_key") if key in ("", "••••••") else _enc(key)
    if not key_enc:
        raise HTTPException(status_code=400, detail="informe a chave de API do provedor")
    try:
        _litellm_apply(body.alias, f"{meta['provider']}/{model}", _dec(key_enc), meta.get("api_base"))
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"o gateway recusou a configuração (chave inválida?): {str(e)[:160]}")
    cfg[body.alias] = {"model": model, "api_key": key_enc, "ativo": bool(body.ativo)}
    APPSTATE["llm_pagas"] = cfg
    _appstate_save(APPSTATE)
    _event("LLM paga configurada", f"{meta['nome']} · {model}", actor=_actor())
    return {"ok": True, "alias": body.alias, "model": model, "configurado": True}


@app.delete("/llms-pagas/{alias}")
def llms_pagas_del(alias: str):
    _assert_admin_sessao()
    _litellm_remove(alias)
    cfg = dict(APPSTATE.get("llm_pagas") or {})
    cfg.pop(alias, None)
    APPSTATE["llm_pagas"] = cfg
    o = APPSTATE.get("org")
    if o and alias in (o.get("provedores_habilitados") or []):
        o["provedores_habilitados"] = [p for p in o["provedores_habilitados"] if p != alias]
    _appstate_save(APPSTATE)
    _event("LLM paga removida", alias, actor=_actor())
    return {"status": "removido", "alias": alias}


