# ---- Loop REAL de execução de ferramentas do agente (fecha o gap vs Codex/Cowork: ferramenta que EXECUTA, não só declarada) ----
def _extract_json(text, need_key=None):
    """Extrai o 1º objeto JSON BALANCEADO (aguenta chaves aninhadas e strings com { }). Se need_key, exige que o
    dict contenha essa chave. Muito mais robusto que regex — necessário p/ specs de planilha/documento/apresentação."""
    if not text:
        return None
    i = text.find("{")
    while i != -1:
        depth = 0; instr = False; esc = False
        for j in range(i, len(text)):
            ch = text[j]
            if instr:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == '"':
                    instr = False
            elif ch == '"':
                instr = True
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    try:
                        o = json.loads(text[i:j + 1])
                        if isinstance(o, dict) and (need_key is None or o.get(need_key) is not None):
                            return o
                    except Exception:
                        pass
                    break
        i = text.find("{", i + 1)
    return None


def _parse_tool_call(text):
    return _extract_json(text, need_key="ferramenta")


# ---- Fast-path DETERMINÍSTICO de Office: detecta a intenção e faz o modelo produzir SÓ o JSON de dados (tarefa
# muito mais fácil p/ modelo local do que escolher+formatar ferramentas). Garante entrega real de .xlsx/.docx/.pptx.
_GERAR_VERBO = re.compile(r"\b(cri[ae]|gera?r?|gere|mont[ae]|montar|fa[çc]a|elabor|prepar|produz|constru|desenvolv|refa[çc]|atualiz|escrev|redij|prepare)", re.I)
_OFFICE_SCHEMAS = {
    "planilha": '{"nome":"planilha.xlsx","abas":[{"nome":"Dados","colunas":["Coluna A","Coluna B"],"linhas":[["exemplo",10]],"totais":{"Coluna B":"soma"}}]}',
    "documento": '{"nome":"documento.docx","titulo":"Título","secoes":[{"titulo":"Seção 1","paragrafos":["texto do parágrafo"],"tabela":{"colunas":["Item","Valor"],"linhas":[["exemplo",1]]}}]}',
    "apresentacao": '{"nome":"apresentacao.pptx","titulo":"Título","subtitulo":"subtítulo","slides":[{"titulo":"Slide 1","topicos":["ponto 1","ponto 2"]}]}',
}


def _office_intent(texto):
    t = (texto or "").lower()
    kinds = []
    if re.search(r"planilha|excel|xlsx|\.xls|c[áa]lculo|or[çc]amento", t):
        kinds.append("planilha")
    if re.search(r"apresenta|slides?|power\s?point|pptx?|\bdeck\b", t):
        kinds.append("apresentacao")
    if re.search(r"\bdocumento\b|\bword\b|docx|relat[óo]ri|of[íi]cio|\bcarta\b|contrato|\bata\b|parecer|petiç|memorand|\bdocx\b", t):
        kinds.append("documento")
    return kinds


def _office_spec(kind, task, contexto=""):
    """Pede ao modelo APENAS o JSON de dados no formato do `kind`. Retorna dict ou None (com 1 retry mais rígido)."""
    schema = _OFFICE_SCHEMAS[kind]
    instr = ("Você monta a ESTRUTURA de dados para gerar um arquivo Office. Responda SOMENTE com UM JSON válido, "
             "sem comentários e sem texto fora dele, exatamente neste formato (troque pelos dados reais):\n" + schema +
             "\n\nRegras: use os dados REAIS da solicitação; não invente números; escreva em português; se algum "
             "dado não existir, crie mesmo assim colunas/seções coerentes." +
             (("\n\nContexto de apoio:\n" + contexto[:2500]) if contexto else "") +
             "\n\nSolicitação:\n" + (task or "")[:3000])
    for tent in range(2):
        try:
            raw = _strip_think(chat_model("chat", [{"role": "user", "content": instr}], max_tokens=1800) or "")
        except Exception:
            return None
        spec = _extract_json(raw)
        if isinstance(spec, dict):
            return spec
        instr += "\n\nATENÇÃO: responda APENAS com o JSON, começando com '{' e terminando com '}'. Nada além disso."
    return None


# ---- Ferramentas EXECUTÁVEIS do agente (código sandbox + arquivos + delegação) ----
_AGENT_CODE_EXEC = os.getenv("AGENT_CODE_EXEC", "1") == "1"
SANDBOX_URL = os.getenv("SANDBOX_URL", "").rstrip("/")     # container isolado; vazio = fallback subprocesso local
RENDER_URL = os.getenv("RENDER_URL", "").rstrip("/")       # renderizador Chromium (HTML → PNG/PDF/MP4); vazio = desligado


def _render_call(html, fmt, dur=8.0, width=1280, height=800):
    """Chama o renderizador Chromium (container separado). Retorna (bytes, erro)."""
    if not RENDER_URL:
        return None, "renderizador indisponível (configure o serviço render)"
    try:
        r = httpx.post(f"{RENDER_URL}/render", timeout=200,
                       json={"html": html or "", "format": fmt, "dur": dur, "width": width, "height": height})
        if r.status_code == 200:
            return r.content, None
        return None, f"render {r.status_code}: {r.text[:120]}"
    except Exception as e:
        return None, f"render erro: {str(e)[:120]}"
_SAFE_ENV = {"PATH": os.getenv("PATH", "/usr/local/bin:/usr/bin:/bin"), "LANG": "C.UTF-8", "HOME": "/tmp"}


def _sb_localdir(run_id):
    safe = "".join(c for c in (run_id or "default") if c.isalnum() or c in "-_")[:48] or "default"
    d = os.path.join(tempfile.gettempdir(), "cerne_sb", safe)
    os.makedirs(d, exist_ok=True)
    return d


def _sandbox_exec(codigo, lang, run_id, timeout=15):
    """Executa código do agente. Preferência: CONTAINER ISOLADO (SANDBOX_URL) — outro container, non-root,
    SEM segredos, com limites (mem/pids) e rede segmentada dos serviços internos. Sem SANDBOX_URL cai p/
    subprocesso local (env sem segredos, python -I). Desligável por AGENT_CODE_EXEC=0."""
    if not _AGENT_CODE_EXEC:
        return "(execução de código desabilitada pela organização)"
    lang = (lang or "python").lower()
    if SANDBOX_URL:
        try:
            r = httpx.post(f"{SANDBOX_URL}/run", json={"workdir": run_id, "linguagem": lang,
                           "codigo": codigo or "", "timeout": timeout}, timeout=timeout + 12)
            return (r.json().get("saida") or "")[:6000]
        except Exception as e:
            return f"(sandbox isolado indisponível: {str(e)[:120]})"
    d = _sb_localdir(run_id)
    try:
        if lang in ("python", "py"):
            open(os.path.join(d, "_run.py"), "w", encoding="utf-8").write(codigo or ""); cmd = ["python", "-I", "_run.py"]
        elif lang in ("bash", "sh", "shell"):
            open(os.path.join(d, "_run.sh"), "w", encoding="utf-8").write(codigo or ""); cmd = ["bash", "_run.sh"]
        else:
            return f"(linguagem '{lang}' não suportada; use python ou bash)"
        r = subprocess.run(cmd, cwd=d, env=_SAFE_ENV, capture_output=True, text=True, timeout=timeout)
        out = (r.stdout or "") + (("\n[stderr]\n" + r.stderr) if r.stderr else "")
        return out[:6000] or f"(sem saída · retorno {r.returncode})"
    except subprocess.TimeoutExpired:
        return f"(tempo esgotado — passou de {timeout}s)"
    except Exception as e:
        return f"(erro ao executar: {str(e)[:200]})"


def _sb_write(run_id, nome, conteudo):
    if SANDBOX_URL:
        try:
            httpx.post(f"{SANDBOX_URL}/write", json={"workdir": run_id, "nome": nome, "conteudo": conteudo or ""}, timeout=15)
            return f"(arquivo '{os.path.basename(nome or '')}' escrito no workspace)"
        except Exception as e:
            return f"(erro ao escrever: {str(e)[:100]})"
    p = os.path.join(_sb_localdir(run_id), os.path.basename(nome or "arquivo.txt"))
    try:
        open(p, "w", encoding="utf-8").write(conteudo or ""); return f"(arquivo '{os.path.basename(nome or '')}' escrito)"
    except Exception as e:
        return f"(erro ao escrever: {str(e)[:100]})"


def _sb_read(run_id, nome):
    if SANDBOX_URL:
        try:
            j = httpx.post(f"{SANDBOX_URL}/read", json={"workdir": run_id, "nome": nome}, timeout=15).json()
            return j.get("conteudo") if "conteudo" in j else f"(erro: {j.get('erro', '')})"
        except Exception as e:
            return f"(erro: {str(e)[:80]})"
    try:
        return open(os.path.join(_sb_localdir(run_id), os.path.basename(nome or "")), encoding="utf-8", errors="ignore").read()[:6000]
    except Exception as e:
        return f"(erro: {str(e)[:80]})"


def _sb_reset(run_id):
    if SANDBOX_URL:
        try:
            httpx.post(f"{SANDBOX_URL}/reset", json={"workdir": run_id}, timeout=10)
        except Exception:
            pass
    else:
        shutil.rmtree(_sb_localdir(run_id), ignore_errors=True)


# ---- Artefatos gerados pelos agentes (Excel/Word/PPT/…): copiados do sandbox efêmero p/ um store baixável ----
_ART_DIR = os.getenv("AGENT_ART_DIR", "/data/app/agent_artifacts")
_ART_TTL_H = 12               # arquivos gerados ficam disponíveis por 12h e depois são apagados


def _art_purge():
    try:
        agora = time.time()
        for r in os.listdir(_ART_DIR):
            p = os.path.join(_ART_DIR, r)
            if os.path.isdir(p) and (agora - os.path.getmtime(p)) > _ART_TTL_H * 3600:
                shutil.rmtree(p, ignore_errors=True)
    except Exception:
        pass


def _agente_coletar_artefatos(run_id):
    """Copia os arquivos que o agente gerou no workspace isolado para um store persistente e retorna
    [{nome, url, bytes}] com links de download. Chamar ANTES do _sb_reset. Máx. 12 arquivos, 25MB cada."""
    if not run_id:
        return []
    out = []
    try:
        os.makedirs(_ART_DIR, exist_ok=True)
        destdir = os.path.join(_ART_DIR, run_id)
        # lista os artefatos (remoto via HTTP; local via filesystem)
        if SANDBOX_URL:
            itens = (httpx.post(f"{SANDBOX_URL}/list", json={"workdir": run_id}, timeout=15).json() or {}).get("arquivos", [])
        else:
            ld = _sb_localdir(run_id)
            itens = [{"nome": n, "bytes": os.path.getsize(os.path.join(ld, n))}
                     for n in sorted(os.listdir(ld)) if os.path.isfile(os.path.join(ld, n)) and not n.startswith("_run.")]
        for it in itens[:12]:
            nome = os.path.basename(it.get("nome") or "")
            if not nome or it.get("bytes", 0) > 25 * 1024 * 1024:
                continue
            if SANDBOX_URL:
                import base64
                j = httpx.post(f"{SANDBOX_URL}/download", json={"workdir": run_id, "nome": nome}, timeout=30).json()
                if "b64" not in j:
                    continue
                dados = base64.b64decode(j["b64"])
            else:
                dados = open(os.path.join(_sb_localdir(run_id), nome), "rb").read()
            os.makedirs(destdir, exist_ok=True)
            open(os.path.join(destdir, nome), "wb").write(dados)
            out.append({"nome": nome, "url": f"/agentes/artefato/{run_id}/{nome}", "bytes": len(dados)})
        _art_purge()
    except Exception as e:
        print("[cerne] coletar artefatos:", str(e)[:120])
    return out


def _art_salvar_bytes(run_id, nome, dados, mime="application/octet-stream"):
    """Grava bytes crus (ex.: vídeo gerado por IA) direto no store persistente e devolve {nome,url,bytes}."""
    nome = os.path.basename(nome or "arquivo.bin")
    destdir = os.path.join(_ART_DIR, run_id)
    os.makedirs(destdir, exist_ok=True)
    open(os.path.join(destdir, nome), "wb").write(dados)
    _art_purge()
    return {"nome": nome, "url": f"/agentes/artefato/{run_id}/{nome}", "bytes": len(dados)}


def _sb_download_bytes(run_id, nome):
    """Bytes crus de um arquivo do workspace do sandbox (p/ upload à nuvem)."""
    nome = os.path.basename(nome or "")
    try:
        if SANDBOX_URL:
            import base64
            j = httpx.post(f"{SANDBOX_URL}/download", json={"workdir": run_id, "nome": nome}, timeout=30).json()
            return base64.b64decode(j["b64"]) if "b64" in j else None
        p = os.path.join(_sb_localdir(run_id), nome)
        return open(p, "rb").read() if os.path.isfile(p) else None
    except Exception:
        return None


def _nuvem_upload_atual(call, workdir):
    """Ferramenta 'nuvem': envia um arquivo gerado no workspace para OneDrive/SharePoint (Graph)."""
    if not workdir:
        return "(sem workspace — gere o arquivo antes com planilha/documento/código)"
    cid = call.get("conector") or call.get("conector_id")
    inst = _conn_por_id(cid) if cid else next((c for c in _conn_instancias() if c.get("tipo") in ("onedrive", "sharepoint")), None)
    if not inst:
        return "(nenhum conector OneDrive/SharePoint configurado — adicione um em Conectores)"
    nome = os.path.basename(call.get("arquivo") or call.get("nome") or "")
    if not nome:
        return "(informe o nome do arquivo gerado a enviar)"
    dados = _sb_download_bytes(workdir, nome)
    if not dados:
        return f"(arquivo '{nome}' não está no workspace — gere-o antes)"
    env = {k: _dec(v) for k, v in (inst.get("env") or {}).items()}
    return _graph_upload(env, call.get("pasta") or call.get("caminho") or "", nome, dados)


_ART_MIME = {".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
             ".docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
             ".pptx": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
             ".pdf": "application/pdf", ".csv": "text/csv", ".json": "application/json",
             ".txt": "text/plain", ".zip": "application/zip", ".png": "image/png",
             ".mp4": "video/mp4", ".gif": "image/gif", ".jpg": "image/jpeg", ".jpeg": "image/jpeg",
             ".html": "text/html", ".webp": "image/webp", ".svg": "image/svg+xml"}


@app.get("/agentes/artefato/{run}/{nome}")
def agentes_artefato(run: str, nome: str):
    """Baixa um arquivo que um agente gerou no ambiente isolado (protegido por sessão via middleware)."""
    safe_run = "".join(c for c in (run or "") if c.isalnum() or c in "-_")[:64]
    safe_nome = os.path.basename(nome or "")
    base = os.path.realpath(_ART_DIR)
    p = os.path.realpath(os.path.join(_ART_DIR, safe_run, safe_nome))
    if not safe_run or not safe_nome or not p.startswith(base + os.sep) or not os.path.isfile(p):
        raise HTTPException(status_code=404, detail="artefato não encontrado ou expirado")
    mime = _ART_MIME.get(os.path.splitext(safe_nome)[1].lower(), "application/octet-stream")
    return FileResponse(p, media_type=mime, filename=safe_nome)


# ---- Geradores DETERMINÍSTICOS de Office: o modelo só produz a ESTRUTURA (JSON simples); o backend gera
# código Python seguro (spec embutida em base64, sem injeção) que roda no sandbox isolado e cria o arquivo real.
# Muito mais confiável que pedir ao modelo local para escrever Python — e 100% real (openpyxl/python-docx/python-pptx).
def _office_nome(spec, ext, padrao):
    n = os.path.basename(str(spec.get("nome") or padrao)).strip() or padrao
    if not n.lower().endswith(ext):
        n = os.path.splitext(n)[0] + ext
    return "".join(c for c in n if c.isalnum() or c in "-_. ")[:60] or padrao


def _office_code(kind, spec):
    """Retorna (codigo_python, nome_arquivo) para gerar um arquivo Office a partir da estrutura `spec`."""
    import base64
    b64 = base64.b64encode(json.dumps(spec, ensure_ascii=False).encode("utf-8")).decode()
    head = f'import base64, json\nSPEC = json.loads(base64.b64decode("{b64}").decode("utf-8"))\n'
    if kind == "planilha":
        nome = _office_nome(spec, ".xlsx", "planilha.xlsx")
        code = head + f'''
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill
wb = Workbook(); primeiro = True
abas = SPEC.get("abas") or [{{"nome": "Planilha", "colunas": SPEC.get("colunas"), "linhas": SPEC.get("linhas")}}]
for aba in abas:
    ws = wb.active if primeiro else wb.create_sheet(); primeiro = False
    ws.title = (str(aba.get("nome") or "Planilha"))[:31]
    cols = aba.get("colunas") or []
    if cols:
        ws.append([str(c) for c in cols])
        for c in ws[1]:
            c.font = Font(bold=True, color="FFFFFF"); c.fill = PatternFill("solid", fgColor="1F6F6F")
    linhas = aba.get("linhas") or []
    for row in linhas:
        ws.append(list(row) if isinstance(row, (list, tuple)) else [row])
    tot = aba.get("totais") or {{}}
    if tot and cols and linhas:
        from openpyxl.utils import get_column_letter as _gcl
        base = len(linhas); ln = base + 2
        ws.cell(row=ln, column=1, value="TOTAL").font = Font(bold=True)
        lc = [str(x).strip().lower() for x in cols]
        fmap = {{"soma": "SUM", "media": "AVERAGE", "max": "MAX", "min": "MIN"}}
        for letra, modo in tot.items():
            try:
                idx = lc.index(str(letra).strip().lower()) + 1
            except ValueError:
                continue
            L = _gcl(idx); fn = fmap.get(str(modo).lower(), "SUM")
            ws.cell(row=ln, column=idx, value="=" + fn + "(" + L + "2:" + L + str(base + 1) + ")").font = Font(bold=True)
    for col in ws.columns:
        w = max((len(str(c.value)) for c in col if c.value is not None), default=8)
        ws.column_dimensions[col[0].column_letter].width = min(max(w + 2, 10), 40)
wb.save("{nome}"); print("OK arquivo:", "{nome}")
'''
        return code, nome
    if kind == "documento":
        nome = _office_nome(spec, ".docx", "documento.docx")
        code = head + f'''
from docx import Document
from docx.shared import Pt
doc = Document()
if SPEC.get("titulo"): doc.add_heading(str(SPEC["titulo"]), 0)
if SPEC.get("subtitulo"):
    p = doc.add_paragraph(str(SPEC["subtitulo"])); p.runs[0].italic = True
for sec in (SPEC.get("secoes") or []):
    if sec.get("titulo"): doc.add_heading(str(sec["titulo"]), level=1)
    for par in (sec.get("paragrafos") or []): doc.add_paragraph(str(par))
    for it in (sec.get("lista") or []): doc.add_paragraph(str(it), style="List Bullet")
    tab = sec.get("tabela") or {{}}
    cols = tab.get("colunas") or []
    if cols:
        t = doc.add_table(rows=1, cols=len(cols))
        try: t.style = "Light Grid Accent 1"
        except Exception: pass
        for i, c in enumerate(cols): t.rows[0].cells[i].text = str(c)
        for row in (tab.get("linhas") or []):
            cells = t.add_row().cells
            for i, v in enumerate((list(row) if isinstance(row, (list, tuple)) else [row])[:len(cols)]): cells[i].text = str(v)
doc.save("{nome}"); print("OK arquivo:", "{nome}")
'''
        return code, nome
    if kind == "apresentacao":
        nome = _office_nome(spec, ".pptx", "apresentacao.pptx")
        code = head + f'''
from pptx import Presentation
prs = Presentation()
cap = prs.slides.add_slide(prs.slide_layouts[0])
cap.shapes.title.text = str(SPEC.get("titulo") or "Apresentação")
try:
    if SPEC.get("subtitulo"): cap.placeholders[1].text = str(SPEC["subtitulo"])
except Exception: pass
for s in (SPEC.get("slides") or []):
    sl = prs.slides.add_slide(prs.slide_layouts[1])
    sl.shapes.title.text = str(s.get("titulo") or "")
    tops = s.get("topicos") or ([str(s.get("texto"))] if s.get("texto") else [])
    if tops:
        tf = sl.placeholders[1].text_frame; tf.text = str(tops[0])
        for t in tops[1:]:
            p = tf.add_paragraph(); p.text = str(t)
prs.save("{nome}"); print("OK arquivo:", "{nome}")
'''
        return code, nome
    return None, None


def _office_url_code(url, nome):
    """Código DETERMINÍSTICO: baixa uma URL/API pública (JSON) e monta um .xlsx com os dados REAIS —
    sem depender do modelo escrever código. Achata a lista de registros e usa as chaves como colunas."""
    return f'''
import requests, json
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill
r = requests.get({url!r}, timeout=30, headers={{"User-Agent": "Mozilla/5.0 (CerneBot)"}})
try:
    data = r.json()
except Exception:
    data = None
def _records(d):
    if isinstance(d, list):
        return d
    if isinstance(d, dict):
        for v in d.values():
            if isinstance(v, list) and v and isinstance(v[0], dict):
                return v
        return [d]
    return []
recs = [x for x in _records(data) if isinstance(x, dict)]
cols = []
for x in recs[:300]:
    for k in x.keys():
        if str(k) not in cols:
            cols.append(str(k))
wb = Workbook(); ws = wb.active; ws.title = "Dados"
if cols:
    ws.append(cols)
    for c in ws[1]:
        c.font = Font(bold=True, color="FFFFFF"); c.fill = PatternFill("solid", fgColor="1F6F6F")
    for x in recs:
        ws.append([json.dumps(x.get(k), ensure_ascii=False) if isinstance(x.get(k), (list, dict)) else x.get(k) for k in cols])
    for col in ws.columns:
        w = max((len(str(c.value)) for c in col if c.value is not None), default=10)
        ws.column_dimensions[col[0].column_letter].width = min(max(w + 2, 12), 48)
else:
    ws.append(["resposta"]); ws.append([str(data)[:3000]])
wb.save({nome!r}); print("OK arquivo:", {nome!r}, "| linhas:", len(recs), "| status:", r.status_code)
'''


# ================= Ponte do NAVEGADOR do usuário (extensão Chrome/Edge) =================
# O agente opera o navegador que o próprio usuário já usa, via extensão do Cerne. Fluxo soberano:
# agente -> fila do usuário -> a extensão faz long-poll -> executa no navegador -> devolve o resultado.
# Sem servidores externos: tudo passa pelo SEU Cerne. Uma moldura aparece na página enquanto o Cerne atua.
_EXT_CH = {}                     # user_id -> {"q": Queue, "res": {}, "ev": {}, "last_hello": ts, "info": {}}
_EXT_LOCK = threading.Lock()


def _ext_tokens():
    return APPSTATE.setdefault("ext_tokens", {})


def _ext_channel(uid):
    with _EXT_LOCK:
        ch = _EXT_CH.get(uid)
        if not ch:
            ch = {"q": queue.Queue(), "res": {}, "ev": {}, "last_hello": 0.0, "info": {},
                  "desktop_q": queue.Queue(), "desktop_hello": 0.0, "office": {}}
            _EXT_CH[uid] = ch
        return ch


_OFFICE_HOSTS = {"excel", "word", "ppt"}


def _office_ch(uid, host):
    ch = _ext_channel(uid)
    with _EXT_LOCK:
        o = ch["office"].get(host)
        if not o:
            o = {"q": queue.Queue(), "res": {}, "ev": {}, "hello": 0.0}
            ch["office"][host] = o
        return o


def _office_conectado(uid, host):
    o = (_EXT_CH.get(uid) or {}).get("office", {}).get(host)
    return bool(o and (time.time() - o["hello"] < 90))


def _office_hosts_ativos(uid):
    return [h for h in _OFFICE_HOSTS if _office_conectado(uid, h)]


def _office_exec(uid, host, cmd, timeout=45):
    o = _office_ch(uid, host)
    cid = uuid.uuid4().hex[:10]
    ev = threading.Event(); o["ev"][cid] = ev
    o["q"].put(dict(cmd, id=cid))
    if not ev.wait(timeout):
        o["ev"].pop(cid, None)
        return {"erro": "sem resposta do add-in do Office (o painel do Cerne está aberto no app?)"}
    res = o["res"].pop(cid, None); o["ev"].pop(cid, None)
    return res if isinstance(res, dict) else {"erro": "resposta vazia"}


def _office_exec_atual(call):
    """Ferramenta do agente: opera o Excel/Word/PowerPoint ABERTO do usuário via o add-in (Office.js)."""
    u = _usuario_atual()
    if not u:
        return "(sem usuário na sessão — Office indisponível)"
    uid = u.get("id")
    host = (call.get("app") or call.get("host") or "").lower()
    host = {"powerpoint": "ppt", "xls": "excel", "planilha": "excel", "doc": "word"}.get(host, host)
    if host not in _OFFICE_HOSTS:
        ativos = _office_hosts_ativos(uid)
        host = ativos[0] if ativos else ""
    if not host or not _office_conectado(uid, host):
        ativos = _office_hosts_ativos(uid)
        return (f"(nenhum add-in do Office conectado para '{host or 'o app pedido'}'. "
                f"Apps conectados agora: {', '.join(ativos) or 'nenhum'}. Instale o add-in do Cerne no Excel/Word/"
                f"PowerPoint e pareie em Agentes → Navegador do usuário.)")
    cmd = {"acao": (call.get("acao") or "ler"), "celula": call.get("celula"), "valor": call.get("valor"),
           "intervalo": call.get("intervalo"), "valores": call.get("valores"), "formula": call.get("formula"),
           "texto": call.get("texto"), "onde": call.get("onde"), "nivel": call.get("nivel"),
           "nome": call.get("nome"), "titulo": call.get("titulo"), "topicos": call.get("topicos")}
    r = _office_exec(uid, host, cmd)
    if isinstance(r, dict):
        if r.get("erro"):
            return f"(office/{host}: {r['erro']})"
        return f"[{host}] " + json.dumps(r, ensure_ascii=False)[:2500]
    return str(r)[:1500]


def _browser_conectado(uid):
    ch = _EXT_CH.get(uid)
    return bool(ch and (time.time() - ch["last_hello"] < 90))


def _desktop_conectado(uid):
    ch = _EXT_CH.get(uid)
    return bool(ch and (time.time() - ch.get("desktop_hello", 0) < 90))


def _browser_exec(uid, cmd, timeout=45):
    ch = _ext_channel(uid)
    cid = uuid.uuid4().hex[:10]
    ev = threading.Event(); ch["ev"][cid] = ev
    ch["q"].put(dict(cmd, id=cid))
    if not ev.wait(timeout):
        ch["ev"].pop(cid, None)
        return {"erro": "sem resposta do navegador (a extensão está conectada e ativa?)"}
    res = ch["res"].pop(cid, None); ch["ev"].pop(cid, None)
    return (res or {}) if isinstance(res, dict) else {"erro": "resposta vazia"}


def _browser_exec_atual(call):
    """Usado pelo loop do agente: opera o navegador do usuário logado e resume o resultado p/ o raciocínio."""
    u = _usuario_atual()
    if not u:
        return "(sem usuário na sessão — navegador indisponível)"
    uid = u.get("id")
    if not _browser_conectado(uid):
        # navegador fechado/sem extensão ativa: se o Cerne Desktop estiver disponível, pede p/ ABRIR o navegador
        if _desktop_conectado(uid):
            _ext_channel(uid)["desktop_q"].put({"acao": "abrir_navegador", "url": call.get("url") or ""})
            for _ in range(24):                            # espera a extensão conectar após o desktop abrir o navegador
                if _browser_conectado(uid):
                    break
                time.sleep(1)
        if not _browser_conectado(uid):
            return ("(o navegador do usuário NÃO está conectado. Instale a extensão do Cerne no Chrome/Edge e pareie em "
                    "Agentes → Navegador do usuário; com o Cerne Desktop aberto, o navegador é iniciado automaticamente. "
                    "Enquanto isso, é possível usar a ferramenta web/código.)")
    cmd = {"acao": (call.get("acao") or "ler"), "url": call.get("url"), "seletor": call.get("seletor"),
           "valor": call.get("valor"), "termo": call.get("termo"), "rotulo": "Cerne (agente) operando este navegador"}
    r = _browser_exec(uid, cmd)
    if isinstance(r, dict):
        if r.get("erro"):
            return f"(navegador: {r['erro']})"
        if "texto" in r:
            return f"[{r.get('titulo', '')}] {r.get('url', '')}\n{(r.get('texto') or '')[:2500]}"
        return json.dumps(r, ensure_ascii=False)[:1500]
    return str(r)[:1500]


@app.post("/ext/pair")
def ext_pair():
    """Gera (ou reaproveita) o código de pareamento do navegador para o usuário logado."""
    u = _usuario_atual()
    if not u:
        raise HTTPException(status_code=401, detail="faça login")
    toks = _ext_tokens()
    tok = next((t for t, m in toks.items() if m.get("user_id") == u.get("id")), None)
    if not tok:
        tok = uuid.uuid4().hex + uuid.uuid4().hex[:8]
        toks[tok] = {"user_id": u.get("id"), "nome": u.get("nome"), "org": _tenant(), "criado": time.strftime("%Y-%m-%dT%H:%M:%S")}
        _appstate_save(APPSTATE)
        _event("navegador pareado", f"código gerado para {u.get('nome')}", actor=_actor())
    return {"token": tok, "conectado": _browser_conectado(u.get("id"))}


@app.get("/ext/status")
def ext_status():
    u = _usuario_atual()
    if not u:
        raise HTTPException(status_code=401, detail="faça login")
    toks = _ext_tokens()
    tok = next((t for t, m in toks.items() if m.get("user_id") == u.get("id")), None)
    ch = _EXT_CH.get(u.get("id")) or {}
    return {"pareado": bool(tok), "token": tok, "conectado": _browser_conectado(u.get("id")),
            "desktop": _desktop_conectado(u.get("id")), "info": ch.get("info") or {},
            "office": {h: _office_conectado(u.get("id"), h) for h in _OFFICE_HOSTS}}


@app.post("/ext/unpair")
def ext_unpair():
    u = _usuario_atual()
    if not u:
        raise HTTPException(status_code=401, detail="faça login")
    toks = _ext_tokens()
    for t in [t for t, m in toks.items() if m.get("user_id") == u.get("id")]:
        toks.pop(t, None)
    _appstate_save(APPSTATE)
    _EXT_CH.pop(u.get("id"), None)
    return {"ok": True}


async def _ext_body(request):
    try:
        return await request.json()
    except Exception:
        return {}


@app.post("/ext/hello")
async def ext_hello(request: Request):
    tok = request.headers.get("x-ext-token", "")
    m = _ext_tokens().get(tok)
    if not m:
        raise HTTPException(status_code=401, detail="código de pareamento inválido")
    body = await _ext_body(request)
    ch = _ext_channel(m["user_id"]); ch["last_hello"] = time.time()
    ch["info"] = {"navegador": body.get("navegador"), "url": body.get("url")}
    return {"ok": True, "usuario": m.get("nome")}


@app.post("/ext/poll")
async def ext_poll(request: Request):
    tok = request.headers.get("x-ext-token", "")
    m = _ext_tokens().get(tok)
    if not m:
        raise HTTPException(status_code=401, detail="código de pareamento inválido")
    ch = _ext_channel(m["user_id"]); ch["last_hello"] = time.time()
    try:
        cmd = await run_in_threadpool(ch["q"].get, True, 20)     # long-poll ~20s sem travar o event loop
    except queue.Empty:
        return {}
    return {"comando": cmd}


@app.post("/ext/result")
async def ext_result(request: Request):
    tok = request.headers.get("x-ext-token", "")
    m = _ext_tokens().get(tok)
    if not m:
        raise HTTPException(status_code=401, detail="código de pareamento inválido")
    body = await _ext_body(request)
    cid = body.get("id"); ch = _ext_channel(m["user_id"])
    if cid:
        ch["res"][cid] = body.get("resultado") or {}
        ev = ch["ev"].get(cid)
        if ev:
            ev.set()
    return {"ok": True}


# ---- Canal do Cerne DESKTOP: recebe pedidos p/ ABRIR o navegador quando ele está fechado (extensão inativa) ----
@app.post("/desktop/hello")
async def desktop_hello(request: Request):
    tok = request.headers.get("x-ext-token", "")
    m = _ext_tokens().get(tok)
    if not m:
        raise HTTPException(status_code=401, detail="código de pareamento inválido")
    _ext_channel(m["user_id"])["desktop_hello"] = time.time()
    return {"ok": True, "usuario": m.get("nome")}


@app.post("/desktop/poll")
async def desktop_poll(request: Request):
    tok = request.headers.get("x-ext-token", "")
    m = _ext_tokens().get(tok)
    if not m:
        raise HTTPException(status_code=401, detail="código de pareamento inválido")
    ch = _ext_channel(m["user_id"]); ch["desktop_hello"] = time.time()
    try:
        acao = await run_in_threadpool(ch["desktop_q"].get, True, 20)
    except queue.Empty:
        return {}
    return {"acao": acao}


