@app.get("/download/office-installer")
def download_office_installer():
    return Response(content=_OFFICE_INSTALLER_CMD, media_type="application/octet-stream",
                    headers={"Content-Disposition": 'attachment; filename="Instalar-Cerne-Office.cmd"'})


def _sub_agente(papel, tarefa):
    """Delegação: roda um sub-agente especialista LOCAL (soberano, 1 nível, sem novas delegações)."""
    persona = (f"Você é um sub-agente especialista em: {papel or 'geral'}. "
               "Execute a subtarefa de forma completa e direta, em português.")
    try:
        raw, _t, _c, _f, _ok, _ctx = _agent_run([], tarefa or "", model="chat", colls=[], system=persona, clarificar=False)
        return _strip_think(raw or "")[:4000] or "(sub-agente sem saída)"
    except Exception as e:
        return f"(sub-agente falhou: {str(e)[:120]})"


def _agente_loop_gen(task, tools, colls, model, workdir, hint=""):
    """Loop agêntico SOBERANO como GERADOR: decide e EXECUTA ferramentas de verdade
    (acervo/web/planilha/documento/apresentacao/codigo/arquivo/navegador/sub_agente). Yield ('step', txt) a cada
    ação p/ streaming; termina com ('result', {evid, fontes, usadas, arquivos}). Fecha o gap vs Codex/Cowork."""
    disp = []
    if "acervo" in tools and colls:
        disp.append('acervo — {"ferramenta":"acervo","consulta":"..."}')
    if "web" in tools and _org().get("busca_web"):
        disp.append('web — {"ferramenta":"web","consulta":"..."}')
    code_on = "codigo" in tools and _AGENT_CODE_EXEC
    if code_on:
        disp.append('planilha (GERA um .xlsx REAL) — {"ferramenta":"planilha","nome":"vendas.xlsx","abas":[{"nome":"Vendas","colunas":["Produto","Qtd","Preço"],"linhas":[["Cadeira",12,150]],"totais":{"Qtd":"soma","Preço":"soma"}}]}')
        disp.append('documento (GERA um .docx REAL) — {"ferramenta":"documento","nome":"relatorio.docx","titulo":"Título","secoes":[{"titulo":"Seção","paragrafos":["texto..."],"tabela":{"colunas":["A","B"],"linhas":[[1,2]]}}]}')
        disp.append('apresentacao (GERA um .pptx REAL) — {"ferramenta":"apresentacao","nome":"deck.pptx","titulo":"Título","subtitulo":"...","slides":[{"titulo":"Slide","topicos":["ponto 1","ponto 2"]}]}')
        disp.append('codigo (Python/bash avançado no workspace isolado, p/ cálculos/análises) — {"ferramenta":"codigo","linguagem":"python","codigo":"..."}')
        disp.append('arquivo — {"ferramenta":"arquivo","acao":"escrever|ler","nome":"x.txt","conteudo":"..."}')
    if "navegador" in tools:
        disp.append('navegador (opera o navegador do usuário: abrir/ler/clicar/preencher/baixar) — {"ferramenta":"navegador","acao":"abrir|ler|clicar|preencher|baixar|links","url":"...","seletor":"...","valor":"..."}')
    if "office" in tools:
        disp.append('office (opera o Excel/Word/PPT ABERTO ao vivo) — {"ferramenta":"office","app":"excel|word|ppt","acao":"...","celula":"B2","valor":"...","intervalo":"A1:C3","valores":[[...]],"formula":"=SUM(...)","texto":"...","titulo":"...","topicos":["..."]}. Ações Excel: ler_selecao/escrever_celula/escrever_intervalo/ler_intervalo/formula/adicionar_linha/nova_aba/ler_planilha; Word: ler_documento/ler_selecao/inserir_texto/substituir_selecao/adicionar_paragrafo/adicionar_titulo; PPT: ler_slides/adicionar_slide/inserir_texto.')
    if "nuvem" in tools:
        disp.append('nuvem (envia um arquivo JÁ GERADO no workspace para o OneDrive/SharePoint) — {"ferramenta":"nuvem","arquivo":"relatorio.xlsx","pasta":"Relatorios"}')
    disp.append('sub_agente (SÓ p/ raciocínio/decomposição — nunca p/ gerar arquivos) — {"ferramenta":"sub_agente","papel":"...","tarefa":"..."}')
    regras = ""
    if code_on:
        regras = ('\nREGRA: se o pedido é ENTREGAR uma planilha, documento ou apresentação, use planilha/documento/'
                  'apresentacao com os DADOS reais preenchidos — NÃO apenas descreva, GERE o arquivo. Nunca use '
                  'sub_agente para produzir arquivos.')
    ctx = (f"\nContexto do agente: {hint[:500]}" if hint else "")
    sysp = ("Você é um agente que USA ferramentas antes de responder. Para chamar uma, responda SOMENTE com uma "
            "linha JSON (sem texto em volta). Ferramentas:\n- " + "\n- ".join(disp) + regras + ctx +
            '\nQuando já tiver o necessário, responda {"ferramenta":"pronto"}. No máximo 5 chamadas, sem repetir.')
    msgs = [{"role": "user", "content": task}]
    evid, fontes, usadas, arquivos = [], [], [], []
    decidiu = False

    # --- Fast-path DETERMINÍSTICO: se o pedido é gerar um arquivo Office e o agente tem 'codigo', gera de fato ---
    kinds = _office_intent(task) or (_office_intent(hint) if _GERAR_VERBO.search(task or "") else [])
    # Caminho DETERMINÍSTICO URL→Excel: se o pedido traz uma URL/API e quer planilha/tabela/dados, o backend baixa
    # e monta o .xlsx com os DADOS REAIS (não depende do modelo escrever código nem inventar dados).
    _url_m = re.search(r"https?://[^\s)>\"'\]]+", task or "")
    if code_on and workdir and _url_m and (("planilha" in kinds) or re.search(r"planilha|excel|tabela|\bdados\b|consolid|xlsx", task or "", re.I)):
        url = _url_m.group(0).rstrip(".,);")
        yield ("step", "🌐 baixando dados de " + url[:56])
        yield ("step", "📊 montando a planilha com os dados reais")
        saida = _sandbox_exec(_office_url_code(url, "dados.xlsx"), "python", workdir)
        if "OK arquivo:" in (saida or ""):
            arquivos.append("dados.xlsx"); usadas.append("planilha")
            evid.append("[planilha] gerada a partir de " + url + " — " + (saida or "")[:200])
            yield ("step", "✅ dados.xlsx pronto")
            yield ("result", {"evid": "\n\n".join(evid), "fontes": fontes, "usadas": usadas, "arquivos": arquivos}); return
        evid.append("[dados] não consegui montar a planilha da URL: " + (saida or "")[:200])
    if code_on and workdir and kinds:
        contexto = ""
        if "acervo" in tools and colls:                    # aterra a geração no acervo, se houver
            yield ("step", "🔍 consultando o acervo")
            hits = _search_rich(task, colls, model, k=5)
            if hits:
                contexto = "\n".join(f"[{h.payload.get('source', '?')}] {(h.payload.get('text', '') or '')[:300]}" for h in hits)
                fontes += [{"source": h.payload.get("source", "?"), "trecho": (h.payload.get("text", "") or "")[:300],
                            "score": round(float(getattr(h, "score", 0) or 0), 2)} for h in hits[:4]]
        elif "web" in tools and _org().get("busca_web"):
            yield ("step", "🌐 buscando na web")
            wt, wf = _web_search(task)
            if wt:
                contexto = wt[:2500]; fontes += wf or []
        emoji = {"planilha": "📊", "documento": "📄", "apresentacao": "📽️"}
        for kind in kinds[:2]:
            yield ("step", f"{emoji[kind]} gerando {kind}")
            spec = _office_spec(kind, task, contexto)
            if not spec:
                evid.append(f"[{kind}] não consegui estruturar os dados"); continue
            code, fnome = _office_code(kind, spec)
            saida = _sandbox_exec(code, "python", workdir) if code else ""
            if "OK arquivo:" in (saida or ""):
                arquivos.append(fnome); usadas.append(kind)
                evid.append(f"[{kind}] arquivo '{fnome}' gerado com sucesso a partir dos dados fornecidos.")
                yield ("step", f"✅ {fnome} pronto")
            else:
                evid.append(f"[{kind}] falha ao gerar: {(saida or '')[:200]}")
        if usadas:                                          # entregou arquivo(s) → encerra sem depender do loop livre
            yield ("result", {"evid": "\n\n".join(evid), "fontes": fontes, "usadas": usadas, "arquivos": arquivos})
            return

    for _ in range(5):
        try:
            raw = _strip_think(chat_model(model, [{"role": "system", "content": sysp}] + msgs, max_tokens=1400) or "")
        except Exception:
            break
        call = _parse_tool_call(raw)
        if call:
            decidiu = True
        if not call or call.get("ferramenta") == "pronto":
            break
        nome = call.get("ferramenta")
        res = "(ferramenta indisponível)"
        if nome == "acervo" and colls:
            q = (call.get("consulta") or task)[:300]
            yield ("step", f"🔍 buscando no acervo: {q[:60]}")
            hits = _search_rich(q, colls, model, k=5)
            res = "\n".join(f"[{h.payload.get('source', '?')}] {(h.payload.get('text', '') or '')[:350]}" for h in hits) or "(nada no acervo)"
            fontes += [{"source": h.payload.get("source", "?"), "trecho": (h.payload.get("text", "") or "")[:300],
                        "score": round(float(getattr(h, "score", 0) or 0), 2)} for h in hits[:4]]
            usadas.append("acervo")
        elif nome == "web" and _org().get("busca_web"):
            q = (call.get("consulta") or task)[:300]
            yield ("step", f"🌐 buscando na web: {q[:60]}")
            wt, wf = _web_search(q); res = wt or "(sem resultados na web)"; fontes += wf or []; usadas.append("web")
        elif nome in ("planilha", "documento", "apresentacao") and workdir and _AGENT_CODE_EXEC:
            emoji = {"planilha": "📊", "documento": "📄", "apresentacao": "📽️"}[nome]
            yield ("step", f"{emoji} gerando {nome}")
            code, fnome = _office_code(nome, call)
            if code:
                saida = _sandbox_exec(code, "python", workdir)
                if "OK arquivo:" in (saida or ""):
                    arquivos.append(fnome); usadas.append(nome)
                    res = f"(arquivo '{fnome}' gerado com sucesso — disponível para download)"
                    yield ("step", f"✅ {fnome} pronto")
                else:
                    res = f"(falha ao gerar {nome}: {(saida or '')[:300]})"
            else:
                res = f"(estrutura inválida para {nome})"
        elif nome == "navegador" and "navegador" in tools:
            acao = (call.get("acao") or "ler")
            yield ("step", f"🧭 navegador: {acao} {(call.get('url') or call.get('seletor') or '')[:50]}")
            res = _browser_exec_atual(call); usadas.append("navegador")
        elif nome == "office" and "office" in tools:
            app_ = (call.get("app") or ""); acao = (call.get("acao") or "ler")
            emoji = {"excel": "📊", "word": "📄", "ppt": "📽️"}.get(app_, "🗂️")
            yield ("step", f"{emoji} office/{app_ or '?'}: {acao}")
            res = _office_exec_atual(call); usadas.append("office")
        elif nome == "nuvem" and "nuvem" in tools:
            yield ("step", f"☁️ enviando p/ nuvem: {os.path.basename(call.get('arquivo') or call.get('nome') or '')}")
            res = _nuvem_upload_atual(call, workdir); usadas.append("nuvem")
        elif nome == "codigo" and workdir and _AGENT_CODE_EXEC:
            lang = call.get("linguagem", "python")
            yield ("step", f"💻 executando código ({lang})")
            res = _sandbox_exec(call.get("codigo", ""), lang, workdir); usadas.append("codigo")
        elif nome == "arquivo" and workdir:
            acao = call.get("acao", "ler"); nomearq = os.path.basename(call.get("nome", "arquivo.txt") or "arquivo.txt")
            if acao == "escrever":
                yield ("step", f"📝 escreveu arquivo {nomearq}")
                res = _sb_write(workdir, nomearq, call.get("conteudo", "")); arquivos.append(nomearq)
            else:
                yield ("step", f"📄 leu arquivo {nomearq}")
                res = _sb_read(workdir, nomearq)
        elif nome == "sub_agente":
            papel = call.get("papel", "geral")
            yield ("step", f"🤝 delegando a sub-agente: {papel[:50]}")
            res = _sub_agente(papel, call.get("tarefa") or task); usadas.append("sub_agente")
        evid.append(f"[{nome}]\n{res[:1500]}")
        msgs.append({"role": "assistant", "content": raw})
        msgs.append({"role": "user", "content": f"Resultado:\n{res[:1500]}\n\nUse outra ferramenta ou responda {{\"ferramenta\":\"pronto\"}}."})
    if not usadas and not decidiu:                         # modelo local fraco não decidiu -> executa 1x direto
        if "web" in tools and _org().get("busca_web"):
            yield ("step", "🌐 buscando na web")
            wt, wf = _web_search(task)
            if wt:
                evid.append(f"[web]\n{wt[:1500]}"); fontes += wf or []; usadas.append("web")
        elif "acervo" in tools and colls:
            yield ("step", "🔍 buscando no acervo")
            hits = _search_rich(task, colls, model, k=5)
            if hits:
                res = "\n".join(f"[{h.payload.get('source', '?')}] {(h.payload.get('text', '') or '')[:350]}" for h in hits)
                evid.append(f"[acervo]\n{res[:1500]}")
                fontes += [{"source": h.payload.get("source", "?"), "trecho": (h.payload.get("text", "") or "")[:300],
                            "score": round(float(getattr(h, "score", 0) or 0), 2)} for h in hits[:4]]
                usadas.append("acervo")
    yield ("result", {"evid": "\n\n".join(evid), "fontes": fontes, "usadas": usadas, "arquivos": arquivos})


def _agente_evidencia(task, tools, colls, model="chat"):
    """Compat não-streaming: drena o loop e retorna (evidencia, fontes, usadas)."""
    res = {"evid": "", "fontes": [], "usadas": []}
    for kind, val in _agente_loop_gen(task, tools, colls, model, None):
        if kind == "result":
            res = val
    return res["evid"], res["fontes"], res["usadas"]


def _agente_answer(a, mensagem, persona, colls, evid_txt, modelo_cfg, permitidos, sess):
    """Gera a resposta final do agente (externa mascarada OU local soberana), embasada nas evidências
    das ferramentas. Retorna (ans, pii, fontes, soberano, rebaixado). Reusado por run e run-stream."""
    quer_externo = str(modelo_cfg).startswith("ext-")
    if quer_externo and modelo_cfg in permitidos:
        hits = _search_rich(mensagem, colls, "chat", k=6) if colls else []
        ctx = _compress("\n\n---\n\n".join(h.payload.get("text", "") for h in hits), mensagem, max_sent=12) if hits else ""
        if evid_txt:
            ctx = (ctx + "\n\n[EVIDÊNCIAS DAS FERRAMENTAS]\n" + evid_txt).strip()
        fontes = [{"source": h.payload.get("source", "?"), "trecho": (h.payload.get("text", "") or "")[:400],
                   "score": round(float(getattr(h, "score", 0) or 0), 2)} for h in hits[:4]]
        ans, pii = _agente_externo_mascarado(modelo_cfg, mensagem, ctx, persona)
        return ans, pii, fontes, False, False
    raw, _trace, clarify, fontes, _okr, _ctx = _agent_run(_session_context(sess), mensagem, model="chat",
                                                          colls=colls, system=persona, clarificar=False, extra=evid_txt)
    ans, _ = guard_output(clarify or raw)
    return ans, [], fontes, True, quer_externo


# ---- Métricas de execução dos agentes (para o painel Visão geral) ----
def _agente_metric(aid, nome, dur_ms, usadas, soberano, ok=True, origem="manual"):
    try:
        m = APPSTATE.setdefault("agent_metrics", {})
        g = m.setdefault("_global", {"execucoes": 0, "tempo_ms": 0, "erros": 0, "agendadas": 0})
        g["execucoes"] += 1; g["tempo_ms"] += int(dur_ms)
        if not ok:
            g["erros"] += 1
        if origem == "agendado":
            g["agendadas"] = g.get("agendadas", 0) + 1
        a = m.setdefault(aid, {"nome": nome, "execucoes": 0, "tempo_ms": 0, "ultima": "", "tools": {}, "soberano": 0, "hibrido": 0})
        a["nome"] = nome; a["execucoes"] += 1; a["tempo_ms"] += int(dur_ms); a["ultima"] = time.strftime("%Y-%m-%dT%H:%M:%S")
        k = "soberano" if soberano else "hibrido"; a[k] = a.get(k, 0) + 1
        for t in (usadas or []):
            a["tools"][t] = a["tools"].get(t, 0) + 1
        dia = m.setdefault("_por_dia", {}); d = time.strftime("%Y-%m-%d"); dia[d] = dia.get(d, 0) + 1
        if len(dia) > 45:
            for kk in sorted(dia)[:-45]:
                dia.pop(kk, None)
        _appstate_save(APPSTATE)
    except Exception:
        pass


@app.get("/agentes/metrics")
def agentes_metrics():
    m = APPSTATE.get("agent_metrics", {}); ags = _agentes()
    porag = []
    for a in ags:
        st = m.get(a["id"], {}); ex = st.get("execucoes", 0)
        porag.append({"id": a["id"], "nome": a["nome"], "execucoes": ex,
                      "tempo_medio_ms": int(st.get("tempo_ms", 0) / ex) if ex else 0,
                      "ultima": st.get("ultima", ""), "ativo": bool(a.get("ativo")),
                      "tools": st.get("tools", {}), "exemplo": bool(a.get("exemplo"))})
    g = m.get("_global", {"execucoes": 0, "tempo_ms": 0, "erros": 0, "agendadas": 0})
    tools_tot = {}
    for a in porag:
        for t, c in (a["tools"] or {}).items():
            tools_tot[t] = tools_tot.get(t, 0) + c
    scheds = APPSTATE.get("agent_schedules", [])
    return {"total_agentes": len(ags), "ativos": sum(1 for a in ags if a.get("ativo")),
            "execucoes_total": g.get("execucoes", 0), "erros": g.get("erros", 0), "agendadas": g.get("agendadas", 0),
            "tempo_medio_ms": int(g.get("tempo_ms", 0) / g["execucoes"]) if g.get("execucoes") else 0,
            "por_agente": sorted(porag, key=lambda x: -x["execucoes"]), "por_dia": m.get("_por_dia", {}),
            "por_ferramenta": tools_tot, "agendamentos": len(scheds),
            "agendamentos_ativos": sum(1 for s in scheds if s.get("ativo"))}


@app.post("/agentes/{aid}/run")
def agentes_run(aid: str, body: AgenteRunReq):
    _t0 = time.time()
    a = _agente_por_id(aid)
    if not a or not a.get("ativo"):
        raise HTTPException(status_code=404, detail="agente não encontrado ou inativo")
    u = _usuario_atual()                                   # RBAC: perfil do usuário >= perfil mínimo do agente
    if u and _PERFIL_RANK.get(u.get("perfil"), 1) < _PERFIL_RANK.get(a.get("perfil_minimo", "colaborador"), 1):
        raise HTTPException(status_code=403, detail="seu perfil não tem acesso a este agente")
    _quota_consumir(externa=str(a.get("modelo", "")).startswith("ext-"))
    ok, why = guard_input(body.mensagem)
    if not ok:
        return {"answer": f"⛔ Bloqueado pelo guardrail: {why}.", "bloqueado": True, "agente": a["nome"]}
    sid = body.session_id or uuid.uuid4().hex[:12]
    sess = _session(sid)
    colls = _org_colls_ok([a["colecao"]]) if a.get("colecao") else []
    # skill do catálogo = persona-base do agente (department copilot); persona custom refina por cima
    skill_txt, skill_nome = "", ""
    if a.get("skill_id"):
        _sk = next((s for s in _skills() if s.get("id") == a["skill_id"]), None)
        if _sk:
            skill_txt, skill_nome = (_sk.get("prompt") or ""), _sk.get("nome", "")
            if not colls and _sk.get("colecao"):
                colls = _org_colls_ok([_sk["colecao"]])
    base = a.get("persona") or f"Você é o agente '{a['nome']}'. {a.get('descricao','')}"
    persona = (skill_txt + ("\n\n" + base if base.strip() else "")) if skill_txt else base
    if a.get("ferramentas"):
        persona += "\n\nFerramentas declaradas: " + ", ".join(AGENTE_TOOLS.get(t, t) for t in a["ferramentas"]) + "."
    if a.get("mcp"):
        nomes = [(_conn_por_id(m) or {}).get("nome", m) for m in a["mcp"]]
        persona += "\n\nConectores disponíveis: " + ", ".join(nomes) + " — executados pelo runtime NanoClaw."
    modelo_cfg = a.get("modelo") or "agent"
    permitidos = _ext_permitidos(_org())
    ferramentas = a.get("ferramentas") or []
    # LOOP REAL DE FERRAMENTAS (soberano): o agente decide e EXECUTA acervo/web/código/arquivo/sub-agente.
    workdir = ("ag" + uuid.uuid4().hex[:12]) if ("codigo" in ferramentas and _AGENT_CODE_EXEC) else None
    steps, loop, artefatos = [], {"evid": "", "fontes": [], "usadas": [], "arquivos": []}, []
    try:
        for kind, val in _agente_loop_gen(body.mensagem, ferramentas, colls, "chat", workdir, hint=persona):
            if kind == "step":
                steps.append(val)
            else:
                loop = val
        ans, pii, fontes_ans, soberano, rebaixado = _agente_answer(a, body.mensagem, persona, colls,
                                                                   loop["evid"], modelo_cfg, permitidos, sess)
        artefatos = _agente_coletar_artefatos(workdir)     # copia os arquivos gerados p/ o store baixável (antes do reset)
    finally:
        if workdir:
            _sb_reset(workdir)
    fontes = (loop["fontes"] or []) + (fontes_ans or [])
    sess["msgs"] += [{"role": "user", "content": body.mensagem}, {"role": "assistant", "content": ans}]
    _compact(sess)
    _event("agente executado", f"{a['nome']} · {'soberano' if soberano else 'híbrido·'+modelo_cfg+' (PII mascarada)'}"
           + (f" · 🔧 {'+'.join(loop['usadas'])}" if loop["usadas"] else "") + f" · {body.mensagem[:40]}", actor=_actor())
    _agente_metric(aid, a["nome"], (time.time() - _t0) * 1000, loop["usadas"], soberano)
    return {"session_id": sid, "answer": ans, "agente": a["nome"], "fontes": fontes, "skill": skill_nome or None,
            "ferramentas_usadas": loop["usadas"], "arquivos": loop["arquivos"], "artefatos": artefatos, "etapas": steps,
            "soberano": soberano, "mascarado": not soberano, "provedor": (None if soberano else modelo_cfg),
            "pii_protegida": pii, "rebaixado_soberano": rebaixado}


@app.post("/agentes/{aid}/run-stream")
def agentes_run_stream(aid: str, body: AgenteRunReq):
    """Igual ao /run mas TRANSMITE as etapas ao vivo (tool-use, código, delegação) e depois a resposta.
    Protocolo: [[STEP]]... antes de [[ANSWER]]<resposta>[[META]]{json}."""
    a = _agente_por_id(aid)
    if not a or not a.get("ativo"):
        raise HTTPException(status_code=404, detail="agente não encontrado ou inativo")
    u = _usuario_atual()
    if u and _PERFIL_RANK.get(u.get("perfil"), 1) < _PERFIL_RANK.get(a.get("perfil_minimo", "colaborador"), 1):
        raise HTTPException(status_code=403, detail="seu perfil não tem acesso a este agente")
    _quota_consumir(externa=str(a.get("modelo", "")).startswith("ext-"))
    okg, why = guard_input(body.mensagem)
    sid = body.session_id or uuid.uuid4().hex[:12]
    org, usr = _ORG_CTX.get(), _USER_CTX.get()             # propaga identidade p/ a thread do gerador

    def gen():
        _t0 = time.time()
        _ORG_CTX.set(org); _USER_CTX.set(usr)              # sem token/reset: o starlette itera em threads distintas
        if True:
            if not okg:
                yield "[[ANSWER]]"; yield f"⛔ Bloqueado pelo guardrail: {why}."
                yield "[[META]]" + json.dumps({"session_id": sid, "bloqueado": True, "agente": a["nome"]})
                return
            sess = _session(sid)
            colls = _org_colls_ok([a["colecao"]]) if a.get("colecao") else []
            skill_txt, skill_nome = "", ""
            if a.get("skill_id"):
                _sk = next((s for s in _skills() if s.get("id") == a["skill_id"]), None)
                if _sk:
                    skill_txt, skill_nome = (_sk.get("prompt") or ""), _sk.get("nome", "")
                    if not colls and _sk.get("colecao"):
                        colls = _org_colls_ok([_sk["colecao"]])
            base = a.get("persona") or f"Você é o agente '{a['nome']}'. {a.get('descricao','')}"
            persona = (skill_txt + ("\n\n" + base if base.strip() else "")) if skill_txt else base
            if a.get("ferramentas"):
                persona += "\n\nFerramentas declaradas: " + ", ".join(AGENTE_TOOLS.get(t, t) for t in a["ferramentas"]) + "."
            modelo_cfg = a.get("modelo") or "agent"
            permitidos = _ext_permitidos(_org())
            ferramentas = a.get("ferramentas") or []
            yield "[[STEP]]interpretando o pedido"
            workdir = ("ag" + uuid.uuid4().hex[:12]) if ("codigo" in ferramentas and _AGENT_CODE_EXEC) else None
            loop, artefatos = {"evid": "", "fontes": [], "usadas": [], "arquivos": []}, []
            try:
                for kind, val in _agente_loop_gen(body.mensagem, ferramentas, colls, "chat", workdir, hint=persona):
                    if kind == "step":
                        yield "[[STEP]]" + val
                    else:
                        loop = val
                externo = str(modelo_cfg).startswith("ext-") and modelo_cfg in permitidos
                yield "[[STEP]]compondo a resposta " + (f"({modelo_cfg} · PII mascarada)" if externo else "(local soberano)")
                ans, pii, fontes_ans, soberano, rebaixado = _agente_answer(a, body.mensagem, persona, colls,
                                                                           loop["evid"], modelo_cfg, permitidos, sess)
                artefatos = _agente_coletar_artefatos(workdir)   # arquivos gerados → store baixável (antes do reset)
                if artefatos:
                    yield "[[STEP]]📎 " + str(len(artefatos)) + " arquivo(s) pronto(s) para download"
            finally:
                if workdir:
                    _sb_reset(workdir)
            fontes = (loop["fontes"] or []) + (fontes_ans or [])
            sess["msgs"] += [{"role": "user", "content": body.mensagem}, {"role": "assistant", "content": ans}]
            _compact(sess)
            _event("agente executado", f"{a['nome']} · {'soberano' if soberano else 'híbrido·'+modelo_cfg}"
                   + (f" · 🔧 {'+'.join(loop['usadas'])}" if loop["usadas"] else "") + f" · {body.mensagem[:40]}", actor=_actor())
            _agente_metric(aid, a["nome"], (time.time() - _t0) * 1000, loop["usadas"], soberano)
            yield "[[ANSWER]]"
            yield ans
            yield "[[META]]" + json.dumps({"session_id": sid, "agente": a["nome"], "fontes": fontes,
                "skill": skill_nome or None, "ferramentas_usadas": loop["usadas"], "arquivos": loop["arquivos"],
                "artefatos": artefatos, "soberano": soberano, "mascarado": not soberano,
                "provedor": (None if soberano else modelo_cfg), "pii_protegida": pii, "rebaixado_soberano": rebaixado})

    return StreamingResponse(gen(), media_type="text/plain; charset=utf-8")


# ================= AGENDAMENTO de agentes (gatilhos: horário / pasta / e-mail) =================
# Um agendamento amarra um AGENTE + uma INSTRUÇÃO fixa + vários GATILHOS. Um loop em 2º plano
# avalia os gatilhos e dispara o agente automaticamente (execução headless, sem sessão de usuário).
_SCHED_WATCH_BASE = os.getenv("AGENT_WATCH_DIR", "/data/agent_watch")


def _agent_schedules():
    return APPSTATE.setdefault("agent_schedules", [])


def _sched_por_id(sid):
    return next((s for s in _agent_schedules() if s.get("id") == sid), None)


def _agente_exec_headless(a, instrucao, origem="agendado"):
    """Executa um agente SEM sessão de usuário (disparo automático). Retorna (answer, artefatos, usadas, soberano)."""
    t0 = time.time()
    colls = _org_colls_ok([a["colecao"]]) if a.get("colecao") else []
    skill_txt = ""
    if a.get("skill_id"):
        _sk = next((s for s in _skills() if s.get("id") == a["skill_id"]), None)
        if _sk:
            skill_txt = _sk.get("prompt") or ""
            if not colls and _sk.get("colecao"):
                colls = _org_colls_ok([_sk["colecao"]])
    base = a.get("persona") or f"Você é o agente '{a['nome']}'. {a.get('descricao','')}"
    persona = (skill_txt + ("\n\n" + base if base.strip() else "")) if skill_txt else base
    modelo_cfg = a.get("modelo") or "agent"
    permitidos = _ext_permitidos(_org())
    ferramentas = a.get("ferramentas") or []
    workdir = ("ag" + uuid.uuid4().hex[:12]) if ("codigo" in ferramentas and _AGENT_CODE_EXEC) else None
    sess = _session("sched-" + a["id"])
    loop = {"evid": "", "fontes": [], "usadas": [], "arquivos": []}; artefatos = []
    try:
        for kind, val in _agente_loop_gen(instrucao, ferramentas, colls, "chat", workdir, hint=persona):
            if kind == "result":
                loop = val
        ans, pii, fontes_ans, soberano, rebaixado = _agente_answer(a, instrucao, persona, colls,
                                                                   loop["evid"], modelo_cfg, permitidos, sess)
        artefatos = _agente_coletar_artefatos(workdir)
    finally:
        if workdir:
            _sb_reset(workdir)
    _agente_metric(a["id"], a["nome"], (time.time() - t0) * 1000, loop["usadas"], soberano, origem=origem)
    return ans, artefatos, loop["usadas"], soberano


def _sched_registrar_run(s, gatilho, ok, resumo, artefatos):
    runs = s.setdefault("runs", [])
    runs.insert(0, {"ts": time.strftime("%Y-%m-%dT%H:%M:%S"), "gatilho": gatilho, "ok": bool(ok),
                    "resumo": (resumo or "")[:400],
                    "artefatos": [{"nome": x.get("nome"), "url": x.get("url")} for x in (artefatos or [])]})
    del runs[15:]
    s["ultima_exec"] = time.strftime("%Y-%m-%dT%H:%M:%S"); s["ultima_status"] = "ok" if ok else "erro"


def _sched_disparar(s, gatilho, instrucao_extra=""):
    a = _agente_por_id(s.get("agente_id"))
    if not a:
        _sched_registrar_run(s, gatilho, False, "agente não encontrado ou removido", []); _appstate_save(APPSTATE); return
    instr = (s.get("instrucao") or "").strip()
    if instrucao_extra:
        instr = (instr + "\n\n" + instrucao_extra).strip() if instr else instrucao_extra
    try:
        _ORG_CTX.set(s.get("org") or DEFAULT_ORG)
        ans, arts, usadas, sob = _agente_exec_headless(a, instr or "Execute a tarefa configurada.")
        _sched_registrar_run(s, gatilho, True, ans, arts)
        _event("agente agendado", f"{a['nome']} · {gatilho} · {'+'.join(usadas) or 'sem ferramentas'}"
               + (f" · {len(arts)} arquivo(s)" if arts else ""))
    except Exception as e:
        _sched_registrar_run(s, gatilho, False, str(e)[:300], [])
        _event("agente agendado (erro)", f"{a.get('nome','?')} · {gatilho} · {str(e)[:80]}")
    _appstate_save(APPSTATE)


def _email_body(msg):
    try:
        if msg.is_multipart():
            for p in msg.walk():
                if p.get_content_type() == "text/plain":
                    return (p.get_payload(decode=True) or b"").decode(p.get_content_charset() or "utf-8", "ignore")
            return ""
        return (msg.get_payload(decode=True) or b"").decode(msg.get_content_charset() or "utf-8", "ignore")
    except Exception:
        return ""


def _sched_check_pasta(s, tr):
    d = os.path.join(_SCHED_WATCH_BASE, s["id"])
    os.makedirs(d, exist_ok=True)
    atuais = [f for f in sorted(os.listdir(d)) if os.path.isfile(os.path.join(d, f)) and not f.startswith(".")]
    if not tr.get("_inic"):                                # 1ª varredura: fotografa o que já existe (não dispara)
        tr["_vistos"] = atuais; tr["_inic"] = True; _appstate_save(APPSTATE); return
    vistos = set(tr.get("_vistos") or [])
    novos = [f for f in atuais if f not in vistos]
    for f in novos:
        try:
            raw = open(os.path.join(d, f), "rb").read()
            txt = extract_text(f, raw)[:6000]
        except Exception:
            txt = "(não consegui ler o conteúdo)"
        _sched_disparar(s, "arquivo: " + f, f"Um arquivo novo chegou na pasta monitorada: {f}\n\nConteúdo:\n{txt}")
    tr["_vistos"] = atuais
    if not novos:
        _appstate_save(APPSTATE)


def _sched_check_email(s, tr):
    inst = _conn_por_id(tr.get("conector_id"))
    if not inst:
        return
    env = {k: _dec(v) for k, v in (inst.get("env") or {}).items()}
    host = env.get("IMAP_HOST"); user = env.get("IMAP_USER"); pw = env.get("IMAP_PASSWORD")
    port = int(env.get("IMAP_PORT") or 993)
    if not (host and user and pw):
        return
    import imaplib
    import email as _email
    M = None
    try:
        M = imaplib.IMAP4_SSL(host, port, timeout=15)
        M.login(user, pw); M.select(tr.get("pasta") or "INBOX", readonly=True)
        typ, data = M.uid("search", None, "ALL")
        uids = data[0].split() if (data and data[0]) else []
        last = int(tr.get("_last_uid") or 0)
        if not tr.get("_inic_email"):
            tr["_inic_email"] = True; tr["_last_uid"] = int(uids[-1]) if uids else 0; _appstate_save(APPSTATE); return
        novos = [u for u in uids if int(u) > last]
        for u in novos[:5]:
            typ, md = M.uid("fetch", u, "(RFC822)")
            if not md or not md[0]:
                continue
            msg = _email.message_from_bytes(md[0][1])
            frm = str(msg.get("From", "")); subj = str(msg.get("Subject", "")); body = _email_body(msg)
            if tr.get("de") and tr["de"].lower() not in frm.lower():
                continue
            if tr.get("assunto") and tr["assunto"].lower() not in subj.lower():
                continue
            if tr.get("corpo") and tr["corpo"].lower() not in body.lower():
                continue
            _sched_disparar(s, "e-mail: " + subj[:40], f"Um e-mail chegou.\nDe: {frm}\nAssunto: {subj}\n\n{body[:5000]}")
        if uids:
            tr["_last_uid"] = max([int(x) for x in uids] + [last]); _appstate_save(APPSTATE)
    finally:
        try:
            if M:
                M.logout()
        except Exception:
            pass


def _http_get(url, timeout=15):
    return httpx.get((url or "").strip(), timeout=timeout, follow_redirects=True,
                     headers={"User-Agent": "Mozilla/5.0 (CerneBot; +https://cerne.orqion-ia.com.br)"})


def _html_to_text(html):
    t = re.sub(r"(?is)<(script|style)[^>]*>.*?</\1>", " ", html or "")
    t = re.sub(r"(?s)<[^>]+>", " ", t)
    import html as _h
    return re.sub(r"\s+", " ", _h.unescape(t)).strip()


def _sched_check_web(s, tr):
    if time.time() - float(tr.get("_ultima_poll", 0) or 0) < max(300, int(tr.get("cada_min") or 30) * 60):
        return
    tr["_ultima_poll"] = time.time()
    try:
        txt = _html_to_text(_http_get(tr.get("url", "")).text)[:20000]
    except Exception:
        return
    h = hashlib.sha256(txt.encode("utf-8", "ignore")).hexdigest()
    if not tr.get("_hash"):
        tr["_hash"] = h; _appstate_save(APPSTATE); return
    if h != tr["_hash"]:
        tr["_hash"] = h
        _sched_disparar(s, "página mudou", f"A página monitorada mudou: {tr.get('url')}\n\nConteúdo atual (resumo):\n{txt[:5000]}")
    else:
        _appstate_save(APPSTATE)


def _sched_check_rss(s, tr):
    if time.time() - float(tr.get("_ultima_poll", 0) or 0) < max(300, int(tr.get("cada_min") or 15) * 60):
        return
    tr["_ultima_poll"] = time.time()
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(_http_get(tr.get("url", "")).text)
    except Exception:
        return
    itens = []
    for it in root.iter():
        if it.tag.split("}")[-1].lower() in ("item", "entry"):
            g = title = link = desc = ""
            for ch in it:
                ct = ch.tag.split("}")[-1].lower()
                if ct in ("guid", "id"):
                    g = (ch.text or "").strip()
                elif ct == "title":
                    title = (ch.text or "").strip()
                elif ct == "link":
                    link = (ch.get("href") or ch.text or "").strip()
                elif ct in ("description", "summary", "content"):
                    desc = (ch.text or "").strip()
            itens.append({"id": g or link or title, "title": title, "link": link, "desc": desc})
    vistos = set(tr.get("_vistos") or [])
    if not tr.get("_inic"):
        tr["_vistos"] = [i["id"] for i in itens][:60]; tr["_inic"] = True; _appstate_save(APPSTATE); return
    novos = [i for i in itens if i["id"] and i["id"] not in vistos]
    for i in novos[:5]:
        _sched_disparar(s, "RSS: " + (i["title"][:40] or "novo item"),
                        f"Novo item no feed:\nTítulo: {i['title']}\nLink: {i['link']}\n\n{_html_to_text(i['desc'])[:3000]}")
    tr["_vistos"] = ([i["id"] for i in itens] + list(vistos))[:90]; _appstate_save(APPSTATE)


def _ms_token(env):
    """Token app-only (client-credentials) do Microsoft Graph. Aceita nomes SHAREPOINT_* ou MS_*."""
    tid = env.get("SHAREPOINT_TENANT_ID") or env.get("MS_TENANT_ID")
    cid = env.get("SHAREPOINT_CLIENT_ID") or env.get("MS_CLIENT_ID")
    sec = env.get("SHAREPOINT_CLIENT_SECRET") or env.get("MS_CLIENT_SECRET")
    if not (tid and cid and sec):
        return None
    r = httpx.post(f"https://login.microsoftonline.com/{tid}/oauth2/v2.0/token", timeout=20,
                   data={"client_id": cid, "client_secret": sec, "scope": "https://graph.microsoft.com/.default",
                         "grant_type": "client_credentials"})
    return r.json().get("access_token")


def _graph_site_id(env, H):
    import urllib.parse as _up
    p = _up.urlparse(env.get("SHAREPOINT_SITE_URL", ""))
    if not p.netloc:
        return None
    return httpx.get(f"https://graph.microsoft.com/v1.0/sites/{p.netloc}:{p.path}", headers=H, timeout=20).json().get("id")


def _graph_drive_base(env, H):
    """Base do drive p/ upload: SharePoint (site) ou OneDrive (usuário)."""
    if env.get("SHAREPOINT_SITE_URL"):
        sid = _graph_site_id(env, H)
        return f"sites/{sid}/drive" if sid else None
    u = env.get("MS_DRIVE_USER") or env.get("ONEDRIVE_USER") or env.get("MS_USER")
    return f"users/{u}/drive" if u else None


def _graph_upload(env, pasta, nome, dados):
    tok = _ms_token(env)
    if not tok:
        return "(conector sem credenciais Microsoft — informe tenant/client id/secret)"
    H = {"Authorization": "Bearer " + tok}
    try:
        base = _graph_drive_base(env, H)
        if not base:
            return "(conector sem site SharePoint nem usuário OneDrive configurado)"
        path = "/".join([x for x in [(pasta or "").strip("/"), nome] if x])
        r = httpx.put(f"https://graph.microsoft.com/v1.0/{base}/root:/{path}:/content",
                      headers=dict(H, **{"Content-Type": "application/octet-stream"}), content=dados, timeout=60)
        if r.status_code in (200, 201):
            return "(enviado p/ nuvem: " + (r.json().get("webUrl") or nome) + ")"
        return f"(falha no upload {r.status_code}: {r.text[:150]})"
    except Exception as e:
        return f"(erro no upload: {str(e)[:150]})"


def _sched_check_sharepoint(s, tr):
    if time.time() - float(tr.get("_ultima_poll", 0) or 0) < 300:
        return
    tr["_ultima_poll"] = time.time()
    inst = _conn_por_id(tr.get("conector_id"))
    if not inst:
        return
    env = {k: _dec(v) for k, v in (inst.get("env") or {}).items()}
    alvo = tr.get("alvo") or "arquivos"
    try:
        tok = _ms_token(env)
        if not tok:
            return
        H = {"Authorization": "Bearer " + tok}
        sid = _graph_site_id(env, H)
        if not sid:
            return
        if alvo == "lista":                                # itens novos numa LISTA do SharePoint
            lid = tr.get("lista_id")
            if not lid and tr.get("lista_nome"):
                ls = httpx.get(f"https://graph.microsoft.com/v1.0/sites/{sid}/lists", headers=H, timeout=20).json().get("value", [])
                lid = next((x["id"] for x in ls if (x.get("displayName", "") or x.get("name", "")).lower() == tr["lista_nome"].lower()), None)
            if not lid:
                return
            itens = httpx.get(f"https://graph.microsoft.com/v1.0/sites/{sid}/lists/{lid}/items?expand=fields&$top=50",
                              headers=H, timeout=20).json().get("value", [])
            rotulo = "lista"
        else:                                              # arquivos novos na biblioteca de documentos
            itens = httpx.get(f"https://graph.microsoft.com/v1.0/sites/{sid}/drive/root/children?$top=50",
                              headers=H, timeout=20).json().get("value", [])
            rotulo = "arquivo"
    except Exception:
        return
    vistos = set(tr.get("_vistos") or [])
    if not tr.get("_inic"):
        tr["_vistos"] = [i.get("id") for i in itens][:80]; tr["_inic"] = True; _appstate_save(APPSTATE); return
    novos = [i for i in itens if i.get("id") and i.get("id") not in vistos]
    for i in novos[:5]:
        if alvo == "lista":
            f = i.get("fields", {}) or {}
            resumo = "; ".join(f"{k}: {v}" for k, v in list(f.items())[:12] if not k.startswith("@") and not k.startswith("_"))
            _sched_disparar(s, "SharePoint lista: " + str(f.get("Title", i.get("id")))[:40],
                            f"Novo item na lista do SharePoint:\n{resumo}")
        else:
            _sched_disparar(s, "SharePoint: " + (i.get("name", "")[:40]),
                            f"Novo arquivo no SharePoint: {i.get('name')}\nModificado: {i.get('lastModifiedDateTime')}\nLink: {i.get('webUrl')}")
    tr["_vistos"] = ([i.get("id") for i in itens] + list(vistos))[:120]; _appstate_save(APPSTATE)


def _sched_por_webhook(token):
    for s in _agent_schedules():
        for tr in (s.get("triggers") or []):
            if tr.get("tipo") == "webhook" and tr.get("token") == token:
                return s, tr
    return None, None


def _scheduler_tick():
    now = time.time(); hoje = time.strftime("%Y-%m-%d"); hhmm = time.strftime("%H:%M")
    for s in list(_agent_schedules()):
        if not s.get("ativo"):
            continue
        for tr in (s.get("triggers") or []):
            try:
                tipo = tr.get("tipo")
                if tipo == "horario":
                    if tr.get("modo") == "diario":
                        if (tr.get("hora") or "") == hhmm and tr.get("_dia") != hoje:
                            tr["_dia"] = hoje; _sched_disparar(s, "horário " + tr.get("hora", ""))
                    else:
                        cada = max(1, int(tr.get("cada_min") or 60))
                        if now - float(tr.get("_ultima", 0) or 0) >= cada * 60:
                            tr["_ultima"] = now; _sched_disparar(s, f"intervalo {cada}min")
                elif tipo == "pasta":
                    _sched_check_pasta(s, tr)
                elif tipo == "email":
                    if now - float(tr.get("_ultima_poll", 0) or 0) >= 60:
                        tr["_ultima_poll"] = now
                        _sched_check_email(s, tr)
                elif tipo == "sharepoint":
                    _sched_check_sharepoint(s, tr)
                elif tipo == "rss":
                    _sched_check_rss(s, tr)
                elif tipo == "web":
                    _sched_check_web(s, tr)
                # webhook: sem polling (disparado pelo endpoint /hooks/agente/{token})
            except Exception as e:
                print("[cerne] trigger:", str(e)[:120])
    try:
        _cen_scheduler_tick()                              # agendamento de cenários (Sala de Cenários)
    except Exception as e:
        print("[cerne] cen scheduler:", str(e)[:120])


def _scheduler_loop():
    time.sleep(15)
    while True:
        try:
            _scheduler_tick()
        except Exception as e:
            print("[cerne] scheduler:", str(e)[:150])
        time.sleep(20)


def _sched_pub(s):
    return {"id": s["id"], "agente_id": s.get("agente_id"), "agente": (_agente_por_id(s.get("agente_id")) or {}).get("nome", "?"),
            "nome": s.get("nome") or "", "instrucao": s.get("instrucao") or "", "ativo": bool(s.get("ativo")),
            "triggers": [{k: v for k, v in t.items() if not k.startswith("_")} for t in (s.get("triggers") or [])],
            "ultima_exec": s.get("ultima_exec"), "ultima_status": s.get("ultima_status"),
            "runs": (s.get("runs") or [])[:8], "watch_dir": os.path.join(_SCHED_WATCH_BASE, s["id"])}


class SchedReq(BaseModel):
    id: str | None = None
    agente_id: str
    nome: str = ""
    instrucao: str = ""
    triggers: list = []
    ativo: bool = True


def _sched_norm_triggers(trs):
    out = []
    for t in (trs or [])[:12]:
        tp = (t.get("tipo") or "").lower()
        if tp == "horario":
            if t.get("modo") == "diario":
                out.append({"tipo": "horario", "modo": "diario", "hora": (t.get("hora") or "08:00")[:5]})
            else:
                out.append({"tipo": "horario", "modo": "intervalo", "cada_min": max(1, min(int(t.get("cada_min") or 60), 20160))})
        elif tp == "pasta":
            out.append({"tipo": "pasta"})
        elif tp == "email":
            out.append({"tipo": "email", "conector_id": t.get("conector_id") or "", "pasta": t.get("pasta") or "INBOX",
                        "de": (t.get("de") or "").strip(), "assunto": (t.get("assunto") or "").strip(), "corpo": (t.get("corpo") or "").strip()})
        elif tp == "webhook":
            out.append({"tipo": "webhook", "token": t.get("token") or uuid.uuid4().hex})
        elif tp == "sharepoint":
            out.append({"tipo": "sharepoint", "conector_id": t.get("conector_id") or "",
                        "alvo": ("lista" if t.get("alvo") == "lista" else "arquivos"),
                        "lista_nome": (t.get("lista_nome") or "").strip()})
        elif tp == "rss":
            out.append({"tipo": "rss", "url": (t.get("url") or "").strip(), "cada_min": max(5, min(int(t.get("cada_min") or 15), 1440))})
        elif tp == "web":
            out.append({"tipo": "web", "url": (t.get("url") or "").strip(), "cada_min": max(5, min(int(t.get("cada_min") or 30), 1440))})
    return out


@app.get("/agentes/agendamentos")
def agendamentos_list(agente_id: str = ""):
    scheds = _agent_schedules()
    if agente_id:
        scheds = [s for s in scheds if s.get("agente_id") == agente_id]
    return {"agendamentos": [_sched_pub(s) for s in scheds]}


@app.post("/agentes/agendamentos")
def agendamentos_save(body: SchedReq):
    _assert_admin_sessao()
    if not _agente_por_id(body.agente_id):
        raise HTTPException(status_code=400, detail="agente inválido")
    atual = _sched_por_id(body.id) if body.id else None
    item = atual or {"id": "sch" + uuid.uuid4().hex[:10], "org": _tenant(), "runs": []}
    item.update({"agente_id": body.agente_id, "nome": (body.nome or "").strip(),
                 "instrucao": (body.instrucao or "").strip(), "ativo": bool(body.ativo)})
    novos = _sched_norm_triggers(body.triggers)
    # preserva o estado interno (_ultima, _vistos, _last_uid…) dos gatilhos que continuam iguais, por índice/tipo
    antigos = (atual or {}).get("triggers") or []
    for i, t in enumerate(novos):
        if i < len(antigos) and antigos[i].get("tipo") == t.get("tipo"):
            for k, v in antigos[i].items():
                if k.startswith("_"):
                    t[k] = v
    item["triggers"] = novos
    APPSTATE["agent_schedules"] = [x for x in _agent_schedules() if x.get("id") != item["id"]] + [item]
    _appstate_save(APPSTATE)
    _event("agendamento salvo", f"{_sched_pub(item)['agente']} · {len(novos)} gatilho(s)", actor=_actor())
    return _sched_pub(item)


@app.delete("/agentes/agendamentos/{sid}")
def agendamentos_del(sid: str):
    _assert_admin_sessao()
    APPSTATE["agent_schedules"] = [x for x in _agent_schedules() if x.get("id") != sid]
    _appstate_save(APPSTATE)
    return {"status": "removido", "id": sid}


@app.post("/agentes/agendamentos/{sid}/toggle")
def agendamentos_toggle(sid: str):
    _assert_admin_sessao()
    s = _sched_por_id(sid)
    if not s:
        raise HTTPException(status_code=404, detail="agendamento não encontrado")
    s["ativo"] = not s.get("ativo"); _appstate_save(APPSTATE)
    return {"id": sid, "ativo": s["ativo"]}


@app.post("/agentes/agendamentos/{sid}/rodar-agora")
def agendamentos_rodar(sid: str):
    _assert_admin_sessao()
    s = _sched_por_id(sid)
    if not s:
        raise HTTPException(status_code=404, detail="agendamento não encontrado")
    threading.Thread(target=lambda: _sched_disparar(s, "manual"), name="cerne-sched-manual", daemon=True).start()
    return {"ok": True, "id": sid}


@app.post("/agentes/agendamentos/{sid}/arquivo")
async def agendamentos_upload(sid: str, file: UploadFile = File(...)):
    _assert_admin_sessao()
    if not _sched_por_id(sid):
        raise HTTPException(status_code=404, detail="agendamento não encontrado")
    d = os.path.join(_SCHED_WATCH_BASE, sid)
    os.makedirs(d, exist_ok=True)
    nome = os.path.basename(file.filename or ("arquivo_" + uuid.uuid4().hex[:6]))
    open(os.path.join(d, nome), "wb").write(await file.read())
    return {"ok": True, "nome": nome}


@app.api_route("/hooks/agente/{token}", methods=["GET", "POST"])
async def hook_agente(token: str, request: Request):
    """Webhook público (por token): qualquer sistema externo dispara o agente. O corpo entra como contexto."""
    s, tr = _sched_por_webhook(token)
    if not s or not s.get("ativo"):
        raise HTTPException(status_code=404, detail="gatilho não encontrado ou inativo")
    if time.time() - float(tr.get("_ultima", 0) or 0) < 3:      # anti-flood simples
        return {"ok": True, "ignorado": "muito rápido"}
    tr["_ultima"] = time.time()
    body = ""
    try:
        body = (await request.body()).decode("utf-8", "ignore")[:6000]
    except Exception:
        pass
    extra = f"Evento recebido via webhook:\n{body}" if body.strip() else "Disparo via webhook (sem corpo)."
    threading.Thread(target=lambda: _sched_disparar(s, "webhook", extra), name="cerne-hook", daemon=True).start()
    return {"ok": True, "agendado": True, "agente": (_agente_por_id(s.get("agente_id")) or {}).get("nome")}


# ================= STUDIO DE MARCA (módulo tipo Pomelli): Brand DNA + campanha + criativos =================
_MARCA_FORMATOS = {
    "ig_post":    {"nome": "Instagram post", "w": 1080, "h": 1080},
    "ig_story":   {"nome": "Instagram story", "w": 1080, "h": 1920},
    "facebook":   {"nome": "Facebook", "w": 1200, "h": 630},
    "linkedin":   {"nome": "LinkedIn", "w": 1200, "h": 627},
    "x_twitter":  {"nome": "X / Twitter", "w": 1600, "h": 900},
    "youtube":    {"nome": "YouTube thumb", "w": 1280, "h": 720},
    "ads_medium": {"nome": "Google Ads (retângulo)", "w": 300, "h": 250},
}


def _marcas():
    return APPSTATE.setdefault("marcas", [])


def _marca_por_id(mid):
    return next((m for m in _marcas() if m.get("id") == mid), None)


def _dna_txt(x):
    """Achata qualquer valor de campo do DNA (que a LLM às vezes devolve como dict/lista) em texto legível."""
    if isinstance(x, str):
        return x
    if isinstance(x, dict):
        v = x.get("nome") or x.get("name") or x.get("titulo") or x.get("produto") or x.get("valor")
        return str(v) if v else "; ".join(f"{k}: {vv}" for k, vv in list(x.items())[:4])
    if isinstance(x, list):
        return ", ".join(_dna_txt(i) for i in x)
    return "" if x is None else str(x)


def _dna_lista(v):
    if isinstance(v, list):
        return [_dna_txt(i) for i in v][:12]
    if not v:
        return []
    return [s.strip() for s in re.split(r"[;,\n]", str(v)) if s.strip()][:12]


def _hex_norm(c):
    m = re.fullmatch(r"#?([0-9a-fA-F]{6}|[0-9a-fA-F]{3})", (c or "").strip())
    if not m:
        return None
    h = m.group(1).lower()
    if len(h) == 3:
        h = "".join(ch * 2 for ch in h)
    return "#" + h


def _marca_extrair_dna(url):
    """Crawl do site + extrai identidade de marca: paleta (do CSS), fontes, logo e tom/público/produtos (LLM)."""
    if not re.match(r"https?://", url or ""):
        url = "https://" + (url or "").strip()
    try:
        html = _http_get(url, timeout=20).text
    except Exception as e:
        return {"erro": f"não consegui acessar o site: {str(e)[:120]}"}
    import urllib.parse as _up
    css = " ".join(re.findall(r"(?is)<style[^>]*>(.*?)</style>", html))
    for href in re.findall(r'(?is)<link[^>]+rel=["\']?stylesheet["\']?[^>]*href=["\']([^"\']+)', html)[:2]:
        try:
            css += " " + _http_get(_up.urljoin(url, href), timeout=12).text[:80000]
        except Exception:
            pass
    blob = html + " " + css
    cores = {}
    for c in re.findall(r"#[0-9a-fA-F]{6}\b|#[0-9a-fA-F]{3}\b", blob):
        h = _hex_norm(c)
        if h:
            cores[h] = cores.get(h, 0) + 1

    def _sat(h):
        r_, g_, b_ = int(h[1:3], 16), int(h[3:5], 16), int(h[5:7], 16)
        return max(r_, g_, b_) - min(r_, g_, b_)
    freq = [h for h, _ in sorted(cores.items(), key=lambda x: -x[1])][:24]
    paleta = sorted(freq, key=lambda h: -_sat(h))[:6] or ["#6c8cff", "#111826"]
    fontes = []
    for f in re.findall(r"font-family\s*:\s*([^;{}]+)", css, re.I):
        for part in f.split(","):
            p = part.strip().strip("'\"")
            if p and p.lower() not in ("inherit", "initial", "sans-serif", "serif", "monospace", "system-ui") and len(p) < 40 and p not in fontes:
                fontes.append(p)
    fontes = fontes[:4]
    logo = ""
    m = re.search(r'(?is)<img[^>]+(?:class|id|alt|src)=["\'][^"\']*logo[^"\']*["\'][^>]*>', html)
    if m:
        s = re.search(r'src=["\']([^"\']+)', m.group(0))
        logo = _up.urljoin(url, s.group(1)) if s else ""
    if not logo:
        og = re.search(r'(?is)<meta[^>]+property=["\']og:image["\'][^>]+content=["\']([^"\']+)', html)
        if og:
            logo = _up.urljoin(url, og.group(1))
    imgs = []                                             # imagens de conteúdo do site (p/ fundo dos criativos)
    ogimg = re.search(r'(?is)<meta[^>]+property=["\']og:image["\'][^>]+content=["\']([^"\']+)', html)
    if ogimg:
        imgs.append(_up.urljoin(url, ogimg.group(1)))
    for sattr in re.findall(r'(?is)<img[^>]+src=["\']([^"\']+)', html):
        u = _up.urljoin(url, sattr)
        if re.search(r'\.(png|jpe?g|webp)(\?|$)', u, re.I) and not re.search(r'sprite|icon|logo|favicon|pixel|1x1|badge|avatar', u, re.I) and u not in imgs:
            imgs.append(u)
    for sattr in re.findall(r'url\(["\']?([^"\')]+\.(?:png|jpe?g|webp))', blob, re.I):
        u = _up.urljoin(url, sattr)
        if u not in imgs and not re.search(r'logo|icon|sprite|favicon', u, re.I):
            imgs.append(u)
    texto = _html_to_text(html)[:6000]
    prompt = ('Analise o site abaixo e responda SOMENTE com um JSON válido: {"nome_marca":"...","resumo":"1-2 frases",'
              '"tom_de_voz":"...","publico_alvo":"...","valores":["..."],"produtos":["..."]}. Em português.\n\nSITE:\n' + texto)
    dna = {"nome_marca": "", "resumo": "", "tom_de_voz": "", "publico_alvo": "", "valores": [], "produtos": []}
    try:
        j = _extract_json(_strip_think(chat_model("chat", [{"role": "user", "content": prompt}], max_tokens=800) or ""))
        if isinstance(j, dict):
            for k in dna:
                if j.get(k):
                    dna[k] = j[k]
    except Exception:
        pass

    def _s(v):
        if isinstance(v, str):
            return v
        if isinstance(v, list):
            return ", ".join(str(x) for x in v)
        return "" if v is None else str(v)

    def _l(v):
        if isinstance(v, list):
            return [_dna_txt(x) for x in v][:12]
        if not v:
            return []
        return [s.strip() for s in re.split(r"[;,\n]", str(v)) if s.strip()][:12]
    for k in ("nome_marca", "resumo", "tom_de_voz", "publico_alvo"):
        dna[k] = _s(dna.get(k))
    for k in ("valores", "produtos"):
        dna[k] = _l(dna.get(k))
    dna.update({"paleta": paleta, "fontes": fontes, "logo": logo, "site": url, "imagens": imgs[:10]})
    if not dna.get("nome_marca"):
        dna["nome_marca"] = _up.urlparse(url).netloc.replace("www.", "").split(".")[0].title()
    return dna


_MARCA_CRIATIVO_TPL = r'''
import base64, json, io, math
from PIL import Image, ImageDraw, ImageFont, ImageFilter
S = json.loads(base64.b64decode("__SPEC__").decode("utf-8"))
W, H = int(S["w"]), int(S["h"])
pal = S.get("paleta") or ["#6c8cff", "#111826"]
def hx(h):
    h = str(h).lstrip("#")
    if len(h) == 3: h = "".join(c*2 for c in h)
    try: return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))
    except Exception: return (108, 140, 255)
def lum(c): return 0.299*c[0] + 0.587*c[1] + 0.114*c[2]
def mix(a, b, t): return tuple(int(a[i]+(b[i]-a[i])*t) for i in range(3))
def clamp(c): return tuple(max(0, min(255, int(x))) for x in c)
cols = [hx(h) for h in pal[:5]] or [(108, 140, 255)]
acc = max(cols, key=lambda c: max(c)-min(c))          # acento = mais saturada
if max(acc)-min(acc) < 25: acc = (108, 140, 255)
base = min(cols, key=lum)                              # base = mais escura
if lum(base) > 95: base = clamp([x*0.45 for x in base])
variante = S.get("variante", "geo")
small = min(W, H) < 400
ref = (W*H) ** 0.5                                     # dimensão de referência: equilibra retrato/paisagem
FB = "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"
FR = "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"
def fnt(sz, b=True):
    try: return ImageFont.truetype(FB if b else FR, max(7, int(sz)))
    except Exception:
        try: return ImageFont.load_default(size=max(7, int(sz)))
        except Exception: return ImageFont.load_default()
img = Image.new("RGB", (W, H), base)
bg_ok = False
if S.get("bg_b64"):
    try:
        ph = Image.open(io.BytesIO(base64.b64decode(S["bg_b64"]))).convert("RGB")
        r = max(W/ph.width, H/ph.height)
        ph = ph.resize((max(1, int(ph.width*r)+1), max(1, int(ph.height*r)+1)))
        ox = (ph.width-W)//2; oy = (ph.height-H)//2
        img = ph.crop((ox, oy, ox+W, oy+H))
        bg_ok = True
    except Exception:
        bg_ok = False
if not bg_ok:
    c2 = mix(base, acc, 0.32) if variante == "geo" else mix(base, (255, 255, 255), 0.06)
    strip = Image.new("RGB", (1, H))
    for y in range(H): strip.putpixel((0, y), mix(base, c2, y/max(1, H-1)))
    img = strip.resize((W, H))
    if variante == "geo":
        ov = Image.new("RGBA", (W, H), (0, 0, 0, 0)); od = ImageDraw.Draw(ov)
        od.ellipse([W*0.52, -H*0.18, W*1.28, H*0.52], fill=acc+(70,))
        od.ellipse([-W*0.22, H*0.55, W*0.42, H*1.25], fill=mix(acc, (255, 255, 255), 0.25)+(48,))
        ov = ov.filter(ImageFilter.GaussianBlur(int(min(W, H)*0.02)))
        img = Image.alpha_composite(img.convert("RGBA"), ov).convert("RGB")
d = ImageDraw.Draw(img, "RGBA")
ink = (255, 255, 255)
m = max(14, int(min(W, H)*0.06))                       # margem proporcional ao MENOR lado (não estoura landscape)
maxw = W-2*m
# logo topo-esquerda (limitada por largura E altura; respeita transparência)
logo_bottom = 0
if S.get("logo_b64"):
    try:
        lg = Image.open(io.BytesIO(base64.b64decode(S["logo_b64"]))).convert("RGBA")
        lw = int(min(W*0.18, H*0.14)); lg.thumbnail((lw, lw))
        img.paste(lg, (m, m), lg); logo_bottom = m + lg.height
        d = ImageDraw.Draw(img, "RGBA")
    except Exception: pass
def wrap(txt, f, mw):
    out = []
    for ln in str(txt or "").split("\n"):
        cur = ""
        for w in ln.split():
            t = (cur+" "+w).strip()
            if d.textlength(t, font=f) <= mw: cur = t
            else:
                if cur: out.append(cur)
                cur = w
        if cur: out.append(cur)
    return out
def mlw(lines, f): return max([d.textlength(x, font=f) for x in lines], default=0)
def ellip(line, f, mw):
    if d.textlength(line, font=f) <= mw: return line
    s = str(line)
    while s and d.textlength(s+"…", font=f) > mw: s = s[:-1]
    return (s.rstrip()+"…") if s else line
titulo = S.get("titulo") or ""; legenda = S.get("legenda") or ""
cta = str(S.get("cta") or "").strip(); kicker = str(S.get("nome_marca") or "").upper()[:38]
top_safe = max(int(H*0.12), logo_bottom + int(H*0.02))
bottom_margin = max(int(H*0.06), 12)
avail_h = H - bottom_margin - top_safe
# auto-ajuste: encolhe a escala do type até caber na VERTICAL e na LARGURA (fim do texto cortado)
t0, l0, c0, k0 = ref*0.100, ref*0.039, ref*0.037, ref*0.027
scale = 1.0; fit = None
for _ in range(26):
    tf = fnt(t0*scale); lf = fnt(l0*scale, False); cf = fnt(c0*scale); kf = fnt(k0*scale)
    tl = wrap(titulo, tf, maxw); ll = wrap(legenda, lf, maxw)
    lim = 2 if small else 4
    if len(ll) > lim:
        ll = ll[:lim]
        if ll: ll[-1] = ll[-1].rstrip(".")+"…"
    lh_t = int(tf.size*1.14); lh_l = int(lf.size*1.34)
    th = len(tl)*lh_t; lhh = len(ll)*lh_l
    cta_h = int(cf.size*2.0) if cta else 0; kick_h = int(kf.size*1.7) if kicker else 0
    gap = int(H*0.02); cta_gap = int(H*0.028) if cta else 0
    block = kick_h + th + (gap+lhh if ll else 0) + (cta_gap+cta_h if cta else 0)
    widest = max(mlw(tl, tf), mlw(ll, lf))
    if (block <= avail_h and widest <= maxw+1) or scale <= 0.34:
        fit = (tf, lf, cf, kf, tl, ll, lh_t, lh_l, th, lhh, cta_h, kick_h, gap, cta_gap, block); break
    scale *= 0.93
tf, lf, cf, kf, tl, ll, lh_t, lh_l, th, lhh, cta_h, kick_h, gap, cta_gap, block = fit
while block > avail_h and len(tl) > 1:                  # copy gigante em canvas minúsculo: corta título por último
    tl = tl[:-1]; tl[-1] = tl[-1].rstrip(".")+"…"
    th = len(tl)*lh_t; block = kick_h + th + (gap+lhh if ll else 0) + (cta_gap+cta_h if cta else 0)
tl = [ellip(x, tf, maxw) for x in tl]; ll = [ellip(x, lf, maxw) for x in ll]  # blinda largura
y0 = max(top_safe, H - bottom_margin - block)
# contraste: gradiente escuro LOCALIZADO atrás do bloco (legibilidade garantida sobre qualquer foto)
if bg_ok:
    pad = int(H*0.05); band = Image.new("L", (1, H), 0)
    for yy in range(H):
        if yy >= y0-pad:
            t = min(1.0, (yy-(y0-pad))/max(1, pad)); band.putpixel((0, yy), int(180*t))
    img = Image.composite(Image.new("RGB", (W, H), clamp([x*0.30 for x in base])), img, band.resize((W, H)))
    d = ImageDraw.Draw(img, "RGBA")
y = y0
if kicker:
    bw = max(3, int(H*0.006)); d.rectangle([m, int(y+kf.size*0.34), m+int(max(W*0.05, 26)), int(y+kf.size*0.34+bw)], fill=acc)
    d.text((m+int(max(W*0.065, 34)), y), kicker, font=kf, fill=acc); y += kick_h
for ln in tl:
    d.text((m, y), ln, font=tf, fill=ink); y += lh_t
if ll:
    y += gap
    for ln in ll:
        d.text((m, y), ln, font=lf, fill=(233, 238, 248)); y += lh_l
if cta:
    y += cta_gap
    while cf.size > 9 and (d.textlength(cta, font=cf)+cf.size*1.7) > maxw:  # encolhe p/ a pílula caber
        cf = fnt(cf.size*0.92); cta_h = int(cf.size*2.0)
    tw = d.textlength(cta, font=cf); pw = int(min(tw+cf.size*1.7, maxw))
    d.rounded_rectangle([m, y, m+pw, y+cta_h], radius=cta_h//2, fill=acc)
    ci = (255, 255, 255) if lum(acc) < 150 else (16, 20, 30)
    d.text((m+(pw-tw)/2, y+(cta_h-cf.size)/2-2), cta, font=cf, fill=ci)
img.convert("RGB").save(S["nome"]); print("OK arquivo:", S["nome"], "| formato:", W, "x", H, "|", variante, "| foto:", bg_ok)
'''


def _marca_criativo_code(spec, nome):
    import base64 as _b64
    b64 = _b64.b64encode(json.dumps(dict(spec, nome=nome), ensure_ascii=False).encode("utf-8")).decode()
    return _MARCA_CRIATIVO_TPL.replace("__SPEC__", b64)


def _marca_imagem_hibrida(prompt, tamanho="1024x1024"):
    """Geração de imagem por IA — HÍBRIDO. Reusa a chave paga já configurada (OpenAI images / Gemini Imagen).
    Retorna (bytes_png, erro). Sem chave configurada, retorna (None, msg) e a composição segue sem imagem base."""
    cfg = APPSTATE.get("llm_pagas") or {}
    # 1) OpenAI Images (gpt-image-1) com a chave do ext-openai
    oa = cfg.get("ext-openai") or {}
    if oa.get("api_key"):
        try:
            import base64 as _b64
            r = httpx.post("https://api.openai.com/v1/images/generations", timeout=90,
                           headers={"Authorization": "Bearer " + _dec(oa["api_key"]), "Content-Type": "application/json"},
                           json={"model": "gpt-image-1", "prompt": prompt, "size": tamanho, "n": 1})
            if r.status_code == 200:
                b = r.json()["data"][0].get("b64_json")
                if b:
                    return _b64.b64decode(b), None
            err = f"OpenAI images {r.status_code}: {r.text[:140]}"
        except Exception as e:
            err = f"OpenAI images erro: {str(e)[:140]}"
    else:
        err = None
    # 2) Google Gemini (chave ext-gemini-pro / ext-gemini): modelo NATIVO de imagem via generateContent
    #    (o Imagen :predict foi bloqueado p/ chaves novas; os gemini-*-image são o caminho atual — exigem
    #    billing habilitado no projeto Google, senão retornam 429).
    gk = (cfg.get("ext-gemini-pro") or {}).get("api_key") or (cfg.get("ext-gemini") or {}).get("api_key")
    if gk:
        import base64 as _b64
        key = _dec(gk)
        base = "https://generativelanguage.googleapis.com/v1beta"
        for _mdl in (os.getenv("GEMINI_IMAGE_MODEL", "gemini-2.5-flash-image"),
                     "gemini-3-pro-image", "nano-banana-pro-preview"):
            try:
                r = httpx.post(f"{base}/models/{_mdl}:generateContent", params={"key": key}, timeout=120,
                               json={"contents": [{"parts": [{"text": prompt}]}]})
                if r.status_code == 200:
                    for c in r.json().get("candidates", []):
                        for p in (c.get("content") or {}).get("parts", []):
                            d = p.get("inlineData") or p.get("inline_data")
                            if d and d.get("data"):
                                return _b64.b64decode(d["data"]), None
                    err = "Gemini image: resposta sem imagem"
                else:
                    err = f"Gemini image {r.status_code}: {r.text[:110]}"
                    if r.status_code != 404:                # 404 = modelo indisponível → tenta o próximo
                        break
            except Exception as e:
                err = f"Gemini image erro: {str(e)[:110]}"
        # legado: Imagen :predict (chaves antigas que ainda têm acesso)
        if not (err and "429" in err):
            try:
                r = httpx.post(f"{base}/models/imagen-4.0-generate-001:predict", timeout=90, params={"key": key},
                               json={"instances": [{"prompt": prompt}], "parameters": {"sampleCount": 1}})
                if r.status_code == 200:
                    preds = r.json().get("predictions", [])
                    if preds and preds[0].get("bytesBase64Encoded"):
                        return _b64.b64decode(preds[0]["bytesBase64Encoded"]), None
            except Exception:
                pass
    return None, (err or "nenhum provedor de imagem configurado (configure OpenAI ou Gemini em Model Ops → LLMs pagas)")


def _marca_video_ia(prompt, dur=6, imagem_b64=None):
    """Geração de vídeo por IA — HÍBRIDO (Veo 3, via chave do Gemini). Retorna (bytes_mp4, erro).
    Sem chave, retorna (None, msg) e o /animate cai para o motion-graphics soberano (Ken Burns).
    Operação longa (~1-3 min): faz poll limitado; se estourar o orçamento, devolve erro claro."""
    cfg = APPSTATE.get("llm_pagas") or {}
    gk = (cfg.get("ext-gemini-pro") or {}).get("api_key") or (cfg.get("ext-gemini") or {}).get("api_key")
    if not gk:
        return None, "vídeo por IA requer a chave do Gemini (Veo) — configure em Model Ops → LLMs pagas."
    key = _dec(gk)
    base = "https://generativelanguage.googleapis.com/v1beta"
    veo_model = os.getenv("VEO_MODEL", "veo-3.1-fast-generate-preview")
    inst = {"prompt": prompt}
    if imagem_b64:
        inst["image"] = {"bytesBase64Encoded": imagem_b64, "mimeType": "image/png"}
    try:
        op = None; last = ""
        for _vm in (veo_model, "veo-3.1-generate-preview", "veo-3.1-lite-generate-preview"):
            r = httpx.post(f"{base}/models/{_vm}:predictLongRunning",
                           params={"key": key}, timeout=60,
                           json={"instances": [inst], "parameters": {"durationSeconds": int(max(4, min(dur, 8)))}})
            if r.status_code == 200:
                op = (r.json() or {}).get("name"); break
            last = f"Veo {r.status_code}: {r.text[:160]}"
            if r.status_code != 404:                        # 404 = modelo indisponível → tenta o próximo
                break
        if not op:
            return None, (last or "Veo: operação não retornada.")
        import time as _t
        prazo = _t.time() + 170                                  # orçamento de poll (~3 min)
        while _t.time() < prazo:
            _t.sleep(8)
            p = httpx.get(f"{base}/{op}", params={"key": key}, timeout=30)
            if p.status_code != 200:
                continue
            j = p.json() or {}
            if j.get("done"):
                if j.get("error"):
                    return None, f"Veo erro: {str(j['error'])[:160]}"
                resp = (j.get("response") or {})
                amostras = (((resp.get("generateVideoResponse") or {}).get("generatedSamples")) or
                            (resp.get("generatedSamples")) or [])
                uri = (amostras[0].get("video") or {}).get("uri") if amostras else None
                if not uri:
                    return None, "Veo: vídeo não encontrado na resposta."
                dl = httpx.get(uri, params={"key": key}, timeout=90, follow_redirects=True)
                if dl.status_code == 200 and len(dl.content) > 10000:
                    return dl.content, None
                return None, f"Veo download {dl.status_code}"
        return None, "Veo: tempo esgotado no poll (o vídeo pode ainda estar sendo gerado)."
    except Exception as e:
        return None, f"Veo erro: {str(e)[:160]}"


def _marca_best_text_model():
    """Melhor modelo de texto disponível p/ a descrição criativa da cena (prefere pago; cai p/ o local soberano)."""
    cfg = APPSTATE.get("llm_pagas") or {}
    for a in ("ext-claude", "ext-openai", "ext-gemini-pro"):
        c = cfg.get(a) or {}
        if c.get("api_key") and c.get("ativo", True):
            return a
    return "chat"


_MARCA_CENA_SYS = (
    "Você é diretor de arte e fotógrafo publicitário premiado. Tarefa: descrever UMA cena visual para um "
    "anúncio que uma IA de imagem vai gerar. Aplique as melhores técnicas de marketing visual: um único "
    "herói/foco claro; storytelling aspiracional coerente com a marca e o público; composição pela regra dos "
    "terços DEIXANDO uma área limpa (céu, parede, mesa ou desfoque) para sobrepor texto depois; iluminação "
    "intencional; profundidade de campo rasa; direção de cor alinhada à paleta da marca; ambientação realista "
    "e desejável de estilo de vida; pessoas reais e naturais quando fizer sentido. "
    "NUNCA inclua texto, letras, números, logotipos ou marcas d'água na imagem. "
    "Responda com UM parágrafo em INGLÊS (55-90 palavras), apenas a descrição da cena, sem título e sem aspas."
)


def _marca_cena_prompt(m, titulo, legenda, cta, formato, hint="", midia="imagem"):
    """Cerne como diretor de arte: monta um prompt DETALHADO de cena p/ a IA, ancorado no DNA da marca + na
    copy da peça + em boas práticas de publicidade. Metade criativa (LLM) + andaime técnico determinístico."""
    dna = m.get("dna") or {}
    fmt = _MARCA_FORMATOS.get(formato) or _MARCA_FORMATOS["ig_post"]
    pal = ", ".join((dna.get("paleta") or [])[:4])
    cat = m.get("catalogo") or []
    prod = "; ".join(str(p.get("nome")) for p in cat[:5]) or ", ".join(_dna_lista(dna.get("produtos")))
    brief = (f"Marca: {_dna_txt(dna.get('nome_marca'))}\nSetor/resumo: {_dna_txt(dna.get('resumo'))}\n"
             f"Tom de voz: {_dna_txt(dna.get('tom_de_voz'))}\nPúblico-alvo: {_dna_txt(dna.get('publico_alvo'))}\n"
             f"Produtos: {prod}\nPeça ({fmt['nome']}) — título: {titulo}\nlegenda: {legenda}\nCTA: {cta}\n"
             f"Paleta da marca (hex): {pal}\n" + (f"Dica do usuário para a cena: {hint}\n" if hint else "")
             + "Descreva a cena publicitária ideal para esta peça.")
    try:
        cena = _strip_think(_chat_resiliente(_marca_best_text_model(),
                            [{"role": "system", "content": _MARCA_CENA_SYS}, {"role": "user", "content": brief}],
                            max_tokens=700) or "").strip().strip('"').strip()
    except Exception:
        cena = ""
    if not cena:
        cena = (f"A premium, aspirational lifestyle scene for {_dna_txt(dna.get('nome_marca')) or 'the brand'} "
                f"conveying: {titulo or 'the brand promise'}. A single clear hero subject in a clean, modern setting.")
    if fmt["h"] > fmt["w"]:
        orient = "vertical 9:16 composition"
    elif fmt["w"] > fmt["h"]:
        orient = "horizontal 16:9 composition"
    else:
        orient = "square 1:1 composition"
    if midia == "video":
        scaffold = (f" Cinematic advertising video, {orient}, smooth subtle camera motion (slow push-in or gentle pan), "
                    f"sharp focus on the hero, shallow depth of field, intentional lighting, clean negative space for "
                    f"later text overlay, color grading harmonizing with the palette {pal or 'brand colors'}, "
                    f"high-end, photorealistic. No text, no letters, no logos, no watermark.")
    else:
        scaffold = (f" Professional advertising photography, {orient}, sharp focus on the hero, shallow depth of field, "
                    f"cinematic intentional lighting, tasteful negative space in the top or side to overlay text later, "
                    f"color grading harmonizing with the palette {pal or 'brand colors'}, high-end editorial quality, "
                    f"photorealistic, 4k. No text, no letters, no numbers, no logos, no watermark.")
    return (cena + scaffold)[:1600]


