@app.post("/marca/{mid}/campanha")
def marca_campanha(mid: str, body: CampanhaReq):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    dna = m.get("dna") or {}
    fmts = [f for f in (body.formatos or []) if f in _MARCA_FORMATOS] or ["ig_post"]
    cat = m.get("catalogo") or []
    cat_txt = "; ".join(f"{p.get('nome')}: {p.get('descricao')}" for p in cat[:10]) if cat else ", ".join(_dna_lista(dna.get('produtos')))
    ctx = (f"Marca: {_dna_txt(dna.get('nome_marca'))}\nResumo: {_dna_txt(dna.get('resumo'))}\n"
           f"Tom de voz: {_dna_txt(dna.get('tom_de_voz'))}\nPúblico: {_dna_txt(dna.get('publico_alvo'))}\n"
           f"Valores: {', '.join(_dna_lista(dna.get('valores')))}\nProdutos/catálogo: {cat_txt}")
    # EXPERIÊNCIA: copies que o usuário APROVOU na biblioteca viram exemplos few-shot (aprende o que ele gosta)
    aprovadas = [it.get("texto") for it in (m.get("biblioteca") or []) if it.get("tipo") in ("copy", "campanha") and it.get("texto")][:3]
    if aprovadas:
        ctx += "\n\nEXEMPLOS DE COPY QUE A MARCA JÁ APROVOU (siga MUITO de perto este tom, estilo e nível de formalidade):\n- " + "\n- ".join(a[:300] for a in aprovadas)
    itens = []
    for f in fmts[:6]:
        prompt = (f"Você é redator de marketing. Crie 1 peça para {_MARCA_FORMATOS[f]['nome']} da marca, no tom dela, "
                  f"para o objetivo: {body.objetivo or 'engajar e apresentar a marca'}. Responda SOMENTE com JSON: "
                  '{"titulo":"curto e chamativo","legenda":"2-4 frases","cta":"chamada de ação curta","hashtags":["#..."]}.'
                  "\n\n" + ctx)
        it = {"formato": f, "formato_nome": _MARCA_FORMATOS[f]["nome"], "titulo": "", "legenda": "", "cta": "", "hashtags": []}
        try:
            j = _extract_json(_strip_think(_chat_resiliente(_marca_best_text_model(), [{"role": "user", "content": prompt}], max_tokens=800) or ""))
            if isinstance(j, dict):
                for k in ("titulo", "legenda", "cta", "hashtags"):
                    if j.get(k):
                        it[k] = j[k]
        except Exception:
            pass
        itens.append(it)
    _event("campanha gerada", f"{dna.get('nome_marca')} · {len(itens)} peça(s)", actor=_actor())
    return {"marca": dna.get("nome_marca"), "objetivo": body.objetivo, "itens": itens}


@app.post("/marca/{mid}/criativo")
def marca_criativo(mid: str, body: CriativoReq):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    dna = m.get("dna") or {}
    fmt = _MARCA_FORMATOS.get(body.formato) or _MARCA_FORMATOS["ig_post"]
    run = "mk" + uuid.uuid4().hex[:12]
    import base64 as _b64
    spec = {"w": fmt["w"], "h": fmt["h"], "paleta": dna.get("paleta") or ["#6c8cff", "#111826"],
            "nome_marca": dna.get("nome_marca") or "", "titulo": body.titulo or dna.get("nome_marca") or "",
            "legenda": body.legenda or "", "cta": body.cta or ""}
    variante = (body.variante or "auto").lower()
    aviso = ""; bg = None; cena_prompt = ""
    # 1) imagem base por IA (híbrido) — quando a flag está ligada, o Cerne DESCREVE a cena sozinho
    #    (diretor de arte, técnicas de marketing) usando título/legenda/CTA + DNA da marca + dica opcional.
    if body.usar_ia_imagem or body.imagem_prompt:
        if body.usar_ia_imagem:
            cena_prompt = _marca_cena_prompt(m, body.titulo, body.legenda, body.cta, body.formato, body.imagem_prompt or "")
            prompt = cena_prompt
        else:                                              # compat: prompt manual sem a flag
            prompt = f"{body.imagem_prompt}. Estilo de marca, sem texto, alta qualidade, fotográfico/editorial."
        ib, err = _marca_imagem_hibrida(prompt, "1024x1024")
        if ib:
            bg = ib
        elif err:
            aviso = err
    # 1b) foto de um produto do catálogo
    if not bg and body.produto_id:
        p = next((x for x in (m.get("catalogo") or []) if x.get("id") == body.produto_id), None)
        if p and p.get("imagem_url"):
            try:
                b = _http_get(p["imagem_url"], timeout=12).content
                if 8000 < len(b) < 8 * 1024 * 1024:
                    bg = b
            except Exception:
                pass
    # 2) imagem real do site (soberano) — quando auto/foto e sem imagem de IA
    if not bg and variante in ("auto", "foto"):
        bg = _marca_bg_bytes(dna)
        if not bg and variante == "foto":
            aviso = aviso or "sem imagem utilizável no site — usei fundo de marca."
    if bg:
        spec["bg_b64"] = _b64.b64encode(bg).decode(); spec["variante"] = "foto"
    else:
        spec["variante"] = "solido" if variante == "solido" else "geo"
    # logo (sobre imagem/fundo)
    if body.usar_logo and dna.get("logo"):
        try:
            lb = _http_get(dna["logo"], timeout=12).content
            if lb and len(lb) < 4 * 1024 * 1024:
                spec["logo_b64"] = _b64.b64encode(lb).decode()
        except Exception:
            pass
    saida = _sandbox_exec(_marca_criativo_code(spec, "criativo.png"), "python", run)
    if "OK arquivo:" not in (saida or ""):
        _sb_reset(run)
        raise HTTPException(status_code=500, detail=f"falha ao compor: {(saida or '')[:200]}")
    arts = _agente_coletar_artefatos(run)
    _sb_reset(run)
    _event("criativo gerado", f"{dna.get('nome_marca')} · {fmt['nome']} · {spec['variante']}", actor=_actor())
    return {"formato": body.formato, "formato_nome": fmt["nome"], "artefatos": arts, "aviso": aviso,
            "estilo": spec["variante"], "cena_prompt": cena_prompt}


