def marca_produto_del(mid: str, pid: str):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    m["catalogo"] = [p for p in (m.get("catalogo") or []) if p.get("id") != pid]
    _appstate_save(APPSTATE)
    return {"ok": True, "catalogo": m["catalogo"]}


# ---- Biblioteca da marca (histórico de materiais APROVADOS) + upload/preview de imagens ----
# Une tudo que o Cerne cria por marca num acervo permanente; os aprovados viram exemplos (few-shot) das próximas campanhas.
_MARCA_LIB_DIR = os.getenv("MARCA_LIB_DIR", "/data/app/marca_lib")
_IMG_EXT = {".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp", ".gif": "image/gif"}


def _marca_lib_sub(sub):
    safe = "".join(c for c in (sub or "") if c.isalnum() or c in "-_")[:64] or "geral"
    d = os.path.join(_MARCA_LIB_DIR, safe)
    os.makedirs(d, exist_ok=True)
    return d


def _marca_src_path(url):
    """Resolve o caminho local de um artefato (do agente, que expira) OU da biblioteca (permanente)."""
    import re as _re
    mo = _re.match(r"^/agentes/artefato/([^/]+)/(.+)$", url or "")
    if mo:
        p = os.path.realpath(os.path.join(_ART_DIR, "".join(c for c in mo.group(1) if c.isalnum() or c in "-_")[:64], os.path.basename(mo.group(2))))
        return p if p.startswith(os.path.realpath(_ART_DIR) + os.sep) else None
    mo = _re.match(r"^/marca/arquivo/([^/]+)/(.+)$", url or "")
    if mo:
        p = os.path.realpath(os.path.join(_MARCA_LIB_DIR, "".join(c for c in mo.group(1) if c.isalnum() or c in "-_")[:64], os.path.basename(mo.group(2))))
        return p if p.startswith(os.path.realpath(_MARCA_LIB_DIR) + os.sep) else None
    return None


@app.get("/marca/arquivo/{sub}/{nome}")
def marca_arquivo(sub: str, nome: str):
    safe_sub = "".join(c for c in (sub or "") if c.isalnum() or c in "-_")[:64]
    safe_nome = os.path.basename(nome or "")
    base = os.path.realpath(_MARCA_LIB_DIR)
    p = os.path.realpath(os.path.join(_MARCA_LIB_DIR, safe_sub, safe_nome))
    if not safe_sub or not safe_nome or not p.startswith(base + os.sep) or not os.path.isfile(p):
        raise HTTPException(status_code=404, detail="arquivo não encontrado")
    mime = _ART_MIME.get(os.path.splitext(safe_nome)[1].lower(), "application/octet-stream")
    return FileResponse(p, media_type=mime, filename=safe_nome)


@app.post("/marca-upload")
async def marca_upload(file: UploadFile = File(...)):
    """Upload de imagem de referência (produto/cena) — retorna uma URL servida pelo Cerne (soberano)."""
    _assert_admin_sessao()
    ext = os.path.splitext(file.filename or "")[1].lower()
    if ext not in _IMG_EXT:
        raise HTTPException(status_code=400, detail="envie uma imagem (png, jpg, webp ou gif)")
    dados = await file.read()
    if not (20 < len(dados) < 12 * 1024 * 1024):
        raise HTTPException(status_code=400, detail="imagem inválida ou grande demais (máx. 12MB)")
    nome = uuid.uuid4().hex[:16] + ext
    open(os.path.join(_marca_lib_sub("uploads"), nome), "wb").write(dados)
    return {"url": f"/marca/arquivo/uploads/{nome}", "nome": file.filename, "bytes": len(dados)}


class BibliotecaReq(BaseModel):
    artefato: str = ""           # /agentes/artefato/<run>/<nome> OU /marca/arquivo/<sub>/<nome>
    tipo: str = "criativo"       # criativo | brandbook | site | photoshoot | video | campanha | copy
    titulo: str = ""
    texto: str = ""             # p/ copy/campanha aprovada (vira few-shot das próximas)
    meta: dict = {}


@app.post("/marca/{mid}/biblioteca")
def marca_lib_add(mid: str, body: BibliotecaReq):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    import shutil as _sh
    item = {"id": "lb" + uuid.uuid4().hex[:10], "tipo": (body.tipo or "criativo"),
            "titulo": (body.titulo or body.tipo or "material")[:120], "criado": time.strftime("%Y-%m-%dT%H:%M:%S"),
            "meta": body.meta or {}}
    if body.artefato:                                     # copia o arquivo p/ o store PERMANENTE da marca (artefato expira em 12h)
        src = _marca_src_path(body.artefato)
        if src and os.path.isfile(src):
            ext = os.path.splitext(src)[1].lower() or ".bin"
            nome = item["id"] + ext
            _sh.copy(src, os.path.join(_marca_lib_sub(mid), nome))
            item["url"] = f"/marca/arquivo/{''.join(c for c in mid if c.isalnum() or c in '-_')[:64]}/{nome}"
            item["nome"] = nome
            item["mime"] = _ART_MIME.get(ext, "")
        else:
            raise HTTPException(status_code=400, detail="artefato não encontrado (talvez tenha expirado — gere de novo e salve)")
    if body.texto:
        item["texto"] = body.texto[:4000]
    m.setdefault("biblioteca", []).insert(0, item)
    if len(m["biblioteca"]) > 200:
        m["biblioteca"] = m["biblioteca"][:200]
    _appstate_save(APPSTATE)
    _event("material salvo na biblioteca", f"{(m.get('dna') or {}).get('nome_marca','')} · {item['tipo']}", actor=_actor())
    return item


@app.delete("/marca/{mid}/biblioteca/{iid}")
def marca_lib_del(mid: str, iid: str):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    it = next((x for x in (m.get("biblioteca") or []) if x.get("id") == iid), None)
    if it and it.get("url"):
        try:
            p = _marca_src_path(it["url"])
            if p and os.path.isfile(p):
                os.remove(p)
        except Exception:
            pass
    m["biblioteca"] = [x for x in (m.get("biblioteca") or []) if x.get("id") != iid]
    _appstate_save(APPSTATE)
    return {"ok": True}


