# --- #1 A/B preditivo: o público sintético (Simulador) escolhe entre 2 variações ---
class AbReq(BaseModel):
    opcao_a: str = ""
    opcao_b: str = ""
    formato: str = "ig_post"
    n: int = 14


@app.post("/marca/{mid}/ab")
def marca_ab(mid: str, body: AbReq):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    if not (body.opcao_a or "").strip() or not (body.opcao_b or "").strip():
        raise HTTPException(status_code=400, detail="informe as duas opções (A e B)")
    dna = m.get("dna") or {}
    publico = _dna_txt(dna.get("publico_alvo")) or _dna_txt(dna.get("resumo"))
    ctx = f"Marca: {_dna_txt(dna.get('nome_marca'))}. Tom: {_dna_txt(dna.get('tom_de_voz'))}. Público: {publico}."
    personas = _cen_personas(ctx, body.n, publico, ["rede_aberta"], atores=None)
    elenco = "\n".join(f'{p["id"]} | {p["nome"]} ({p["grupo"]}): {p["perfil"]}; viés: {p["vies"]}' for p in personas)
    prompt = ("Cada persona abaixo deve escolher qual peça a faz mais querer agir (A ou B) e por quê, no ponto de vista dela.\n"
              f"OPÇÃO A: {body.opcao_a[:600]}\nOPÇÃO B: {body.opcao_b[:600]}\n\nPERSONAS:\n{elenco}\n\n"
              'Responda SOMENTE com JSON: {"votos":[{"persona_id":"...","escolha":"A|B","motivo":"curto"}]}')
    arr = _cen_json_list(_chat_resiliente(_marca_best_text_model(), [{"role": "user", "content": prompt}], max_tokens=3000) or "", "votos")
    byid = {p["id"]: p for p in personas}
    va = vb = 0; mot_a = []; mot_b = []
    for it in (arr or []):
        if not isinstance(it, dict):
            continue
        esc_ = str(it.get("escolha", "")).strip().upper()[:1]
        mot = _dna_txt(it.get("motivo"))
        if esc_ == "A":
            va += 1; (mot_a.append(mot) if mot else None)
        elif esc_ == "B":
            vb += 1; (mot_b.append(mot) if mot else None)
    tot = va + vb or 1
    venc = "A" if va > vb else "B" if vb > va else "empate"
    return {"vencedor": venc, "votos_a": va, "votos_b": vb, "pct_a": round(100 * va / tot), "pct_b": round(100 * vb / tot),
            "motivos_a": mot_a[:4], "motivos_b": mot_b[:4], "n": len(personas)}


# --- #2 On-brand score: quão aderente à marca está um texto/imagem ---
_ONBRAND_IMG_TPL = r'''
import base64, json, io
from PIL import Image
S = json.loads(base64.b64decode("__SPEC__").decode("utf-8"))
im = Image.open(io.BytesIO(base64.b64decode(S["img_b64"]))).convert("RGB"); im.thumbnail((150, 150))
px = list(im.getdata())
def hx(h):
    h = str(h).lstrip("#"); h = "".join(c*2 for c in h) if len(h) == 3 else h
    try: return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))
    except Exception: return (128, 128, 128)
pal = [hx(c) for c in S.get("paleta", [])] or [(128, 128, 128)]
def dist(a, b): return (sum((a[i]-b[i])**2 for i in range(3))) ** 0.5
hit = sum(1 for p in px if min(dist(p, c) for c in pal) < 70)
print("MATCH", round(100.0*hit/max(1, len(px))))
'''


class OnbrandReq(BaseModel):
    texto: str = ""
    imagem_url: str = ""


@app.post("/marca/{mid}/onbrand")
def marca_onbrand(mid: str, body: OnbrandReq):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    dna = m.get("dna") or {}
    res = {"score": None, "paleta_match": None, "notas": [], "sugestoes": []}
    if body.imagem_url:
        try:
            import base64 as _b64
            b = _http_get(body.imagem_url, timeout=15).content
            spec = {"img_b64": _b64.b64encode(b).decode(), "paleta": dna.get("paleta") or []}
            code = _ONBRAND_IMG_TPL.replace("__SPEC__", _b64.b64encode(json.dumps(spec).encode()).decode())
            run = "ob" + uuid.uuid4().hex[:10]
            out = _sandbox_exec(code, "python", run, timeout=30); _sb_reset(run)
            mo = re.search(r"MATCH (\d+)", out or "")
            if mo:
                res["paleta_match"] = int(mo.group(1))
        except Exception as e:
            print("[cerne] onbrand img:", str(e)[:100])
    if (body.texto or "").strip():
        prompt = (f"Avalie a aderência do TEXTO à marca. Marca: {_dna_txt(dna.get('nome_marca'))}; "
                  f"tom de voz: {_dna_txt(dna.get('tom_de_voz'))}; valores: {', '.join(_dna_lista(dna.get('valores')))}; "
                  f"público: {_dna_txt(dna.get('publico_alvo'))}.\nTEXTO: \"{body.texto[:1500]}\"\n"
                  'Responda SOMENTE JSON: {"score":0-100,"notas":["o que está on-brand"],"sugestoes":["ajustes p/ ficar mais on-brand"]}')
        j = _extract_json(_strip_think(_chat_resiliente(_marca_best_text_model(), [{"role": "user", "content": prompt}], max_tokens=700) or "")) or {}
        try:
            res["score"] = int(float(j.get("score"))) if j.get("score") is not None else None
        except Exception:
            res["score"] = None
        res["notas"] = _as_list(j.get("notas"))[:5]
        res["sugestoes"] = _as_list(j.get("sugestoes"))[:5]
    if res["score"] is None and res["paleta_match"] is not None:
        res["score"] = res["paleta_match"]
    if res["score"] is None:
        raise HTTPException(status_code=400, detail="informe um texto e/ou uma imagem para avaliar")
    return res


