class SiteReq(BaseModel):
    objetivo: str = ""


@app.post("/marca/{mid}/site")
def marca_site(mid: str, body: SiteReq):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    dna = _marca_pub(m)["dna"]
    prompt = ("Gere uma LANDING PAGE em HTML completa e MODERNA (um único arquivo, todo o CSS inline em <style>, "
              "SEM bibliotecas externas, responsiva). Use EXATAMENTE estas cores da marca: " + ", ".join(dna.get("paleta") or []) +
              ". Tipografia (use como font-family, com fallback de sistema): " + (", ".join(dna.get("fontes") or []) or "system-ui") +
              ". Marca: " + (dna.get("nome_marca") or "") + ". Tom: " + (dna.get("tom_de_voz") or "") +
              ". Público: " + (dna.get("publico_alvo") or "") + ". Produtos: " + ", ".join(dna.get("produtos") or []) +
              ". Objetivo: " + (body.objetivo or "apresentar a marca e converter") +
              ". Inclua: header com o nome da marca, hero com título forte + subtítulo + botão de CTA, seção de "
              "benefícios/produtos (cards), uma faixa de prova social simples e um rodapé. Responda SOMENTE com o HTML, "
              "começando em <!doctype html>.")
    try:
        html = _chat_completo(_marca_best_text_model(), [{"role": "user", "content": prompt}], max_tokens=6000, conts=3) or ""
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"falha ao gerar o site: {str(e)[:160]}")
    html = _strip_think(html)
    mo = re.search(r"(?is)<!doctype html.*?</html>", html) or re.search(r"(?is)<html.*?</html>", html)
    if mo:
        html = mo.group(0)
    html = re.sub(r"^```[a-z]*\n?|\n?```$", "", html.strip())
    run = "st" + uuid.uuid4().hex[:12]
    _sb_write(run, "site.html", html)
    arts = _agente_coletar_artefatos(run); _sb_reset(run)
    _event("site on-brand gerado", dna.get("nome_marca") or "", actor=_actor())
    return {"html": html[:200000], "artefatos": arts}


# ---- Photoshoot: foto do produto → recorte (rembg) + fundo de estúdio/marca + sombra (soberano) ----
_PHOTOSHOOT_TPL = r'''
import base64, json, io
from PIL import Image, ImageDraw, ImageFilter
from rembg import remove, new_session
S = json.loads(base64.b64decode("__SPEC__").decode("utf-8"))
W = H = 1080
pal = S.get("paleta") or ["#6c8cff", "#111826"]
fundo = S.get("fundo", "studio")
def hx(h):
    h = str(h or "#888").lstrip("#")
    if len(h) == 3: h = "".join(c*2 for c in h)
    try: return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))
    except Exception: return (136, 136, 136)
def mix(a, b, t): return tuple(int(a[i]+(b[i]-a[i])*t) for i in range(3))
sess = new_session("u2net")
cut = Image.open(io.BytesIO(remove(base64.b64decode(S["prod_b64"]), session=sess))).convert("RGBA")
if S.get("scene_b64"):                              # cena (foto fornecida ou gerada por IA): produto sobre o cenário
    sc = Image.open(io.BytesIO(base64.b64decode(S["scene_b64"]))).convert("RGB")
    r0 = max(W/sc.width, H/sc.height); sc = sc.resize((max(1, int(sc.width*r0)+1), max(1, int(sc.height*r0)+1)))
    ox0 = (sc.width-W)//2; oy0 = (sc.height-H)//2; bg = sc.crop((ox0, oy0, ox0+W, oy0+H))
    from PIL import ImageEnhance
    bg = ImageEnhance.Brightness(bg).enhance(0.92)
elif fundo == "marca":
    c1 = hx(pal[0]); c2 = mix(c1, (0, 0, 0), 0.5)
    strip = Image.new("RGB", (1, H))
    for y in range(H): strip.putpixel((0, y), mix(c1, c2, y/(H-1)))
    bg = strip.resize((W, H))
else:
    bg = Image.new("RGB", (W, H), (236, 238, 243))
    sweep = Image.new("L", (1, H), 0)
    for y in range(H): sweep.putpixel((0, y), int(70*(y/(H-1))))
    bg = Image.composite(Image.new("RGB", (W, H), (200, 206, 216)), bg, sweep.resize((W, H)))
mh = int(H*0.72); r = min(mh/cut.height, (W*0.82)/cut.width); cut = cut.resize((max(1, int(cut.width*r)), max(1, int(cut.height*r))))
px = (W-cut.width)//2; py = int(H*0.58)-cut.height//2
sh = Image.new("RGBA", (W, H), (0, 0, 0, 0)); sd = ImageDraw.Draw(sh)
sd.ellipse([px+cut.width*0.12, py+cut.height-int(H*0.03), px+cut.width*0.88, py+cut.height+int(H*0.05)], fill=(0, 0, 0, 130))
bg = Image.alpha_composite(bg.convert("RGBA"), sh.filter(ImageFilter.GaussianBlur(int(H*0.022))))
bg.alpha_composite(cut, (px, py))
bg.convert("RGB").save(S["nome"]); print("OK arquivo:", S["nome"])
'''


class PhotoshootReq(BaseModel):
    produto_id: str = ""
    imagem_url: str = ""
    fundo: str = "studio"        # studio | marca | cena
    cena_url: str = ""           # coloca o produto sobre esta imagem de cenário (soberano)
    cena_prompt: str = ""        # gera o cenário por IA (híbrido; requer chave de imagem)


@app.post("/marca/{mid}/photoshoot")
def marca_photoshoot(mid: str, body: PhotoshootReq):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    src = body.imagem_url
    if not src and body.produto_id:
        p = next((x for x in (m.get("catalogo") or []) if x.get("id") == body.produto_id), None)
        src = (p or {}).get("imagem_url")
    if not src:
        raise HTTPException(status_code=400, detail="informe a URL da foto do produto (ou um produto do catálogo com foto)")
    try:
        pb = _http_get(src, timeout=15).content
        if not (2000 < len(pb) < 12 * 1024 * 1024):
            raise ValueError("imagem inválida")
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"não consegui baixar a foto: {str(e)[:120]}")
    import base64 as _b64
    dna = m.get("dna") or {}
    aviso = ""; scene_b64 = None
    if body.cena_prompt:                               # cenário por IA (híbrido)
        ib, err = _marca_imagem_hibrida(body.cena_prompt + ". Cenário/ambiente fotográfico de fundo, sem texto.", "1024x1024")
        if ib:
            scene_b64 = _b64.b64encode(ib).decode()
        elif err:
            aviso = err
    if not scene_b64 and body.cena_url:                # cenário via imagem fornecida (soberano)
        try:
            sb = _http_get(body.cena_url, timeout=15).content
            if 2000 < len(sb) < 12 * 1024 * 1024:
                scene_b64 = _b64.b64encode(sb).decode()
        except Exception:
            aviso = aviso or "não consegui baixar a imagem da cena — usei o fundo padrão."
    spec = {"paleta": dna.get("paleta") or ["#6c8cff", "#111826"], "fundo": (body.fundo or "studio"),
            "prod_b64": _b64.b64encode(pb).decode(), "nome": "photoshoot.png"}
    if scene_b64:
        spec["scene_b64"] = scene_b64
    code = _PHOTOSHOOT_TPL.replace("__SPEC__", _b64.b64encode(json.dumps(spec, ensure_ascii=False).encode()).decode())
    run = "ps" + uuid.uuid4().hex[:12]
    saida = _sandbox_exec(code, "python", run, timeout=90)
    if "OK arquivo:" not in (saida or ""):
        _sb_reset(run); raise HTTPException(status_code=500, detail=f"falha no photoshoot: {(saida or '')[:200]}")
    arts = _agente_coletar_artefatos(run); _sb_reset(run)
    _event("photoshoot gerado", f"{dna.get('nome_marca')} · {'cena' if scene_b64 else body.fundo}", actor=_actor())
    return {"artefatos": arts, "aviso": aviso}


# ---- Animate: criativo estático → vídeo curto (Ken Burns + fade) via ffmpeg (soberano) ----
_ANIMATE_TPL = r'''
import subprocess, os
from PIL import Image
base = Image.open("__BASE__").convert("RGB")
W, H = base.size
W -= W % 2; H -= H % 2
base = base.resize((W, H))
fps = 24; dur = __DUR__; N = max(24, int(fps*dur))
os.makedirs("frames", exist_ok=True)
z0, z1 = 1.06, 1.16
for i in range(N):
    t = i/max(1, N-1); z = z0+(z1-z0)*t
    cw, ch = int(W/z), int(H/z)
    ox = int((W-cw)*(0.5+0.18*(t-0.5)*2)); oy = int((H-ch)*(0.5+0.12*(t-0.5)*2))
    ox = max(0, min(W-cw, ox)); oy = max(0, min(H-ch, oy))
    fr = base.crop((ox, oy, ox+cw, oy+ch)).resize((W, H))
    if t < 0.12:
        fr = Image.blend(Image.new("RGB", (W, H), (0, 0, 0)), fr, t/0.12)
    fr.save("frames/f_%04d.png" % i)
subprocess.run(["ffmpeg", "-y", "-framerate", str(fps), "-i", "frames/f_%04d.png",
                "-c:v", "libx264", "-pix_fmt", "yuv420p", "-movflags", "+faststart", "-loglevel", "error", "__OUT__"],
               check=True, timeout=140)
print("OK arquivo:", "__OUT__", "|", W, "x", H, "|", round(dur, 1), "s")
'''


class AnimateReq(BaseModel):
    formato: str = "ig_story"
    titulo: str = ""
    legenda: str = ""
    cta: str = ""
    usar_logo: bool = True
    variante: str = "auto"
    produto_id: str = ""
    dur: float = 4.0
    usar_ia_video: bool = False  # flag: liga o vídeo por IA (Veo); o Cerne descreve a cena sozinho
    ia_prompt: str = ""          # (opcional) dica de cena; se vazio e a flag ligada, o Cerne cria a descrição


@app.post("/marca/{mid}/animate")
def marca_animate(mid: str, body: AnimateReq):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    dna = m.get("dna") or {}
    fmt = _MARCA_FORMATOS.get(body.formato) or _MARCA_FORMATOS["ig_story"]
    import base64 as _b64
    _aviso_ia = ""
    if body.usar_ia_video or body.ia_prompt:                   # vídeo por IA (Veo) — híbrido, gated na chave
        prompt_v = (_marca_cena_prompt(m, body.titulo, body.legenda, body.cta, body.formato, body.ia_prompt or "",
                                       midia="video") if body.usar_ia_video else body.ia_prompt)
        vb, verr = _marca_video_ia(prompt_v, dur=int(max(4, min(body.dur or 6, 8))))
        if vb:
            run = "an" + uuid.uuid4().hex[:12]
            art = _art_salvar_bytes(run, "reel_ia.mp4", vb, "video/mp4")
            _event("animate IA gerado", f"{dna.get('nome_marca')} · Veo", actor=_actor())
            return {"artefatos": [art], "formato_nome": fmt["nome"], "aviso": "vídeo gerado por IA (Veo)"}
        # sem chave/erro → segue no motion-graphics soberano, avisando
        _aviso_ia = "vídeo por IA indisponível (" + (verr or "") + ") — gerei motion-graphics soberano."
    spec = {"w": fmt["w"], "h": fmt["h"], "paleta": dna.get("paleta") or ["#6c8cff", "#111826"],
            "nome_marca": dna.get("nome_marca") or "", "titulo": body.titulo or dna.get("nome_marca") or "",
            "legenda": body.legenda or "", "cta": body.cta or ""}
    bg = None
    if body.produto_id:
        p = next((x for x in (m.get("catalogo") or []) if x.get("id") == body.produto_id), None)
        if p and p.get("imagem_url"):
            try:
                b = _http_get(p["imagem_url"], timeout=12).content
                if 8000 < len(b) < 8 * 1024 * 1024:
                    bg = b
            except Exception:
                pass
    if not bg and body.variante in ("auto", "foto"):
        bg = _marca_bg_bytes(dna)
    if bg:
        spec["bg_b64"] = _b64.b64encode(bg).decode(); spec["variante"] = "foto"
    else:
        spec["variante"] = "solido" if body.variante == "solido" else "geo"
    if body.usar_logo and dna.get("logo"):
        try:
            lb = _http_get(dna["logo"], timeout=12).content
            if lb and len(lb) < 4 * 1024 * 1024:
                spec["logo_b64"] = _b64.b64encode(lb).decode()
        except Exception:
            pass
    run = "an" + uuid.uuid4().hex[:12]
    s1 = _sandbox_exec(_marca_criativo_code(spec, "base.png"), "python", run, timeout=40)
    if "OK arquivo:" not in (s1 or ""):
        _sb_reset(run); raise HTTPException(status_code=500, detail=f"falha ao compor a base: {(s1 or '')[:180]}")
    dur = max(3.0, min(float(body.dur or 4.0), 8.0))
    code = _ANIMATE_TPL.replace("__BASE__", "base.png").replace("__OUT__", "reel.mp4").replace("__DUR__", str(dur))
    s2 = _sandbox_exec(code, "python", run, timeout=160)
    if "OK arquivo:" not in (s2 or ""):
        _sb_reset(run); raise HTTPException(status_code=500, detail=f"falha ao animar: {(s2 or '')[:200]}")
    arts = _agente_coletar_artefatos(run); _sb_reset(run)
    mp4 = [a for a in arts if a["nome"].endswith(".mp4")]
    _event("animate gerado", f"{dna.get('nome_marca')} · {fmt['nome']} · {dur}s", actor=_actor())
    return {"artefatos": mp4 or arts, "formato_nome": fmt["nome"], "aviso": _aviso_ia}


# ---- Publicar: envia o criativo (base64) + copy a um webhook (Make/Zapier/n8n → posta nas redes) ----
class WebhookReq(BaseModel):
    url: str = ""


class PublicarReq(BaseModel):
    artefato: str = ""           # /agentes/artefato/<run>/<nome>
    texto: str = ""
    webhook: str = ""


@app.post("/marca/{mid}/webhook")
def marca_webhook(mid: str, body: WebhookReq):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    m["publish_webhook"] = (body.url or "").strip()
    _appstate_save(APPSTATE)
    return {"ok": True, "webhook": m["publish_webhook"]}


@app.post("/marca/{mid}/publicar")
def marca_publicar(mid: str, body: PublicarReq):
    _assert_admin_sessao()
    m = _marca_por_id(mid)
    if not m:
        raise HTTPException(status_code=404, detail="marca não encontrada")
    wh = (body.webhook or m.get("publish_webhook") or "").strip()
    if not wh:
        raise HTTPException(status_code=400, detail="configure um webhook de publicação (Make/Zapier/n8n) em Materiais")
    mo = re.search(r"/agentes/artefato/([^/]+)/(.+)$", body.artefato or "")
    if not mo:
        raise HTTPException(status_code=400, detail="artefato inválido")
    run = "".join(c for c in mo.group(1) if c.isalnum() or c in "-_")[:64]
    nome = os.path.basename(mo.group(2))
    p = os.path.realpath(os.path.join(_ART_DIR, run, nome))
    if not p.startswith(os.path.realpath(_ART_DIR) + os.sep) or not os.path.isfile(p):
        raise HTTPException(status_code=404, detail="artefato não encontrado ou expirado")
    import base64 as _b64
    dados = open(p, "rb").read()
    payload = {"marca": (m.get("dna") or {}).get("nome_marca") or "", "texto": body.texto or "",
               "arquivo": nome, "mime": _ART_MIME.get(os.path.splitext(nome)[1].lower(), "application/octet-stream"),
               "arquivo_base64": _b64.b64encode(dados).decode()}
    try:
        r = httpx.post(wh, json=payload, timeout=30)
        _event("campanha publicada", f"{payload['marca']} · {nome} · webhook {r.status_code}", actor=_actor())
        return {"ok": 200 <= r.status_code < 300, "status": r.status_code, "resposta": (r.text or "")[:200]}
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"falha ao publicar no webhook: {str(e)[:140]}")


# ================= SALA DE CENÁRIOS — motor de enxame soberano (tipo MiroFish) =================
# Semente → grafo (LLM + Neo4j) → personas → rodadas de simulação social → relatório de predição.
# 100% na stack do Cerne (gateway/Ollama + Neo4j + sandbox). Motor de rodadas PRÓPRIO (sem OASIS/AGPL).
_CEN_AMBIENTES = {"rede_aberta": "rede social aberta (posts curtos, virais, tom público)",
                  "forum": "fórum de discussão (respostas longas, argumentativas, nichado)",
                  "noticias": "comentários em portal de notícias (reativos, polarizados)",
                  "interno": "canal interno/corporativo (formal, cauteloso)"}


def _cenarios():
    return [c for c in APPSTATE.get("cenarios", []) if c.get("org") == _tenant()]


def _cenario_por_id(cid):
    return next((c for c in _cenarios() if c.get("id") == cid), None)


def _cen_llm():
    return _marca_best_text_model()


def _cen_pub(c, full=False):
    base = {"id": c["id"], "titulo": c.get("titulo") or "(sem título)", "tipo": c.get("tipo") or "livre",
            "marca_id": c.get("marca_id") or "", "publico": c.get("publico") or "", "criado": c.get("criado"),
            "n_personas": len(c.get("personas") or []), "n_rodadas": len(c.get("rodadas") or []),
            "ambientes": c.get("ambientes") or ["rede_aberta"], "status": c.get("status") or "novo",
            "sentimento": (c.get("rodadas") or [{}])[-1].get("sentimento_medio") if c.get("rodadas") else None,
            "tem_relatorio": bool((c.get("relatorio") or {}).get("texto"))}
    base["agendamento"] = _cen_agenda_pub(c.get("agendamento"))
    if full:
        base.update({"semente": (c.get("semente") or "")[:4000], "grafo": c.get("grafo") or {},
                     "personas": c.get("personas") or [], "rodadas": c.get("rodadas") or [],
                     "relatorio": c.get("relatorio") or {}})
    return base


def _cen_agenda_pub(ag):
    if not ag:
        return None
    return {k: v for k, v in ag.items() if not k.startswith("_")}


def _cen_graph_write(cid, grafo):
    """Espelha o grafo do cenário no Neo4j (best-effort — reusa a infra do /graph)."""
    drv = _graph_driver()
    if not drv:
        return
    try:
        with drv.session() as s:
            s.run("MERGE (c:Cenario {id:$id})", id=cid)
            for e in (grafo.get("entidades") or [])[:80]:
                nome = str((e.get("nome") if isinstance(e, dict) else e) or "")[:90]
                tipo = str((e.get("tipo") if isinstance(e, dict) else "tema") or "tema")[:40]
                if nome:
                    s.run("MERGE (x:Entity {value:$v, type:$t}) MERGE (c:Cenario {id:$id}) "
                          "MERGE (c)-[:ENVOLVE]->(x)", v=nome, t=tipo, id=cid)
    except Exception as ex:
        print("[cerne] cenario grafo:", str(ex)[:100])


def _cen_grafo(semente):
    """GraphRAG leve: extrai entidades/relações/temas/atores da semente via LLM."""
    prompt = ("Você é um analista. Extraia o GRAFO DE CONHECIMENTO do texto abaixo. Responda SOMENTE com JSON: "
              '{"resumo":"1-2 frases","entidades":[{"nome":"...","tipo":"pessoa|org|lugar|produto|tema|evento"}],'
              '"relacoes":[{"de":"...","rel":"...","para":"..."}],"atores":["grupos/stakeholders afetados"],'
              '"temas":["temas centrais em disputa"]}.\n\nTEXTO:\n' + (semente or "")[:8000])
    try:
        j = _extract_json(_strip_think(_chat_resiliente(_cen_llm(), [{"role": "user", "content": prompt}], max_tokens=1400) or ""))
        if isinstance(j, dict):
            return {"resumo": _dna_txt(j.get("resumo")), "entidades": j.get("entidades") or [],
                    "relacoes": j.get("relacoes") or [], "atores": _dna_lista(j.get("atores")),
                    "temas": _dna_lista(j.get("temas"))}
    except Exception as e:
        print("[cerne] cen_grafo:", str(e)[:120])
    return {"resumo": "", "entidades": [], "relacoes": [], "atores": [], "temas": []}


def _cen_json_list(raw, key):
    """Extrai a LISTA (personas/posts) tolerando: array puro [...], {'key':[...]}, cercas ```json e lixo ao redor.
    Corrige o caso em que o LLM devolve o array direto (o _extract_json pegava só o 1º objeto)."""
    import json as _json
    import re as _re
    t = _strip_think(raw or "")
    mo = _re.search(r"```(?:json)?\s*(.*?)```", t, _re.S)
    if mo:
        t = mo.group(1)
    t = t.strip()
    try:
        v = _json.loads(t)
        if isinstance(v, list):
            return v
        if isinstance(v, dict) and isinstance(v.get(key), list):
            return v[key]
    except Exception:
        pass
    cands = sorted([s for s in [(t.find("["), "[", "]"), (t.find("{"), "{", "}")] if s[0] != -1])
    for pos, op, cl in cands:
        depth = 0; instr = False; escp = False
        for j in range(pos, len(t)):
            ch = t[j]
            if instr:
                if escp:
                    escp = False
                elif ch == "\\":
                    escp = True
                elif ch == '"':
                    instr = False
            elif ch == '"':
                instr = True
            elif ch == op:
                depth += 1
            elif ch == cl:
                depth -= 1
                if depth == 0:
                    try:
                        v = _json.loads(t[pos:j + 1])
                        if isinstance(v, list):
                            return v
                        if isinstance(v, dict) and isinstance(v.get(key), list):
                            return v[key]
                    except Exception:
                        pass
                    break
    return []


def _cen_personas(contexto, n, publico, ambientes, atores=None):
    """Gera n personas com perfil, viés, influência, stance inicial e ambiente (round-robin).
    Se o LLM falhar (rate-limit/JSON), cai num gerador DETERMINÍSTICO (stances espalhados, grupos dos atores
    do grafo) — a criação NUNCA falha; degrada com transparência."""
    n = max(6, min(int(n or 16), 40))
    pub = f"O público a simular: {publico}.\n" if publico else ""
    prompt = ("Você é sociólogo. Gere EXATAMENTE " + str(n) + " personas realistas e DIVERSAS (idade, classe, "
              "profissão, valores, posição) para simular a reação social ao contexto abaixo. " + pub +
              "REGRAS DE DIVERSIDADE (obrigatório): (1) ESPALHE os 'stance' por TODA a faixa −100 a +100 — "
              "vários bem negativos (−60 a −100), alguns neutros (−20 a +20) e vários bem positivos (+60 a +100); "
              "NUNCA repita o mesmo valor para todos. (2) Use AO MENOS 4 rótulos de 'grupo' diferentes. "
              "(3) 'influencia' variada de 1 a 5. Responda SOMENTE com JSON: "
              '{"personas":[{"nome":"Nome curto","perfil":"1 frase (quem é)","vies":"o que o inclina",'
              '"influencia":1-5,"grupo":"rótulo do segmento","stance":-100 a 100 (posição inicial sobre o tema)}]}'
              "\n\nCONTEXTO:\n" + (contexto or "")[:5000])
    out = []
    for _try in range(3):                                   # robustez: LLM/rate-limit intermitente → tenta de novo
        built = []
        try:
            raw = _chat_resiliente(_cen_llm(), [{"role": "user", "content": prompt}], max_tokens=4096) or ""
            arr = _cen_json_list(raw, "personas")
            for i, p in enumerate((arr or [])[:n]):
                if not isinstance(p, dict):
                    continue
                try:
                    st = int(float(p.get("stance", 0)))
                except Exception:
                    st = 0
                try:
                    inf = max(1, min(int(float(p.get("influencia", 2))), 5))
                except Exception:
                    inf = 2
                amb = ambientes[i % len(ambientes)] if ambientes else "rede_aberta"
                built.append({"id": "pa" + uuid.uuid4().hex[:8], "nome": _dna_txt(p.get("nome")) or f"Pessoa {i+1}",
                              "perfil": _dna_txt(p.get("perfil")), "vies": _dna_txt(p.get("vies")),
                              "influencia": inf, "grupo": _dna_txt(p.get("grupo")) or "geral",
                              "stance": max(-100, min(st, 100)), "ambiente": amb, "mem": []})
        except Exception as e:
            print("[cerne] cen_personas:", str(e)[:120])
        if len(built) >= 6:
            out = built; break
        if built:
            out = built
        time.sleep(2.0)                                    # backoff antes de retentar
    if len(out) < 6:                                       # fallback determinístico: criação nunca falha
        grupos = [str(g) for g in (atores or []) if g]
        if len(grupos) < 4:                                # garante variedade de segmentos mesmo sem atores do grafo
            grupos += ["apoiadores", "críticos", "indecisos", "especialistas", "afetados", "observadores"]
            grupos = list(dict.fromkeys(grupos))           # dedup preservando ordem
        faltam = n - len(out)
        for i in range(faltam):
            st = -90 + int(180 * i / max(1, faltam - 1))   # espalha -90..+90
            amb = ambientes[(len(out)) % len(ambientes)] if ambientes else "rede_aberta"
            out.append({"id": "pa" + uuid.uuid4().hex[:8], "nome": f"Pessoa {len(out) + 1}",
                        "perfil": "Membro do público (perfil sintético — modelo indisponível no momento)",
                        "vies": "reage conforme o segmento", "influencia": (i % 5) + 1,
                        "grupo": str(grupos[i % len(grupos)])[:40], "stance": max(-100, min(st, 100)),
                        "ambiente": amb, "mem": []})
    return out


def _cen_grupos(personas):
    """Clusters de opinião por stance + tamanho + média (para o painel)."""
    buckets = {"contra": [], "neutro": [], "a favor": []}
    for p in personas:
        s = p.get("stance", 0)
        buckets["contra" if s <= -34 else "a favor" if s >= 34 else "neutro"].append(s)
    return [{"rotulo": k, "tamanho": len(v), "stance": round(sum(v)/len(v)) if v else 0} for k, v in buckets.items()]


def _cen_rodada(c, evento=""):
    """Uma rodada de simulação social: todos os agentes reagem em UMA chamada (eficiente/soberano).
    Cada agente vê os posts recentes de MAIOR influência do SEU ambiente (dupla plataforma na Fase 2)."""
    personas = c.get("personas") or []
    tema = (c.get("grafo") or {}).get("resumo") or (c.get("semente") or "")[:400]
    ambientes = c.get("ambientes") or ["rede_aberta"]
    posts_ronda = []
    for amb in ambientes:
        grupo = [p for p in personas if p.get("ambiente") == amb] or (personas if len(ambientes) == 1 else [])
        if not grupo:
            continue
        # feed que os agentes veem: posts recentes de maior influência (memória cruzada = emergência)
        ult = (c.get("rodadas") or [])[-1] if c.get("rodadas") else None
        feed = ""
        if ult:
            vis = [x for x in ult.get("posts", []) if x.get("ambiente") == amb]
            vis = sorted(vis, key=lambda x: x.get("influencia", 1), reverse=True)[:6]
            feed = "\n".join(f"- {x.get('nome')}: {x.get('texto')}" for x in vis)
        elenco = "\n".join(f'{p["id"]} | {p["nome"]} ({p["grupo"]}, infl {p["influencia"]}, stance {p["stance"]}): {p["perfil"]}; viés: {p["vies"]}' for p in grupo)
        ev = f"\nACONTECEU AGORA (reaja a isto): {evento}\n" if evento else ""
        prompt = ("Simule UMA rodada num ambiente de " + _CEN_AMBIENTES.get(amb, amb) + " sobre o tema: \"" + str(tema)[:500] + "\"."
                  + ev + ("\nO que já foi dito (você pode concordar, rebater ou ser influenciado):\n" + feed if feed else "")
                  + "\n\nPersonas (responda por CADA uma, no tom dela, 1 post curto e autêntico em pt-BR):\n" + elenco
                  + '\n\nResponda SOMENTE com JSON: {"posts":[{"persona_id":"...","texto":"post curto","sentimento":-100 a 100}]}')
        try:
            raw = _chat_resiliente(_cen_llm(), [{"role": "user", "content": prompt}], max_tokens=4096) or ""
            arr = _cen_json_list(raw, "posts")
            byid = {p["id"]: p for p in grupo}
            for it in (arr or []):
                if not isinstance(it, dict):
                    continue
                pid = it.get("persona_id")
                pa = byid.get(pid)
                if not pa:
                    continue
                try:
                    sent = max(-100, min(int(float(it.get("sentimento", pa["stance"]))), 100))
                except Exception:
                    sent = pa["stance"]
                txt = _dna_txt(it.get("texto"))[:600]
                posts_ronda.append({"persona_id": pid, "nome": pa["nome"], "grupo": pa["grupo"],
                                    "ambiente": amb, "texto": txt, "sentimento": sent, "influencia": pa["influencia"]})
                # atualiza stance (blend) + memória do agente (Fase 2)
                pa["stance"] = max(-100, min(int(pa["stance"]*0.6 + sent*0.4), 100))
                pa["mem"] = (pa.get("mem") or [])[-2:] + [txt]
        except Exception as e:
            print("[cerne] cen_rodada:", str(e)[:120])
    sm = round(sum(x["sentimento"] for x in posts_ronda)/len(posts_ronda)) if posts_ronda else 0
    return {"n": len(c.get("rodadas") or []) + 1, "evento": evento or "", "posts": posts_ronda,
            "sentimento_medio": sm, "grupos": _cen_grupos(personas)}


_CEN_DOCX_TPL = r'''
import base64, json
from docx import Document
from docx.shared import Pt
S = json.loads(base64.b64decode("__SPEC__").decode("utf-8"))
doc = Document()
doc.add_heading(S.get("titulo", "Relatório de Cenário"), 0)
if S.get("subtitulo"):
    doc.add_paragraph(S["subtitulo"])
for sec in S.get("secoes", []):
    doc.add_heading(str(sec.get("t", "")), level=1)
    for par in (sec.get("p") or []):
        doc.add_paragraph(str(par))
    for b in (sec.get("bullets") or []):
        doc.add_paragraph(str(b), style="List Bullet")
doc.save(S["nome"]); print("OK arquivo:", S["nome"])
'''


def _cen_relatorio(c):
    """ReportAgent: sintetiza predição das rodadas + gera .docx no sandbox."""
    personas = c.get("personas") or []
    rodadas = c.get("rodadas") or []
    traj = " → ".join(str(r.get("sentimento_medio")) for r in rodadas) or "sem rodadas"
    grupos = _cen_grupos(personas)
    amostra = []
    for r in rodadas[-2:]:
        amostra += [f'[{p["nome"]}/{p["grupo"]}] {p["texto"]}' for p in r.get("posts", [])[:8]]
    grupos_txt = ", ".join("%s %d (média %d)" % (g["rotulo"], g["tamanho"], g["stance"]) for g in grupos)
    tema_txt = (c.get("grafo") or {}).get("resumo") or c.get("titulo")
    ctx = (f"Tema: {tema_txt}\n"
           f"Público: {c.get('publico') or '(geral)'}\nPersonas: {len(personas)} · Rodadas: {len(rodadas)}\n"
           f"Trajetória de sentimento (−100..100): {traj}\n"
           f"Grupos atuais: {grupos_txt}\n"
           f"Amostra de reações:\n" + "\n".join(amostra[:16]))
    prompt = ("Você é analista de cenários. Com base na simulação de enxame abaixo, escreva um RELATÓRIO DE PREDIÇÃO "
              "objetivo e acionável (não invente números). Responda SOMENTE com JSON: "
              '{"titulo":"...","subtitulo":"1 linha","secoes":[{"t":"Cenário mais provável","p":["..."]},'
              '{"t":"Reação por grupo","bullets":["..."]},{"t":"Riscos e pontos de atrito","bullets":["..."]},'
              '{"t":"Recomendações","bullets":["..."]}],"resumo_curto":"2-3 frases para exibir na tela",'
              '"confianca":"baixa|média|alta"}\n\nSIMULAÇÃO:\n' + ctx)
    j = _extract_json(_strip_think(_chat_resiliente(_cen_llm(), [{"role": "user", "content": prompt}], max_tokens=2600) or "")) or {}
    spec = {"titulo": _dna_txt(j.get("titulo")) or ("Relatório — " + (c.get("titulo") or "Cenário")),
            "subtitulo": _dna_txt(j.get("subtitulo")), "secoes": j.get("secoes") or [], "nome": "relatorio.docx"}
    arts = []
    try:
        import base64 as _b64
        code = _CEN_DOCX_TPL.replace("__SPEC__", _b64.b64encode(json.dumps(spec, ensure_ascii=False).encode()).decode())
        run = "cen" + uuid.uuid4().hex[:12]
        saida = _sandbox_exec(code, "python", run, timeout=40)
        if "OK arquivo:" in (saida or ""):
            arts = _agente_coletar_artefatos(run)
        _sb_reset(run)
    except Exception as e:
        print("[cerne] cen_relatorio docx:", str(e)[:120])
    return {"texto": _dna_txt(j.get("resumo_curto")) or spec["subtitulo"], "confianca": _dna_txt(j.get("confianca")) or "média",
            "secoes": spec["secoes"], "artefatos": arts, "gerado": time.time()}


def _cen_sched_disparar(c, gatilho):
    """Roda o cenário agendado: (opcional) checa fonte monitorada → injeta como evento → K rodadas → relatório."""
    ag = c.get("agendamento") or {}
    try:
        _ORG_CTX.set(c.get("org") or DEFAULT_ORG)
        evento = ""
        fonte = (ag.get("fonte_url") or "").strip()
        if fonte:
            try:
                txt = _html_to_text(_http_get(fonte, timeout=15).text)[:4000]
                h = hashlib.sha256(txt.encode("utf-8", "ignore")).hexdigest()
                if h == ag.get("_hash"):
                    return                                  # fonte não mudou → não gasta rodada
                ag["_hash"] = h
                evento = "Novidade da fonte monitorada: " + txt[:600]
            except Exception:
                pass
        nr = max(1, min(int(ag.get("rodadas") or 2), 4))
        for k in range(nr):
            c.setdefault("rodadas", []).append(_cen_rodada(c, evento if k == 0 else ""))
        if len(c["rodadas"]) > 30:
            c["rodadas"] = c["rodadas"][-30:]
        c["relatorio"] = _cen_relatorio(c)
        ag["ultima_exec"] = time.strftime("%Y-%m-%dT%H:%M:%S"); ag["ultima_status"] = "ok"
        _event("cenário agendado", f"{c.get('titulo')} · {gatilho} · +{nr} rodada(s)")
    except Exception as e:
        ag["ultima_status"] = "erro: " + str(e)[:120]
        _event("cenário agendado (erro)", f"{c.get('titulo')} · {str(e)[:80]}")
    _appstate_save(APPSTATE)


def _cen_scheduler_tick():
    """Chamado pelo _scheduler_tick (tick global de 20s). Dispara cenários com agendamento ativo."""
    now = time.time(); hoje = time.strftime("%Y-%m-%d"); hhmm = time.strftime("%H:%M")
    for c in list(APPSTATE.get("cenarios", [])):
        ag = c.get("agendamento") or {}
        if not ag.get("ativo"):
            continue
        try:
            if ag.get("modo") == "diario":
                if (ag.get("hora") or "") == hhmm and ag.get("_dia") != hoje:
                    ag["_dia"] = hoje; _cen_sched_disparar(c, "horário " + ag.get("hora", ""))
            else:
                cada = max(5, int(ag.get("cada_min") or 60))
                if now - float(ag.get("_ultima", 0) or 0) >= cada * 60:
                    ag["_ultima"] = now; _cen_sched_disparar(c, f"intervalo {cada}min")
        except Exception as e:
            print("[cerne] cen sched:", str(e)[:120])


class CenarioReq(BaseModel):
    titulo: str = ""
    semente: str = ""
    url: str = ""
    tipo: str = "livre"          # livre | marca (Fase 3)
    marca_id: str = ""
    publico: str = ""
    n_personas: int = 16
    ambientes: list = []         # ["rede_aberta","forum"] — dupla plataforma (Fase 2)


class CenRodarReq(BaseModel):
    rodadas: int = 2
    evento: str = ""             # injeção "visão de Deus" (Fase 1)


class CenChatReq(BaseModel):
    persona_id: str = ""         # id da persona OU "report" p/ o analista
    mensagem: str = ""


@app.get("/cenarios")
def cenarios_list():
    return {"cenarios": [_cen_pub(c) for c in sorted(_cenarios(), key=lambda x: x.get("criado", ""), reverse=True)]}


@app.get("/cenarios/{cid}")
def cenario_get(cid: str):
    c = _cenario_por_id(cid)
    if not c:
        raise HTTPException(status_code=404, detail="cenário não encontrado")
    return _cen_pub(c, full=True)


@app.post("/cenarios")
def cenario_criar(body: CenarioReq):
    _assert_admin_sessao()
    semente = (body.semente or "").strip()
    if body.url and not semente:
        try:
            semente = _html_to_text(_http_get(body.url, timeout=15).text)[:8000]
        except Exception:
            raise HTTPException(status_code=400, detail="não consegui ler a URL")
    publico = (body.publico or "").strip()
    marca = None
    if body.tipo == "marca" and body.marca_id:
        marca = _marca_por_id(body.marca_id)
        if not marca:
            raise HTTPException(status_code=404, detail="marca não encontrada")
        dna = marca.get("dna") or {}
        if not publico:
            publico = _dna_txt(dna.get("publico_alvo")) or _dna_txt(dna.get("resumo"))
        if not semente:
            raise HTTPException(status_code=400, detail="descreva a campanha/mensagem a testar no público")
        semente = (f"Marca: {_dna_txt(dna.get('nome_marca'))} — {_dna_txt(dna.get('resumo'))}. "
                   f"Tom: {_dna_txt(dna.get('tom_de_voz'))}. Testar a reação do público a: " + semente)
    if len(semente) < 20:
        raise HTTPException(status_code=400, detail="cole um texto-semente (notícia, campanha, mensagem) com mais contexto")
    ambientes = [a for a in (body.ambientes or []) if a in _CEN_AMBIENTES] or ["rede_aberta"]
    grafo = _cen_grafo(semente)
    ctx = (grafo.get("resumo") or "") + "\nTemas: " + ", ".join(grafo.get("temas") or []) + "\n" + semente[:2000]
    personas = _cen_personas(ctx, body.n_personas, publico, ambientes, atores=grafo.get("atores"))
    if not personas:
        raise HTTPException(status_code=502, detail="o modelo não conseguiu gerar as personas — tente de novo ou configure uma LLM paga")
    cid = "cn" + uuid.uuid4().hex[:12]
    c = {"id": cid, "org": _tenant(), "criado": time.strftime("%Y-%m-%dT%H:%M:%S"), "titulo": (body.titulo or grafo.get("resumo") or "Cenário")[:120],
         "tipo": body.tipo or "livre", "marca_id": body.marca_id or "", "publico": publico, "semente": semente,
         "ambientes": ambientes, "grafo": grafo, "personas": personas, "rodadas": [], "relatorio": {}, "status": "pronto"}
    APPSTATE.setdefault("cenarios", []).append(c)
    _appstate_save(APPSTATE)
    _cen_graph_write(cid, grafo)
    _event("cenário criado", f"{c['titulo']} · {len(personas)} personas", actor=_actor())
    return _cen_pub(c, full=True)


@app.post("/cenarios/{cid}/rodar")
def cenario_rodar(cid: str, body: CenRodarReq):
    _assert_admin_sessao()
    c = _cenario_por_id(cid)
    if not c:
        raise HTTPException(status_code=404, detail="cenário não encontrado")
    nr = max(1, min(int(body.rodadas or 1), 6))
    for k in range(nr):
        ev = body.evento if k == 0 else ""              # evento injetado entra na 1ª rodada desta leva
        c.setdefault("rodadas", []).append(_cen_rodada(c, ev))
    if len(c["rodadas"]) > 30:
        c["rodadas"] = c["rodadas"][-30:]
    _appstate_save(APPSTATE)
    _event("cenário simulado", f"{c['titulo']} · +{nr} rodada(s)" + (" · evento" if body.evento else ""), actor=_actor())
    return _cen_pub(c, full=True)


@app.post("/cenarios/{cid}/relatorio")
def cenario_relatorio(cid: str, body: dict = None):
    _assert_admin_sessao()
    c = _cenario_por_id(cid)
    if not c:
        raise HTTPException(status_code=404, detail="cenário não encontrado")
    if not (c.get("rodadas")):
        raise HTTPException(status_code=400, detail="rode ao menos 1 rodada antes de gerar o relatório")
    c["relatorio"] = _cen_relatorio(c)
    _appstate_save(APPSTATE)
    _event("relatório de cenário", c["titulo"], actor=_actor())
    return c["relatorio"]


@app.post("/cenarios/{cid}/chat")
def cenario_chat(cid: str, body: CenChatReq):
    _assert_admin_sessao()
    c = _cenario_por_id(cid)
    if not c:
        raise HTTPException(status_code=404, detail="cenário não encontrado")
    msg = (body.mensagem or "").strip()
    if not msg:
        raise HTTPException(status_code=400, detail="escreva uma mensagem")
    tema = (c.get("grafo") or {}).get("resumo") or c.get("titulo")
    if body.persona_id == "report":
        rel = (c.get("relatorio") or {}).get("texto") or "(sem relatório ainda)"
        traj = " → ".join(str(r.get("sentimento_medio")) for r in (c.get("rodadas") or []))
        sysp = (f"Você é o analista do cenário '{c.get('titulo')}'. Tema: {tema}. Trajetória de sentimento: {traj}. "
                f"Síntese: {rel}. Responda com base na simulação, de forma objetiva.")
    else:
        pa = next((p for p in (c.get("personas") or []) if p.get("id") == body.persona_id), None)
        if not pa:
            raise HTTPException(status_code=404, detail="persona não encontrada")
        mem = " | ".join(pa.get("mem") or [])
        sysp = (f"Você É {pa['nome']} ({pa['grupo']}): {pa['perfil']}. Seu viés: {pa['vies']}. "
                f"Sua posição atual (−100 contra a +100 a favor): {pa['stance']}. "
                f"O tema em discussão: {tema}. O que você já disse: {mem}. "
                f"Responda em 1ª pessoa, no seu tom, curto e coerente com sua posição. Não saia do personagem.")
    resp = _strip_think(_chat_resiliente(_cen_llm(), [{"role": "system", "content": sysp},
                                                      {"role": "user", "content": msg}], max_tokens=500) or "")
    return {"resposta": resp.strip()}


@app.delete("/cenarios/{cid}")
def cenario_del(cid: str):
    _assert_admin_sessao()
    APPSTATE["cenarios"] = [c for c in APPSTATE.get("cenarios", []) if not (c.get("id") == cid and c.get("org") == _tenant())]
    _appstate_save(APPSTATE)
    return {"status": "removido", "id": cid}


class CenAgendaReq(BaseModel):
    ativo: bool = True
    modo: str = "intervalo"       # intervalo | diario
    cada_min: int = 60            # intervalo em minutos (mín. 5)
    hora: str = ""               # HH:MM (modo diario)
    rodadas: int = 2
    fonte_url: str = ""          # se informado, só dispara quando a página mudar (predição contínua sobre notícia viva)


@app.post("/cenarios/{cid}/agendamento")
def cenario_agendar(cid: str, body: CenAgendaReq):
    _assert_admin_sessao()
    c = _cenario_por_id(cid)
    if not c:
        raise HTTPException(status_code=404, detail="cenário não encontrado")
    prev = c.get("agendamento") or {}
    ag = {"ativo": bool(body.ativo), "modo": ("diario" if body.modo == "diario" else "intervalo"),
          "cada_min": max(5, int(body.cada_min or 60)), "hora": (body.hora or "").strip(),
          "rodadas": max(1, min(int(body.rodadas or 2), 4)), "fonte_url": (body.fonte_url or "").strip()}
    for k in ("_ultima", "_dia", "_hash", "ultima_exec", "ultima_status"):   # preserva estado interno
        if k in prev:
            ag[k] = prev[k]
    c["agendamento"] = ag
    _appstate_save(APPSTATE)
    _event("cenário agendado (config)", f"{c.get('titulo')} · {ag['modo']}", actor=_actor())
    return _cen_agenda_pub(ag)


@app.delete("/cenarios/{cid}/agendamento")
def cenario_agendar_off(cid: str):
    _assert_admin_sessao()
    c = _cenario_por_id(cid)
    if not c:
        raise HTTPException(status_code=404, detail="cenário não encontrado")
    c.pop("agendamento", None)
    _appstate_save(APPSTATE)
    return {"status": "removido"}


@app.post("/cenarios/{cid}/agendamento/rodar-agora")
def cenario_agendar_rodar(cid: str):
    _assert_admin_sessao()
    c = _cenario_por_id(cid)
    if not c:
        raise HTTPException(status_code=404, detail="cenário não encontrado")
    if not c.get("agendamento"):
        c["agendamento"] = {"ativo": False, "modo": "intervalo", "cada_min": 60, "rodadas": 2}
    _cen_sched_disparar(c, "manual")
    return _cen_pub(c, full=True)


