_DESIGN_SYS = ("Você é engenheiro de design sênior. Produz UM arquivo HTML COMPLETO e AUTOSSUFICIENTE (um só arquivo: "
               "todo o CSS em <style> e o JS em <script>; SEM frameworks nem imagens externas — pode usar Google Fonts "
               "via <link> e ícones em SVG inline). O resultado deve ser MODERNO, responsivo, com hierarquia tipográfica "
               "forte, espaçamento generoso, micro-detalhes de qualidade e conteúdo REAL (nada de lorem ipsum). "
               "Responda SOMENTE com o HTML, começando em <!doctype html>.")


def _design_sistema(dna):
    if not dna:
        return "Sem marca definida: use um design moderno, limpo e profissional, com paleta de bom contraste a seu critério."
    return ("DESIGN SYSTEM DA MARCA (siga à risca):\n"
            f"- Marca: {_dna_txt(dna.get('nome_marca'))}\n- Tom/estilo: {_dna_txt(dna.get('tom_de_voz'))}\n"
            f"- Paleta (use EXATAMENTE estas cores): {', '.join(dna.get('paleta') or []) or 'a seu critério'}\n"
            f"- Tipografia (font-family com fallback de sistema): {', '.join(dna.get('fontes') or []) or 'system-ui'}\n"
            f"- Público: {_dna_txt(dna.get('publico_alvo'))}\n- Produtos: {', '.join(_dna_lista(dna.get('produtos')))}")


def _design_sistemas_custom():
    return [x for x in APPSTATE.get("design_sistemas", []) if x.get("org") == _tenant()]


def _design_sistema_contrato(s):
    return (f"\nDESIGN SYSTEM — replique com alta fidelidade a identidade visual de {s.get('nome', '')} ({s.get('categoria', '')}): "
            f"paleta (use EXATAMENTE estas cores): {', '.join(s.get('paleta') or [])}; "
            f"tipografia (Google Fonts com fallback de sistema): {', '.join(s.get('fontes') or [])}; "
            f"estética: {s.get('vibe', '')}.")


def _design_estilo_txt(estilo):
    """Contrato do estilo/design-system escolhido (abstrato, marca famosa OU customizado) injetado no prompt."""
    if not estilo:
        return ""
    if estilo in _DESIGN_ESTILOS:
        g = (_DESIGN_ESTILOS[estilo] or {}).get("guia")
        return f"\nESTILO VISUAL (aplique): {g}" if g else ""
    s = _DESIGN_SYSTEMS.get(estilo) or next((x for x in _design_sistemas_custom() if x.get("id") == estilo), None)
    return _design_sistema_contrato(s) if s else ""


def _design_cands():
    """Modelos de texto em ordem de preferência p/ o Design: pagos configurados → local soberano."""
    cfg = APPSTATE.get("llm_pagas") or {}
    return [a for a in ("ext-claude", "ext-openai", "ext-gemini-pro")
            if (cfg.get(a) or {}).get("api_key") and (cfg.get(a) or {}).get("ativo", True)] + ["chat"]


def _design_capa(prompt, dna):
    """Gera uma imagem de capa/hero por IA (gancho híbrido) e a serve numa URL pública. Retorna (url, erro)."""
    pal = ", ".join((dna or {}).get("paleta") or []) if dna else ""
    ip = ("Wide cinematic hero/cover image for: " + str(prompt)[:400] + ". " + (f"Brand palette: {pal}. " if pal else "") +
          "High-end, professional, editorial, photorealistic, no text, no letters, no watermark, calm areas for text overlay.")
    ib, err = _marca_imagem_hibrida(ip, "1536x1024")
    if not ib:
        return None, err
    nome = "cap" + uuid.uuid4().hex[:14] + ".png"
    open(os.path.join(_marca_lib_sub("design_assets"), nome), "wb").write(ib)
    return f"{_OFFICE_BASE}/design/asset/{nome}", None


def _design_html(resp):
    html = _strip_think(resp or "")
    mo = re.search(r"(?is)<!doctype html.*?</html>", html) or re.search(r"(?is)<html.*?</html>", html)
    if mo:
        html = mo.group(0)
    return re.sub(r"^```[a-z]*\n?|\n?```$", "", html.strip())


def _design_gerar(prompt, tipo, dna, estilo="", html_atual=None, instrucao=None, capa_url=None):
    tp = _DESIGN_TIPOS.get(tipo) or _DESIGN_TIPOS["landing"]
    ds = _design_sistema(dna)
    ds += _design_estilo_txt(estilo)
    if capa_url:
        ds += (f"\nIMAGEM DE CAPA: use EXATAMENTE este src como hero (em <img> ou background-image cobrindo a área), "
               f"com bom scrim/legibilidade do texto por cima; NÃO invente outras imagens externas. SRC: {capa_url}")
    if html_atual and instrucao:
        user = ("Aqui está o HTML atual do design. Aplique a MUDANÇA pedida e devolva o HTML COMPLETO atualizado.\n\n"
                "MUDANÇA: " + instrucao + "\n\n" + ds + "\n\nHTML ATUAL:\n" + html_atual[:60000])
    else:
        user = f"Crie um(a) {tp['nome']}. Especificação: {tp['guia']}\n\nBRIEFING DO USUÁRIO: {prompt}\n\n{ds}"
    msgs = [{"role": "system", "content": _DESIGN_SYS}, {"role": "user", "content": user}]
    resp = ""
    for mdl in _design_cands():                           # tenta os pagos em ordem e cai no local soberano
        try:
            resp = _chat_completo(mdl, msgs, max_tokens=6000, conts=4) or ""
            if "<" in resp:
                break
        except Exception as e:
            print("[cerne] design", mdl, "falhou:", str(e)[:100])
    return _design_html(resp)


def _designs():
    return [d for d in APPSTATE.get("designs", []) if d.get("org") == _tenant()]


def _design_por_id(did):
    return next((d for d in _designs() if d.get("id") == did), None)


def _design_pub(d, full=False):
    base = {"id": d["id"], "titulo": d.get("titulo") or "(sem título)", "tipo": d.get("tipo"),
            "tipo_nome": (_DESIGN_TIPOS.get(d.get("tipo")) or {}).get("nome", d.get("tipo")),
            "marca_id": d.get("marca_id") or "", "estilo": d.get("estilo") or "",
            "criado": d.get("criado"), "iteracoes": len(d.get("historico") or [])}
    if full:
        base.update({"html": d.get("html") or "", "prompt": d.get("prompt") or "", "historico": d.get("historico") or []})
    return base


class DesignReq(BaseModel):
    titulo: str = ""
    prompt: str = ""
    tipo: str = "landing"
    marca_id: str = ""
    estilo: str = ""
    capa_ia: bool = False        # gera uma imagem de capa/hero por IA e embute no design


class DesignIterarReq(BaseModel):
    mensagem: str = ""


@app.get("/design")
def design_list():
    return {"designs": [_design_pub(d) for d in sorted(_designs(), key=lambda x: x.get("criado", ""), reverse=True)],
            "tipos": [{"id": k, "nome": v["nome"]} for k, v in _DESIGN_TIPOS.items()],
            "estilos": [{"id": k, "nome": v["nome"], "paleta": v.get("paleta", []), "fontes": v.get("fontes", []), "dark": v.get("dark", False)} for k, v in _DESIGN_ESTILOS.items()],
            "sistemas": [{"id": k, "nome": v["nome"], "categoria": v.get("categoria", ""), "paleta": v.get("paleta", []), "fontes": v.get("fontes", []), "custom": False} for k, v in _DESIGN_SYSTEMS.items()]
                       + [{"id": x["id"], "nome": x["nome"], "categoria": x.get("categoria", "Meus"), "paleta": x.get("paleta", []), "fontes": x.get("fontes", []), "custom": True} for x in _design_sistemas_custom()],
            "templates": _DESIGN_TEMPLATES}


class SistemaReq(BaseModel):
    nome: str = ""
    blurb: str = ""
    notas: str = ""
    url: str = ""              # site (extrai paleta+fontes automaticamente)
    paleta: list = []
    fontes: list = []


@app.post("/design/sistema")
def design_sistema_criar(body: SistemaReq):
    """Cria um design system PRÓPRIO (nome + blurb + notas + URL do site p/ extrair paleta/fontes)."""
    _assert_admin_sessao()
    nome = (body.nome or "").strip()
    if not nome:
        raise HTTPException(status_code=400, detail="informe o nome do design system")
    paleta = [c for c in (body.paleta or []) if isinstance(c, str) and c.strip()]
    fontes = [f for f in (body.fontes or []) if isinstance(f, str) and f.strip()]
    if (body.url or "").strip() and (not paleta or not fontes):
        dna = _marca_extrair_dna(body.url)
        if not dna.get("erro"):
            paleta = paleta or (dna.get("paleta") or [])
            fontes = fontes or (dna.get("fontes") or [])
    vibe = " · ".join(x.strip() for x in [body.blurb, body.notas] if (x or "").strip())[:600] or "identidade visual própria"
    item = {"id": "sy" + uuid.uuid4().hex[:10], "org": _tenant(), "nome": nome[:60], "categoria": "Meus",
            "paleta": paleta[:6] or ["#111827", "#6C8CFF", "#FFFFFF"], "fontes": fontes[:3] or ["Inter", "system-ui"],
            "vibe": vibe, "criado": time.strftime("%Y-%m-%dT%H:%M:%S")}
    APPSTATE.setdefault("design_sistemas", []).append(item)
    _appstate_save(APPSTATE)
    _event("design system criado", nome, actor=_actor())
    return item


@app.delete("/design/sistema/{sid}")
def design_sistema_del(sid: str):
    _assert_admin_sessao()
    APPSTATE["design_sistemas"] = [x for x in APPSTATE.get("design_sistemas", []) if not (x.get("id") == sid and x.get("org") == _tenant())]
    _appstate_save(APPSTATE)
    return {"ok": True}


@app.get("/design/asset/{nome}")
def design_asset(nome: str):
    """Imagem de capa gerada por IA — PÚBLICA (o preview em iframe/blob e o HTML exportado precisam carregá-la)."""
    safe = os.path.basename(nome or "")
    base = os.path.realpath(os.path.join(_MARCA_LIB_DIR, "design_assets"))
    p = os.path.realpath(os.path.join(base, safe))
    if not safe or not p.startswith(base + os.sep) or not os.path.isfile(p):
        raise HTTPException(status_code=404, detail="imagem não encontrada")
    return FileResponse(p, media_type=_ART_MIME.get(os.path.splitext(safe)[1].lower(), "image/png"))


@app.get("/design/{did}")
def design_get(did: str):
    d = _design_por_id(did)
    if not d:
        raise HTTPException(status_code=404, detail="design não encontrado")
    return _design_pub(d, full=True)


@app.post("/design")
def design_criar(body: DesignReq):
    _assert_admin_sessao()
    if len((body.prompt or "").strip()) < 6:
        raise HTTPException(status_code=400, detail="descreva o que você quer criar")
    dna = None
    if body.marca_id:
        mm = _marca_por_id(body.marca_id)
        if mm:
            dna = _marca_pub(mm)["dna"]
    capa_url = None; aviso = ""
    if body.capa_ia:
        capa_url, cerr = _design_capa(body.prompt, dna)
        if not capa_url:
            aviso = "capa por IA indisponível (" + (cerr or "sem provedor de imagem") + ") — gerei sem imagem."
    try:
        html = _design_gerar(body.prompt, body.tipo, dna, estilo=body.estilo, capa_url=capa_url)
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"falha ao gerar: {str(e)[:160]}")
    if "<" not in html:
        raise HTTPException(status_code=502, detail="o modelo não retornou HTML — tente de novo")
    did = "dz" + uuid.uuid4().hex[:12]
    d = {"id": did, "org": _tenant(), "criado": time.strftime("%Y-%m-%dT%H:%M:%S"),
         "titulo": (body.titulo or body.prompt[:60]), "tipo": body.tipo, "marca_id": body.marca_id or "",
         "estilo": body.estilo or "", "prompt": body.prompt, "html": html[:400000], "capa_url": capa_url or "",
         "historico": [{"papel": "user", "texto": body.prompt}]}
    APPSTATE.setdefault("designs", []).append(d)
    _appstate_save(APPSTATE)
    _event("design gerado", f"{(_DESIGN_TIPOS.get(body.tipo) or {}).get('nome', body.tipo)} · {str(d['titulo'])[:40]}", actor=_actor())
    return {**_design_pub(d, full=True), "aviso": aviso}


@app.post("/design/{did}/iterar")
def design_iterar(did: str, body: DesignIterarReq):
    _assert_admin_sessao()
    d = _design_por_id(did)
    if not d:
        raise HTTPException(status_code=404, detail="design não encontrado")
    msg = (body.mensagem or "").strip()
    if not msg:
        raise HTTPException(status_code=400, detail="diga o que mudar")
    dna = None
    if d.get("marca_id"):
        mm = _marca_por_id(d["marca_id"])
        if mm:
            dna = _marca_pub(mm)["dna"]
    try:
        html = _design_gerar(d.get("prompt"), d.get("tipo"), dna, estilo=d.get("estilo", ""), html_atual=d.get("html"), instrucao=msg, capa_url=d.get("capa_url") or None)
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"falha ao iterar: {str(e)[:160]}")
    if "<" in html:
        d["html"] = html[:400000]
    d.setdefault("historico", []).append({"papel": "user", "texto": msg})
    _appstate_save(APPSTATE)
    return _design_pub(d, full=True)


