_DESIGN_PPTX_TPL = r'''
import base64, json
from pptx import Presentation
S = json.loads(base64.b64decode("__SPEC__").decode("utf-8"))
prs = Presentation()
from pptx.util import Inches
prs.slide_width = Inches(13.333); prs.slide_height = Inches(7.5)
c = prs.slides.add_slide(prs.slide_layouts[0])
c.shapes.title.text = S.get("titulo", "Apresentação")
try:
    c.placeholders[1].text = S.get("subtitulo", "")
except Exception:
    pass
for sl in S.get("slides", []):
    s = prs.slides.add_slide(prs.slide_layouts[1])
    s.shapes.title.text = str(sl.get("titulo", ""))
    tf = s.placeholders[1].text_frame; tf.clear()
    bl = sl.get("bullets") or []
    for i, b in enumerate(bl):
        p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
        p.text = str(b)
prs.save(S["nome"]); print("OK arquivo:", S["nome"])
'''


@app.post("/design/{did}/pptx")
def design_pptx(did: str):
    """Converte o design num deck editável (.pptx) — resume o conteúdo em slides via LLM e renderiza no sandbox."""
    _assert_admin_sessao()
    d = _design_por_id(did)
    if not d:
        raise HTTPException(status_code=404, detail="design não encontrado")
    txt = _html_to_text(d.get("html") or "")[:6000]
    prompt = ("Converta o conteúdo abaixo num deck de slides objetivo (6 a 10 slides, bullets curtos). "
              'Responda SOMENTE JSON: {"titulo":"...","subtitulo":"...","slides":[{"titulo":"...","bullets":["...","..."]}]}'
              "\n\nCONTEÚDO:\n" + txt)
    raw = ""
    for mdl in _design_cands():
        try:
            raw = _chat_completo(mdl, [{"role": "user", "content": prompt}], max_tokens=2500, conts=2) or ""
            if raw.strip():
                break
        except Exception:
            continue
    j = _extract_json(_strip_think(raw)) or {}
    spec = {"titulo": _dna_txt(j.get("titulo")) or (d.get("titulo") or "Apresentação"),
            "subtitulo": _dna_txt(j.get("subtitulo")),
            "slides": [x for x in (j.get("slides") or []) if isinstance(x, dict)][:12], "nome": "design.pptx"}
    if not spec["slides"]:
        raise HTTPException(status_code=502, detail="não consegui montar os slides — tente de novo")
    import base64 as _b64
    code = _DESIGN_PPTX_TPL.replace("__SPEC__", _b64.b64encode(json.dumps(spec, ensure_ascii=False).encode()).decode())
    run = "dp" + uuid.uuid4().hex[:12]
    saida = _sandbox_exec(code, "python", run, timeout=40)
    if "OK arquivo:" not in (saida or ""):
        _sb_reset(run)
        raise HTTPException(status_code=500, detail=f"falha ao gerar o .pptx: {(saida or '')[:180]}")
    arts = _agente_coletar_artefatos(run); _sb_reset(run)
    _event("design → pptx", d.get("titulo") or "", actor=_actor())
    return {"artefatos": arts}


