# ---- Runtime de Agentes: painel de gestão/monitoramento do NanoClaw (que não tem UI própria) ----
# O NanoClaw guarda o estado num SQLite (v2.db). O Cerne o monta somente-leitura e vira a tela de
# controle: agentes ativos, canais, tarefas agendadas e aprovações pendentes.
NANOCLAW_DB = os.getenv("NANOCLAW_DB", "/data/nanoclaw/v2.db")


def _runtime_con():
    """Abre um SNAPSHOT do v2.db. O NanoClaw usa WAL; abrir o arquivo original
    somente-leitura (mount :ro) falha ao criar o -shm. Copiamos p/ tmp e lemos lá."""
    import sqlite3
    import shutil
    if not os.path.exists(NANOCLAW_DB):
        return None
    snap = "/tmp/cerne_runtime_snap.db"
    try:
        shutil.copy(NANOCLAW_DB, snap)
        for ext in ("-wal", "-shm"):                       # inclui WAL se existir, p/ snapshot consistente
            if os.path.exists(NANOCLAW_DB + ext):
                shutil.copy(NANOCLAW_DB + ext, snap + ext)
    except Exception:
        return None
    con = sqlite3.connect(snap, timeout=3)
    con.row_factory = sqlite3.Row
    return con


@app.get("/runtime")
def runtime_status():
    _assert_admin_sessao()                                  # tela de gestão = só admin
    base = {"conectado": False, "db": NANOCLAW_DB, "gateway": "http://host.docker.internal:4000",
            "modelo": "agent (Ollama local, soberano)"}
    con = _runtime_con()
    if not con:
        return dict(base, aviso="runtime do NanoClaw ainda não inicializado (nenhum v2.db) — conclua o bring-up no servidor")
    try:
        tabelas = {r["name"] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}

        def q(sql, cols):
            try:
                return [{c: r[c] for c in cols} for r in con.execute(sql).fetchall()]
            except Exception:
                return []

        def n(tab):
            try:
                return con.execute(f"SELECT COUNT(*) c FROM {tab}").fetchone()["c"] if tab in tabelas else 0
            except Exception:
                return 0
        grupos = q("SELECT id,name,folder,agent_provider,created_at FROM agent_groups ORDER BY created_at DESC LIMIT 50",
                   ["id", "name", "folder", "agent_provider", "created_at"]) if "agent_groups" in tabelas else []
        canais = q("SELECT channel_type,platform_id,name,is_group FROM messaging_groups LIMIT 50",
                   ["channel_type", "platform_id", "name", "is_group"]) if "messaging_groups" in tabelas else []
        return dict(base, conectado=True, agentes=grupos, canais=canais,
                    contadores={"agentes": len(grupos), "canais": len(canais),
                                "agendadas": n("scheduled_tasks"), "aprovacoes_pendentes": n("pending_approvals")})
    finally:
        con.close()


