# ---- geração assistida: documento (Markdown) ou site (HTML) a partir do acervo ----
class PlanoReq(BaseModel):
    mensagem: str
    tipo: str = "documento"
    colecoes: list | None = None


@app.post("/plano")
def plano(body: PlanoReq):
    """Planejador soberano (modo agente: plano -> aprovação -> execução). Devolve um plano curto ANTES de gastar o modelo grande."""
    _quota_consumir()
    tipo = "site" if (body.tipo or "") == "site" else "documento"
    sys = ("Você é um planejador conciso. Dado o pedido de criação de um " + tipo + ", responda SOMENTE com JSON válido no "
           "formato {\"titulo\": \"...\", \"passos\": [\"...\", \"...\"], \"resumo\": \"uma frase\"}. De 3 a 6 passos; cada item de "
           "\"passos\" é uma STRING (uma frase começando por um verbo), NUNCA um objeto, e ESPECÍFICO ao pedido (nada genérico). Em português.")
    msgs = [{"role": "system", "content": sys}, {"role": "user", "content": (body.mensagem or "")[:1500]}]
    raw = re.sub(r"(?s)<think>.*?</think>", "", (_chat_completo("chat", msgs, max_tokens=500, conts=1) or "")).strip()
    data = {}
    mm = re.search(r"\{.*\}", raw, re.S)
    if mm:
        try:
            data = json.loads(mm.group(0))
        except Exception:
            data = {}
    def _ptxt(p):
        if isinstance(p, dict):
            vb = str(p.get("verbo") or "").strip()
            for k in ("descricao", "passo", "acao", "texto", "step", "description", "titulo", "title"):
                if p.get(k):
                    v = str(p[k]).strip()
                    return (vb.capitalize() + " " + v).strip() if (vb and not v.lower().startswith(vb.lower())) else v
            return " ".join(str(v) for v in p.values() if isinstance(v, (str, int, float))).strip()[:160]
        return str(p).strip()
    passos = [x for x in (_ptxt(p) for p in (data.get("passos") or [])) if x][:6]
    if len(passos) < 2:  # fallback determinístico: o card de aprovação sempre aparece
        passos = (["Definir as seções da página (topo/hero, benefícios, prova social e chamada para ação)",
                   "Escrever o conteúdo com base no seu pedido e nos documentos do projeto",
                   "Montar o HTML responsivo e estilizado, num único arquivo",
                   "Revisar e abrir a prévia ao lado para você ajustar"]
                  if tipo == "site" else
                  ["Reunir o contexto do pedido e dos documentos do projeto",
                   "Estruturar o documento em seções (introdução, desenvolvimento, conclusão)",
                   "Redigir o conteúdo completo em português, no tom adequado",
                   "Revisar, formatar e abrir a prévia ao lado para você ajustar"])
    titulo = (str(data.get("titulo") or "").strip() or ("Plano do " + tipo))[:120]
    resumo = str(data.get("resumo") or "").strip()[:240]
    prov = None
    try:
        prov = _best_provider_for(body.mensagem)
    except Exception:
        prov = None
    externo = bool(prov) and str(prov).startswith("ext-")
    prov_nome = (str(prov).replace("ext-", "").replace("-", " ").title()) if externo else ""
    return {"titulo": titulo, "passos": passos, "resumo": resumo, "externo": externo, "provider": prov_nome}


class GerarReq(BaseModel):
    tipo: str = "documento"      # documento | site
    instrucao: str
    colecao: str = COLLECTION
    colecoes: list | None = None


@app.post("/gerar")
def gerar(body: GerarReq):
    _quota_consumir()
    hits = _search_multi(body.instrucao, 5, _colls_of(body))
    ctx = "\n\n---\n\n".join(h.payload.get("text", "") for h in hits)
    if body.tipo == "site":
        sys = ("Você gera UMA página HTML completa e autocontida (com <style> inline), profissional, moderna e em português, "
               "que ATENDA AO PEDIDO do usuário. Use o CONTEXTO do acervo apenas como referência quando for pertinente ao pedido "
               "(NÃO copie o contexto se ele não tiver relação com o pedido). Responda SOMENTE com o HTML começando por <!doctype html>, sem comentários e sem cercas de código.")
    else:
        sys = ("Você gera um DOCUMENTO em Markdown bem estruturado (título com #, seções com ##, listas e tabelas quando útil), "
               "profissional e em português, que ATENDA AO PEDIDO do usuário. Use o CONTEXTO do acervo apenas como referência quando for pertinente "
               "(NÃO copie o contexto se ele não tiver relação com o pedido). Responda SOMENTE com o Markdown, sem explicações.")
    org = _org()
    prov = _best_provider(org) if org.get("soberania") == "hibrido" else None   # híbrido: modelo forte escreve o entregável
    tokens = None
    try:
        if prov:
            # mascara só o PEDIDO (o ctx do acervo já vem mascarado da ingestão) -> provedor forte -> de-mascara
            mq, mp = mask_reversible(body.instrucao)
            raw = _chat_completo(prov, [{"role": "system", "content": sys},
                                        {"role": "user", "content": f"Contexto:\n{ctx}\n\nPedido: {mq}"}],
                                 max_tokens=8192, conts=2)
            out = demask(_strip_think(raw or ""), mp)
            out, _ = guard_output(out)
        else:
            out, tokens = _gen_call([{"role": "system", "content": sys},
                                     {"role": "user", "content": f"Contexto:\n{ctx}\n\nPedido: {body.instrucao}"}],
                                    max_tokens=4096)
            out = _strip_think(out or "")
    except Exception as e:
        try:                                            # provedor externo falhou (429/etc.) -> cai p/ local soberano
            out, tokens = _gen_call([{"role": "system", "content": sys},
                                     {"role": "user", "content": f"Contexto:\n{ctx}\n\nPedido: {body.instrucao}"}],
                                    max_tokens=4096)
            out = _strip_think(out or "")
        except Exception as e2:
            return JSONResponse(status_code=502, content={"error": "falha na geração", "detail": str(e2)[:300]})
    out = re.sub(r"^```[a-zA-Z]*\n?", "", out.strip())
    out = re.sub(r"\n?```$", "", out).strip()
    _event("geração", f"{body.tipo} · {body.instrucao[:50]}")
    return {"tipo": body.tipo, "conteudo": out, "tokens": tokens, "fontes": sorted({h.payload.get("source", "?") for h in hits})}


# ---- geração/ajuste de CÓDIGO com preview (código novo ou correção antes/depois) ----
def _code_blocks(text):
    return re.findall(r"```[a-zA-Z0-9_+.\-]*\n?(.*?)```", text or "", re.S)


def _code_field(raw, name):
    m = re.search(name + r"\s*:\s*(.+?)(?:\n[A-ZÇÃÉ_]{4,}\s*:|\n```|\Z)", raw or "", re.S)
    return m.group(1).strip() if m else ""


class CodigoReq(BaseModel):
    instrucao: str
    colecao: str = COLLECTION
    colecoes: list | None = None


@app.post("/codigo")
def codigo(body: CodigoReq):
    _quota_consumir()
    instr = body.instrucao or ""
    colls = _colls_of(body)
    hits = _search_rich(instr, colls, "chat", k=6) if colls else []
    ctx = _compress("\n\n---\n\n".join(h.payload.get("text", "") for h in hits), instr, max_sent=14) if hits else ""
    tem_codigo = bool(re.search(r"```|(^|\n)\s*(def |class |import |from \s*\w+\s+import|function |const |let |var |public |#include)", instr)) or len(instr) > 500
    ajuste = tem_codigo and bool(re.search(r"corrig|ajust|melhor|refator|otimiz|conserta|debug|\berro\b|\bbug\b|revis|n[aã]o funciona|falha", instr, re.I))
    org = _org()
    prov = _best_provider(org) if org["soberania"] == "hibrido" else None      # híbrido: melhor modelo escreve o código
    if ajuste:
        sysp = ("Você é um revisor de código sênior. Analise o código do usuário e proponha a correção/melhoria mais importante. "
                "Responda EXATAMENTE neste formato (em português), sem texto fora dele:\n"
                "PROBLEMA: <uma frase sobre o erro encontrado ou a melhoria necessária>\n"
                "ANTES:\n```python\n<apenas o trecho original problemático>\n```\n"
                "DEPOIS:\n```python\n<o mesmo trecho já corrigido>\n```\n"
                "EXPLICACAO: <por que a mudança resolve, curto>\n"
                "COMPLETO:\n```python\n<o código completo já corrigido>\n```\n"
                "(troque 'python' pela linguagem real do código)")
    else:
        sysp = ("Você é um engenheiro de software sênior. Gere código REAL, completo e executável que atenda ao pedido. "
                "HONRE EXATAMENTE as bibliotecas/ferramentas citadas pelo usuário (ex.: se pedirem Playwright, use Playwright — nunca troque por Selenium). "
                "Se o pedido exigir algo específico (ex.: evitar detecção), IMPLEMENTE de fato no código — não apenas mencione. "
                "A EXPLICACAO deve descrever SOMENTE o que o código realmente contém: NUNCA cite bibliotecas, ferramentas, etapas ou ambientes "
                "(ex.: pyenv, venv, docker) que não apareçam no código. Não invente recursos. "
                "Comente os pontos-chave. Responda EXATAMENTE neste formato (em português), sem texto fora dele:\n"
                "EXPLICACAO: <2 a 4 frases: o que faz e como executar — só o que está no código>\n"
                "CODIGO:\n```python\n<código completo>\n```\n"
                "(troque 'python' pela linguagem real que você usou)")
    base = (f"Contexto do acervo (use como referência técnica se ajudar):\n{ctx}\n\n" if ctx else "")
    try:
        if prov:
            mq, mapping = mask_reversible(instr)
            raw = demask(_strip_think(chat_model(prov, [{"role": "system", "content": sysp},
                        {"role": "user", "content": base + "Pedido:\n" + mq}], max_tokens=2800) or ""), mapping)
        else:
            raw = _strip_think(chat_model("chat", [{"role": "system", "content": sysp},
                        {"role": "user", "content": base + "Pedido:\n" + instr}], max_tokens=2800) or "")
    except Exception as e:
        return JSONResponse(status_code=502, content={"error": "falha ao gerar o código", "detail": str(e)[:200]})
    blocks = [b.strip() for b in _code_blocks(raw) if b.strip()]
    ml = re.search(r"```([a-zA-Z0-9_+.\-]+)", raw)
    lang = (ml.group(1) if ml else "python")
    if lang.lower() in ("lang", "linguagem", "<lang>", "<linguagem>", "code", "código", "codigo"):
        lang = "python"                                 # o modelo às vezes copia o placeholder do formato
    fontes = sorted({h.payload.get("source", "?") for h in hits})
    modelo = prov or "local (qwen)"
    codigo = max(blocks, key=len).strip() if blocks else ""
    completo = (blocks[2] if len(blocks) >= 3 else (blocks[-1] if blocks else "")).strip()
    # O modelo pode RECUSAR ou responder sem código (ex.: pedido que ele considera impróprio).
    # Não fingir que gerou código: devolve a mensagem crua para o chat exibir normalmente (honesto).
    tem_saida = (len(completo) >= 20) if ajuste else (len(codigo) >= 20)
    if not tem_saida:
        msg = (_code_field(raw, "EXPLICACAO") or _code_field(raw, "PROBLEMA") or (raw or "").strip()
               or "O modelo não retornou código para este pedido.")
        _event("código · sem saída", instr[:50])
        return {"modo": "sem_codigo", "mensagem": msg[:1500], "modelo": modelo, "fontes": fontes}
    if ajuste:
        _event("código · ajuste", instr[:50])
        return {"modo": "ajuste", "linguagem": lang, "problema": _code_field(raw, "PROBLEMA"),
                "antes": (blocks[0].strip() if len(blocks) >= 1 else ""), "depois": (blocks[1].strip() if len(blocks) >= 2 else ""),
                "explicacao": _code_field(raw, "EXPLICACAO"), "completo": completo,
                "fontes": fontes, "modelo": modelo}
    _event("código · novo", instr[:50])
    return {"modo": "novo", "linguagem": lang, "codigo": codigo,
            "explicacao": _code_field(raw, "EXPLICACAO"), "fontes": fontes, "modelo": modelo}


# ---- ações prontas sobre o acervo (resumir / riscos / extrair) ----
class AcaoReq(BaseModel):
    acao: str
    colecao: str = COLLECTION
    colecoes: list | None = None


@app.post("/acao")
def acao(body: AcaoReq):
    colls = _colls_of(body) or [COLLECTION]
    ctx, srcs = "", set()
    try:
        for coll in colls:
            pts, _ = qdrant.scroll(collection_name=coll, limit=40, with_payload=True, with_vectors=False)
            ctx += "\n\n".join((p.payload or {}).get("text", "") for p in pts) + "\n\n"
            srcs |= {(p.payload or {}).get("source", "?") for p in pts}
        ctx = ctx[:6000]
        fontes = sorted(srcs)
    except Exception:
        ctx, fontes = "", []
    if not ctx:
        return {"tipo": "documento", "conteudo": "_(coleção vazia — ingira documentos primeiro.)_", "fontes": [], "formato": "md"}
    A = {
        "resumir": ("md", "Resuma os documentos em Markdown: um título (#), pontos-chave em lista e uma conclusão objetiva. Português."),
        "riscos": ("md", "Liste em Markdown os principais riscos e pontos de atenção dos documentos numa tabela | Risco | Severidade | Observação |. Português."),
        "extrair": ("json", "Extraia os dados estruturados dos documentos em JSON válido (partes, valores, prazos, datas, documentos citados). Responda SOMENTE o JSON."),
        "auditoria": ("md",
            "Você é um AUDITOR SÊNIOR de compras públicas e contratos. Analise os documentos e produza um "
            "RELATÓRIO DE RISCOS DE LICITAÇÃO/CONTRATAÇÃO em Markdown, começando por um título (#) e um resumo de 2 linhas, "
            "seguido de uma tabela | Bandeira de risco | Evidência no documento | Severidade (Alta/Média/Baixa) | Recomendação |. "
            "Procure especificamente por: concentração/repetição de fornecedores; indícios de cartel ou rodízio de propostas; "
            "preços anômalos ou suspeitosamente próximos entre concorrentes; baixa competição (poucos participantes); "
            "direcionamento de edital (especificações restritivas); fracionamento para fugir de modalidade de licitação; "
            "aditivos, prazos ou valores fora do padrão; conflitos de interesse; ausência de justificativa/pesquisa de preços. "
            "Cite o trecho/fonte que embasa cada bandeira. NÃO invente: se não houver evidência de um item, não o inclua. "
            "Se os documentos não forem de compras/contratos, diga isso e aponte apenas riscos gerais observáveis. Português."),
    }
    fmt, instr = A.get(body.acao, A["resumir"])
    try:
        out, tokens = _gen_call([{"role": "system", "content": instr}, {"role": "user", "content": "Documentos:\n" + ctx}])
        out = _strip_think(out or "").strip()
        out = re.sub(r"^```[a-zA-Z]*\n?", "", out)
        out = re.sub(r"\n?```$", "", out).strip()
    except Exception as e:
        return JSONResponse(status_code=502, content={"error": "falha na ação", "detail": str(e)[:300]})
    _event("ação", f"{body.acao} · {coll}")
    return {"tipo": "documento", "conteudo": out, "tokens": tokens, "fontes": fontes, "formato": fmt}


# ---- adaptar linguagem: reescreve um texto em registro SIMPLES (leigo) ou TÉCNICO (especialista) ----
class AdaptarReq(BaseModel):
    texto: str
    modo: str = "simples"      # simples | tecnico


@app.post("/adaptar")
def adaptar(body: AdaptarReq):
    txt = (body.texto or "").strip()
    if not txt:
        return JSONResponse(status_code=400, content={"error": "sem texto para adaptar"})
    if body.modo == "tecnico":
        sysp = ("Reescreva o texto em LINGUAGEM TÉCNICA e precisa, para um público especialista: use a terminologia "
                "correta da área, seja rigoroso e conciso, explicite mecanismos, parâmetros e detalhes relevantes. "
                "Preserve o significado e NÃO invente fatos que não estejam no texto. Responda somente com o texto reescrito, em português.")
    else:
        sysp = ("Reescreva o texto em LINGUAGEM SIMPLES, acessível a qualquer pessoa (leigo): frases curtas, sem jargão, "
                "explicando termos difíceis com analogias do dia a dia. Preserve o significado e NÃO invente. "
                "Responda somente com o texto reescrito, em português.")
    try:
        out = _strip_think(chat_model("chat", [{"role": "system", "content": sysp},
                                               {"role": "user", "content": txt[:6000]}], max_tokens=1600) or "")
    except Exception as e:
        return JSONResponse(status_code=502, content={"error": "falha ao adaptar", "detail": str(e)[:200]})
    _event("adaptar linguagem", body.modo)
    return {"modo": body.modo, "texto": out.strip()}


# ---- classificação de intenção pelo próprio modelo (pergunta / documento / site / ambíguo) ----
class InterpretarReq(BaseModel):
    mensagem: str
    colecao: str = COLLECTION
    colecoes: list | None = None
    sem_opcoes: bool | None = False     # True quando a msg já é a resposta de uma escolha (não reoferecer opções)


@app.post("/interpretar")
def interpretar(body: InterpretarReq):
    """Roteador conversacional, ciente do acervo. Decide entre responder, esclarecer, perguntar, gerar."""
    colls = _colls_of(body)
    docs = set()
    try:
        for coll in colls:
            pts, _ = qdrant.scroll(collection_name=coll, limit=200, with_payload=True, with_vectors=False)
            docs |= {(p.payload or {}).get("source", "?") for p in pts}
    except Exception:
        pass
    docs = sorted(docs)
    doclist = ", ".join(docs) if docs else ("(conversa sem acervo — pode responder livremente)" if not colls else "(nenhum documento neste projeto ainda)")
    sys = ("Você é o roteador do copiloto do Cerne (plataforma da Orqion); nunca diga que foi criado por outra empresa. Ele trabalha SOBRE os documentos de um projeto. "
           f"DOCUMENTOS disponíveis no projeto: {doclist}. "
           "Analise a MENSAGEM do usuário e escolha UMA ação:\n"
           "- perguntar: pergunta cujo conteúdo está (ou deveria estar) nos documentos.\n"
           "- responder: saudação, agradecimento, ou pergunta sobre o que você CONSEGUE fazer (capacidades).\n"
           "- esclarecer: a pessoa quer gerar um documento ou site, mas o pedido está VAGO (falta assunto, tipo, ou qual documento usar).\n"
           "- documento: pedido CLARO de gerar um texto/documento, com assunto definido.\n"
           "- site: pedido CLARO de gerar uma página/site, com assunto definido.\n"
           "Responda EXATAMENTE em duas linhas:\n"
           "ACAO: <perguntar|responder|esclarecer|documento|site>\n"
           "TEXTO: <se for responder ou esclarecer, escreva a mensagem ao usuário: explique brevemente o que você faz e/ou faça 1-2 perguntas objetivas, citando os documentos disponíveis quando útil. Caso contrário, deixe vazio>")
    try:
        raw = _strip_think(chat_model("chat", [{"role": "system", "content": sys},
                                               {"role": "user", "content": body.mensagem}]) or "")
    except Exception:
        raw = ""
    ma = re.search(r"ACAO\s*:\s*([A-Za-zçãíé]+)", raw, re.I)
    acao = (ma.group(1).lower() if ma else "")
    mt = re.search(r"TEXTO\s*:\s*(.*)", raw, re.I | re.S)
    texto = (mt.group(1).strip() if mt else "")
    if "site" in acao:
        intent = "site"
    elif "document" in acao:
        intent = "documento"
    elif "esclar" in acao:
        intent = "esclarecer"
    elif "respond" in acao:
        intent = "responder"
    else:
        intent = "perguntar"
    if intent in ("responder", "esclarecer") and not texto:
        texto = ("Consigo responder sobre os documentos deste projeto e gerar documentos ou sites com base neles. "
                 "Me diga o assunto e o tipo — ex.: um resumo do contrato, ou uma landing page sobre o serviço. "
                 f"Documentos disponíveis: {doclist}.")
    # oferece opções de escolha quando o pedido pode ser especificado melhor (o gerador decide se cabem)
    if intent in ("esclarecer", "documento", "site") and not body.sem_opcoes:
        esc = _gerar_opcoes(body.mensagem, doclist)
        if esc.get("opcoes"):
            return {"intent": "escolher", "texto": esc["pergunta"], "opcoes": esc["opcoes"], "docs": docs}
    return {"intent": intent, "texto": texto, "docs": docs}


