  x.beginPath();x.arc(cx,cy,13,0,7);x.fillStyle="#35e0e6";x.shadowColor="#35e0e6";x.shadowBlur=16;x.fill();x.shadowBlur=0;x.fillStyle="#04212a";x.font="bold 9px ui-monospace,monospace";x.textAlign="center";x.fillText("CERNE",cx,cy+3);
